func_x3tDc.functionBody:
const user = String({{ b_sxS5R['value'] }} || '').toLowerCase();
const chosen = {{ var_5vIKk['value'] }} || {};
const mode = String({{ var_Dl887['value'] }} || 'View');
const order = ['Tasks', 'Sequences'];
const access = order.filter(function (key) {
  return chosen[key] === true;
});
const from = {{ b_rIYJN['value'] }};
const to = {{ b_PZU7t['value'] }};
const reason = ({{ b_uZhD4['value'] }} || '').trim();

function niceName(email) {
  const local = String(email).split('@')[0];
  return local
    .split(/[._-]+/)
    .filter(function (part) { return part; })
    .map(function (part) { return part.charAt(0).toUpperCase() + part.slice(1); })
    .join(' ');
}

function dayParts(ms) {
  const d = new Date(ms);
  if (ms % 86400000 === 0) {
    return [d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()];
  }
  return [d.getFullYear(), d.getMonth(), d.getDate()];
}

function dayStart(ms) {
  const p = dayParts(ms);
  return new Date(p[0], p[1], p[2], 0, 0, 0, 0).getTime();
}

function dayEnd(ms) {
  const p = dayParts(ms);
  return new Date(p[0], p[1], p[2], 23, 59, 59, 999).getTime();
}

const fromMs = typeof from === 'number' ? dayStart(from) : null;
const toMs = typeof to === 'number' ? dayEnd(to) : null;

let error = '';
if (!user) {
  error = 'Select who gets access.';
} else if (!access.length) {
  error = 'Pick Tasks, Sequences or both.';
} else if (!fromMs || !toMs || toMs < fromMs) {
  error = 'Pick a start date and an end date after it.';
} else if (toMs < Date.now()) {
  error = 'Pick an end date that is today or later.';
} else if (!reason) {
  error = 'Add a reason.';
}

function formatDay(ms, withYear) {
  const options = { day: 'numeric', month: 'short' };
  if (withYear) {
    options.year = 'numeric';
  }
  return new Date(ms).toLocaleDateString('en-GB', options);
}

const name = user ? niceName(user) : '';

return {
  ok: !error,
  error: error,
  user: name,
  accessText: access.join(', '),
  reason: reason,
  when: fromMs && toMs ? formatDay(fromMs, false) + ' – ' + formatDay(toMs, true) : '',
  toText: toMs ? formatDay(toMs, true) : '',
  payload: {
    granteeEmail: user,
    granteeName: name,
    mode: mode.toLowerCase() === 'edit' ? 'edit' : 'view',
    scopes: access.map(function (key) { return key.toLowerCase(); }),
    fromDate: fromMs,
    toDate: toMs,
    reason: reason,
  },
};

func_fYhn8.functionBody:
const data = {{ e_6ae05e69b373722e3cfdf953['data'] }} || {};
const rows = data['objects'] || [];
const me = String({{ userContext['email'] }} || '').toLowerCase();

function niceName(email) {
  const local = String(email).split('@')[0];
  return local
    .split(/[._-]+/)
    .filter(function (part) { return part; })
    .map(function (part) { return part.charAt(0).toUpperCase() + part.slice(1); })
    .join(' ');
}

const seen = {};
const byEmail = {};
const options = [];
rows.forEach(function (row) {
  const props = row['properties'] || {};
  const email = String(props['owner_id'] || row['id'] || '').trim().toLowerCase();
  if (!email || email.indexOf('@') < 1 || seen[email]) {
    return;
  }
  if (props['isActive'] === false || email === me) {
    return;
  }
  seen[email] = true;
  const name = niceName(email);
  byEmail[email] = name;
  options.push({ value: email, label: name });
});
options.sort(function (a, b) { return a.label.localeCompare(b.label); });

return {
  options: options,
  byEmail: byEmail,
};

func_7KZic.functionBody:
const ds = {{ e_6ae05e6933138b70edce68ab['data'] }};
const dsError = {{ e_6ae05e6933138b70edce68ab['error'] }};
const filter = {{ var_jNh2O['value'] }} || 'All';
const res = ds || {};
const loading = !ds && !dsError;
const failed = !!dsError || (!!ds && res['ok'] === false);
let failMessage = '';
if (dsError) {
  failMessage = dsError['message'] || 'Please try again.';
} else if (failed) {
  failMessage = res['message'] || 'Please try again.';
}

function day(ms, withYear) {
  if (typeof ms !== 'number') {
    return '—';
  }
  const options = { day: 'numeric', month: 'short' };
  if (withYear) {
    options.year = 'numeric';
  }
  return new Date(ms).toLocaleDateString('en-GB', options);
}

function scopeText(list) {
  const names = { tasks: 'Tasks', sequences: 'Sequences' };
  const text = (list || []).map(function (key) { return names[key] || key; }).join(', ');
  return text || '—';
}

function toRow(grant, direction) {
  const state = grant['state'] || 'Ended';
  const given = direction === 'given';
  const person = given
    ? (grant['granteeName'] || grant['granteeEmail'] || 'Someone')
    : (grant['grantorName'] || grant['grantorEmail'] || 'Someone');
  return {
    id: grant['id'],
    who: (given ? 'To ' : 'From ') + person,
    type: given
      ? 'You gave · ' + (grant['granteeEmail'] || '')
      : 'Given to you · ' + (grant['grantorEmail'] || ''),
    access: scopeText(grant['scopes']) + ' · ' + (grant['mode'] === 'edit' ? 'Edit' : 'View'),
    when: day(grant['fromDate'], false) + ' – ' + day(grant['toDate'], true),
    reason: grant['reason'] || '—',
    status: state,
    canRevoke: given && (state === 'Active' || state === 'Scheduled') ? 'yes' : 'no',
    revokeName: person,
    sortKey: grant['createdTime'] || grant['fromDate'] || 0,
  };
}

const all = (failed ? [] : (res['given'] || []))
  .map(function (grant) { return toRow(grant, 'given'); })
  .concat((failed ? [] : (res['received'] || [])).map(function (grant) { return toRow(grant, 'received'); }));
all.sort(function (a, b) { return b.sortKey - a.sortKey; });

function isOpen(row) {
  return row.status === 'Active' || row.status === 'Scheduled';
}
const active = all.filter(isOpen);
const ended = all.filter(function (row) { return !isOpen(row); });

let visible = all;
if (filter === 'Active') {
  visible = active;
} else if (filter === 'Ended') {
  visible = ended;
}

let emptyText = 'Nothing here for this filter.';
if (loading) {
  emptyText = 'Loading access…';
} else if (failed) {
  emptyText = "Couldn't load access. " + failMessage;
} else if (!all.length) {
  emptyText = 'No temporary access given yet.';
}

return {
  rows: visible,
  counts: {
    all: all.length,
    active: active.length,
    ended: ended.length,
  },
  loading: loading,
  failed: failed,
  emptyText: emptyText,
};

