const countrySource = {{ e_6adf9ca7fe800f2db80685b6 }} || {};
const zoneSource = {{ e_6adf9ca7fe800f2db80685b4 }} || {};

function readValue(row, alias) {
  if (!row || typeof row !== 'object') {
    return '';
  }
  const holder = row['columns'] && typeof row['columns'] === 'object' ? row['columns'] : row;
  let value = holder[alias];
  if (value && typeof value === 'object' && 'value' in value) {
    value = value['value'];
  }
  return value === null || value === undefined ? '' : String(value).trim();
}

function toOptions(source, alias) {
  const data = source['data'];
  const rows = data && Array.isArray(data['objects']) ? data['objects'] : [];
  const seen = {};
  const values = [];
  rows.forEach(function (row) {
    const value = readValue(row, alias);
    if (value && !seen[value]) {
      seen[value] = true;
      values.push(value);
    }
  });
  values.sort(function (left, right) {
    return left.localeCompare(right);
  });
  let state = 'ready';
  if (source['error']) {
    state = 'error';
  } else if (!data || source['isLoading'] === true) {
    state = 'loading';
  } else if (!values.length) {
