const S = {{ var_CrrjU['value'] }} || {};
const saved = {{ var_KSbLC['value'] }} || {};
const filter = {{ var_SDyZd['value'] }} || 'upcoming';
const orgSource = {{ e_6adfb12db373722e3c95f66c }} || {};
const holidaySource = {{ e_6adfb12d33138b70ed6472ca }} || {};
const statusSource = {{ e_6adfb12d33138b70ed6472cc }} || {};
const repSource = {{ e_6adfb12dfe800f2db80dbfea }} || {};
const sendsSource = {{ e_6adfb12db373722e3c95f66b }} || {};

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const DAY_ORDER = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const pad = function (n) { return String(n).padStart(2, '0'); };
const now = new Date();
const todayIso = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());

function stateOf(source) {
  if (source['error']) {
    return 'error';
  }
  if (!source['data'] || source['isLoading'] === true) {
    return 'loading';
  }
  return 'ready';
}

function rowsOf(source) {
  const data = source['data'];
  return data && Array.isArray(data['objects']) ? data['objects'] : [];
}

function readColumn(row, alias) {
  const holder = row && row['columns'] && typeof row['columns'] === 'object' ? row['columns'] : (row || {});
  let value = holder[alias];
  if (value && typeof value === 'object' && 'value' in value) {
    value = value['value'];
  }
  return value;
}

function formatDate(iso) {
  const parts = String(iso || '').split('-');
  if (parts.length < 3) {
    return String(iso || '');
  }
  const d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
  return d.getDate() + ' ' + MONTHS[d.getMonth()] + ' ' + d.getFullYear() + ' · ' + WEEKDAYS[d.getDay()];
}

function formatStamp(ms) {
  if (!ms) {
    return '';
  }
  const d = new Date(Number(ms));
  return d.getDate() + ' ' + MONTHS[d.getMonth()] + ' ' + d.getFullYear() + ', ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}

function nameFromEmail(email) {
  const local = String(email || '').split('@')[0];
  if (!local) {
    return '—';
  }
  return local.split(/[._-]+/).filter(Boolean).map(function (w) {
    return w.charAt(0).toUpperCase() + w.slice(1);
  }).join(' ');
}

// Settings row
const orgState = stateOf(orgSource);
const orgRow = rowsOf(orgSource)[0] || null;
const orgProps = (orgRow && orgRow['properties']) || {};
let settingsLine = '';
if (orgState === 'loading') {
  settingsLine = 'Loading saved settings…';
} else if (orgState === 'error') {
  settingsLine = "Couldn't load the saved settings, so defaults are shown. Reload the page before saving.";
} else if (!orgRow) {
  settingsLine = 'Not saved yet. These are the defaults every sequence uses today.';
} else {
  settingsLine = 'Last saved ' + formatStamp(orgProps['updatedAt'] || orgRow['modifiedTime']) + '.';
}

// Holidays
const holidayState = stateOf(holidaySource);
const holidays = rowsOf(holidaySource).map(function (r) {
  const p = r['properties'] || {};
  const scope = p['appliesTo'] === 'time_zones' ? 'zones' : (p['appliesTo'] || 'all');
  return {
    id: r['id'],
    name: p['holidayName'] || '',
    date: p['holidayDate'] || '',
    scope: scope,
    targets: scope === 'countries' ? (p['countries'] || []) : (scope === 'zones' ? (p['timeZones'] || []) : []),
    by: p['addedByName'] || p['addedByEmail'] || '—'
  };
});
const sorted = holidays.slice().sort(function (a, b) { return String(a.date) < String(b.date) ? -1 : 1; });
const upcoming = sorted.filter(function (h) { return String(h.date) >= todayIso; });
const shown = filter === 'all' ? sorted : upcoming;
const holidayRows = shown.map(function (h) {
  const targets = (h.targets || []).join(', ');
  return {
    id: h.id,
    name: h.name,
    date: h.date,
    dateLabel: formatDate(h.date),
    scope: h.scope,
    scopeLabel: h.scope === 'all' ? 'All countries & time zones' : (h.scope === 'countries' ? 'Countries: ' : 'Time zones: ') + targets,
    by: h.by
  };
});
let holidayEmptyTitle = filter === 'all' ? 'No holidays yet' : 'No upcoming holidays';
let holidayEmptySubtitle = 'Add one so sequences skip that day.';
if (holidayState === 'loading') {
  holidayEmptyTitle = 'Loading holidays…';
  holidayEmptySubtitle = '';
} else if (holidayState === 'error') {
  holidayEmptyTitle = "Couldn't load holidays";
  holidayEmptySubtitle = 'Reload the page to try again.';
}

// Validation of the draft settings
const errors = [];
const dailyRaw = String(S.dailyEmails == null ? '' : S.dailyEmails).trim();
const daily = Number(dailyRaw);
const dailyValid = dailyRaw !== '' && Number.isInteger(daily) && daily >= 1 && daily <= 2000;
if (!dailyValid) { errors.push('daily'); }
const gapRaw = String(S.gapMin == null ? '' : S.gapMin).trim();
const gap = Number(gapRaw);
const gapValid = gapRaw !== '' && isFinite(gap) && gap >= 0 && gap <= 60;
if (!gapValid) { errors.push('gap'); }

const toMinutes = function (t) {
  const p = String(t || '0:0').split(':');
  return Number(p[0]) * 60 + Number(p[1] || 0);
};
const ws = toMinutes(S.winStart);
const we = toMinutes(S.winEnd);
const winError = we <= ws;
if (winError) { errors.push('window'); }
const winHours = Math.max(0, (we - ws) / 60);

const days = DAY_ORDER.filter(function (d) { return (S.days || []).indexOf(d) >= 0; });
const daysError = days.length === 0;
if (daysError) { errors.push('days'); }

const bounceRaw = String(S.bounceTh == null ? '' : S.bounceTh).trim();
const bounceTh = Number(bounceRaw);
const bounceValid = bounceRaw !== '' && isFinite(bounceTh) && bounceTh >= 0 && bounceTh <= 100;
if (!bounceValid) { errors.push('bounce'); }
const spamRaw = String(S.spamTh == null ? '' : S.spamTh).trim();
const spamTh = Number(spamRaw);
const spamValid = spamRaw !== '' && isFinite(spamTh) && spamTh >= 0 && spamTh <= 100;
if (!spamValid) { errors.push('spam'); }

// Mailboxes: reps' mailboxIds joined to Mailbox Status and today's sends
const statusState = stateOf(statusSource);
const repState = stateOf(repSource);
const sendsState = stateOf(sendsSource);
const mailboxState = statusState === 'error' || repState === 'error' ? 'error' : (statusState === 'loading' || repState === 'loading' ? 'loading' : 'ready');

const statusById = {};
rowsOf(statusSource).forEach(function (r) {
  const p = r['properties'] || {};
  const key = p['mailboxId'] || r['id'];
  if (key) {
    statusById[key] = p;
  }
});
const sendsById = {};
rowsOf(sendsSource).forEach(function (r) {
  const key = readColumn(r, 'connectionId');
  if (key) {
    sendsById[key] = Number(readColumn(r, 'sends')) || 0;
  }
});

const boxes = [];
const seen = {};
rowsOf(repSource).forEach(function (r) {
  const p = r['properties'] || {};
  const ids = Array.isArray(p['mailboxIds']) ? p['mailboxIds'].filter(Boolean) : [];
  ids.forEach(function (mailboxId, i) {
    if (seen[mailboxId]) {
      return;
    }
    seen[mailboxId] = true;
    boxes.push({ id: mailboxId, ownerEmail: String(p['owner_id'] || '').toLowerCase(), cap: p['dailySendCap'], index: i, count: ids.length });
  });
});
Object.keys(statusById).forEach(function (mailboxId) {
  if (!seen[mailboxId]) {
    seen[mailboxId] = true;
    boxes.push({ id: mailboxId, ownerEmail: String(statusById[mailboxId]['ownerEmail'] || '').toLowerCase(), cap: null, index: 0, count: 1 });
  }
});

const STATUS_LABEL = { active: 'Active', paused: 'Paused', auto_paused: 'Auto-paused' };
const mailboxRows = boxes.map(function (b) {
  const st = statusById[b.id] || {};
  const code = st['status'] || 'active';
  const rate = st['bounceRate7d'];
  const bounce = rate === null || rate === undefined || rate === '' ? null : Math.round(Number(rate) * 10) / 10;
  const over = bounce != null && bounceValid && bounce > bounceTh;
  const capNumber = Number(b.cap);
  const limit = dailyValid ? (capNumber > 0 ? Math.min(daily, capNumber) : daily) : null;
  const sends = sendsById[b.id] || 0;
  const sendsText = sendsState === 'ready' ? String(sends) : '—';
  let note = 'Connection …' + String(b.id).slice(-8);
  if (code === 'auto_paused') {
    if (st['pausedReason'] === 'spam_complaints') {
      const spamRate = st['spamRate7d'];
      note = 'Auto-paused: spam complaints ' + (spamRate == null ? '' : spamRate + '% ') + 'over ' + (spamValid ? spamTh : '—') + '%';
    } else {
      note = 'Auto-paused: bounce ' + (bounce == null ? '' : bounce + '% ') + 'over ' + (bounceValid ? bounceTh : '—') + '%';
    }
  } else if (code === 'paused') {
    note = 'Paused by ' + (st['pausedByEmail'] || 'an admin') + (st['pausedAt'] ? ' · ' + formatStamp(st['pausedAt']) : '');
  } else if (b.count > 1) {
    note = 'Mailbox ' + (b.index + 1) + ' of ' + b.count + ' · …' + String(b.id).slice(-8);
  }
  return {
    id: b.id,
    email: b.ownerEmail || b.id,
    ownerEmail: b.ownerEmail,
    owner: nameFromEmail(b.ownerEmail),
    status: STATUS_LABEL[code] || 'Active',
    statusCode: code,
    sends: sends,
    sendsLabel: sendsText + ' / ' + (limit == null ? (dailyRaw || '—') : limit),
    bounce: bounce,
    bounceLabel: bounce == null ? '—' : bounce + '%',
    over: over,
    rot: true,
    note: note
  };
});
const bounceOver = mailboxRows.filter(function (m) { return m.over; }).length;
let mailboxEmptyMessage = 'No mailboxes connected yet. A rep’s Outlook mailbox shows here once it is connected.';
if (mailboxState === 'loading') {
  mailboxEmptyMessage = 'Loading mailboxes…';
} else if (mailboxState === 'error') {
  mailboxEmptyMessage = "Couldn't load mailboxes. Reload the page to try again.";
}

const LABELS = {
  dailyEmails: 'Daily emails per mailbox',
  gapMin: 'Gap between automatic emails',
  winStart: 'Org send window · start',
  winEnd: 'Org send window · end',
  days: 'Org working days',
  bounceTh: 'Auto-pause · bounce rate',
  spamTh: 'Auto-pause · spam complaints'
};
const dirtyKeys = Object.keys(LABELS).filter(function (k) {
  return JSON.stringify(S[k]) !== JSON.stringify(saved[k]);
});
const dirtyLabels = dirtyKeys.map(function (k) { return LABELS[k]; });
const listText = dirtyLabels.slice(0, 2).join(', ') + (dirtyLabels.length > 2 ? ' and ' + (dirtyLabels.length - 2) + ' more' : '');
const dirtyText = dirtyKeys.length + ' unsaved change' + (dirtyKeys.length === 1 ? '' : 's') + ' · ' + listText;

const perHour = gap > 0 ? Math.floor(60 / gap) : null;

return {
  orgState: orgState,
  settingsLine: settingsLine,
  savePayload: {
    dailyEmailsPerMailbox: daily,
    minGapMinutes: gap,
    sendWindowStart: S.winStart,
    sendWindowEnd: S.winEnd,
    workingDays: days,
    bounceThresholdPct: bounceTh,
    spamThresholdPct: spamTh
  },
  holidayState: holidayState,
  holidayRows: holidayRows,
  holidayCount: holidayRows.length,
  upcomingCount: upcoming.length,
  holidayEmptyTitle: holidayEmptyTitle,
  holidayEmptySubtitle: holidayEmptySubtitle,
  dailyValid: dailyValid,
  dailyLine: dailyValid ? 'Email ' + (daily + 1) + ' goes out on the next working day.' : 'Enter a whole number from 1 to 2000.',
  gapValid: gapValid,
  gapLine: gapValid ? (perHour ? 'At ' + gap + ' min, one mailbox sends at most ' + perHour + ' emails an hour.' : 'At 0 min, emails from one mailbox go out back to back.') : 'Enter a number of minutes from 0 to 60.',
  winError: winError,
  winLeft: (ws / 1440 * 100).toFixed(2) + '%',
  winWidth: Math.max(0, (we - ws) / 1440 * 100).toFixed(2) + '%',
  windowLine: winError ? 'The end time must be after the start time.' : 'Sends between ' + S.winStart + ' and ' + S.winEnd + " in each prospect's time · " + winHours + ' hours a day.',
  days: days,
  daysError: daysError,
  daysLine: daysError ? 'Pick at least one working day, or no automatic email can go out.' : days.length + ' working day' + (days.length === 1 ? '' : 's') + ' · ' + days.join(', '),
  bounceValid: bounceValid,
  bounceOver: bounceOver,
  bounceLine: bounceValid ? 'The mailbox stops sending and its owner is told. ' + bounceOver + (bounceOver === 1 ? ' mailbox is' : ' mailboxes are') + ' over this limit now.' : 'Enter a percentage from 0 to 100.',
  spamValid: spamValid,
  spamLine: spamValid ? 'Needs complaint events from the email provider.' : 'Enter a percentage from 0 to 100.',
  mailboxState: mailboxState,
  mailboxRows: mailboxRows,
  mailboxEmptyMessage: mailboxEmptyMessage,
  dirtyCount: dirtyKeys.length,
  dirtyText: dirtyText,
  hasErrors: errors.length > 0
};

