const rows = {{var_2lqqp['value']}} || [];
const tab = {{var_rdwpB['value']}} || 'All';
const person = {{var_Hghwv['value']}} || 'All';

// Map each change to one of the four admin tabs.
// Rules rows split by section; Users & access rows only survive for Temporary access.
const complianceSections = ['Compliance', 'Call settings'];
function tabOf(row) {
  const t = row['tab'];
  if (t === 'rules') {
    return complianceSections.indexOf(row['section']) >= 0 ? 'compliance' : 'enrolment';
  }
  if (t === 'users') {
    return row['section'] === 'Temporary access' ? 'users' : null;
  }
  return t;
}

const all = rows
  .map(function (row) { return Object.assign({}, row, { tab: tabOf(row) }); })
  .filter(function (row) { return row['tab'] !== null; });

