func_Gsb7S.functionBody:
const rows = {{ e_6adcb7330881d2257a36cb5e['data']['meetings'] }} || [];
const monday = {{ func_jlrue['value']['startEpoch'] }} || 0;
const H0 = 0;
const H1 = 24;
const DAY_MS = 24 * 60 * 60 * 1000;
const now = Date.now();

const byDay = [[], [], [], [], [], [], []];
rows.forEach(function (m) {
  var d = Math.floor((m.startEpochOfCall - monday) / DAY_MS);
  if (d >= 0 && d <= 6) {
    byDay[d].push(m);
  }
});

var nextId = null;
var nextStart = Infinity;
rows.forEach(function (m) {
  if (m.endEpochOfCall > now && m.startEpochOfCall < nextStart) {
    nextStart = m.startEpochOfCall;
    nextId = m.id;
  }
});

var todayStart = new Date(now);
todayStart.setHours(0, 0, 0, 0);
var todayIdx = Math.round((todayStart.getTime() - monday) / DAY_MS);
var nowHour = ((now - monday) % DAY_MS) / (60 * 60 * 1000);
var nowTopPct = ((nowHour - H0) / (H1 - H0)) * 100;

function layoutDay(list) {
  var sorted = list.slice().sort(function (a, b) {
    return a.startEpochOfCall - b.startEpochOfCall;
  });
  var n = sorted.length;
  var parent = [];
  for (var i = 0; i < n; i++) {
    parent.push(i);
  }
  function find(x) {
    while (parent[x] !== x) {
      x = parent[x];
    }
    return x;
  }
  function union(a, b) {
    var ra = find(a);
    var rb = find(b);
    if (ra !== rb) {
      parent[ra] = rb;
    }
  }
  for (var i = 0; i < n; i++) {
    for (var j = i + 1; j < n; j++) {
      if (sorted[i].startEpochOfCall < sorted[j].endEpochOfCall && sorted[j].startEpochOfCall < sorted[i].endEpochOfCall) {
        union(i, j);
      }
    }
  }
  var groups = {};
  for (var i = 0; i < n; i++) {
    var r = find(i);
    if (!groups[r]) {
      groups[r] = [];
    }
    groups[r].push(i);
  }
  var colOf = {};
  var maxColOf = {};
  Object.keys(groups).forEach(function (gk) {
    var idxs = groups[gk];
    var active = [];
    var maxCol = 1;
    idxs.forEach(function (idx) {
      var m = sorted[idx];
      active = active.filter(function (a) {
        return a.end > m.startEpochOfCall;
      });
      var used = active.map(function (a) {
        return a.col;
      });
      var c = 0;
      while (used.indexOf(c) !== -1) {
        c++;
      }
      colOf[idx] = c;
      active.push({ end: m.endEpochOfCall, col: c });
      if (c + 1 > maxCol) {
        maxCol = c + 1;
      }
    });
    idxs.forEach(function (idx) {
      maxColOf[idx] = maxCol;
    });
  });

  return sorted.map(function (m, idx) {
    var sHour = ((m.startEpochOfCall - monday) % DAY_MS) / (60 * 60 * 1000);
    var eHour = sHour + (m.endEpochOfCall - m.startEpochOfCall) / (60 * 60 * 1000);
    var clipS = Math.max(sHour, H0);
    var clipE = Math.min(eHour, H1);
    var durMin = Math.round((m.endEpochOfCall - m.startEpochOfCall) / 60000);
    var cols = maxColOf[idx] || 1;
    var col = colOf[idx] || 0;
    var widthPct = 100 / cols;
    var startLabel = new Date(m.startEpochOfCall).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    var endLabel = new Date(m.endEpochOfCall).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    return {
      id: m.id,
      title: m.title || 'Meeting',
      prospectName: m.prospectName || '',
      accountName: m.accountName || '',
      meetingUrl: m.meetingUrl || '',
      startEpochOfCall: m.startEpochOfCall,
      endEpochOfCall: m.endEpochOfCall,
      durationMin: durMin,
      top: Math.max(((clipS - H0) / (H1 - H0)) * 100, 0),
      height: Math.max(((clipE - clipS) / (H1 - H0)) * 100, 2),
      left: col * widthPct,
      width: widthPct,
      isPast: m.endEpochOfCall <= now,
      isNext: m.id === nextId,
      showTime: durMin >= 45,
      showProspect: durMin >= 60,
      timeLabel: startLabel + ' – ' + endLabel,
      tooltip: (m.title || 'Meeting') + ' · ' + startLabel + ' – ' + endLabel + (m.prospectName ? ' · ' + m.prospectName : ''),
    };
  });
}

return {
  day0: layoutDay(byDay[0]),
  day1: layoutDay(byDay[1]),
  day2: layoutDay(byDay[2]),
  day3: layoutDay(byDay[3]),
  day4: layoutDay(byDay[4]),
  day5: layoutDay(byDay[5]),
  day6: layoutDay(byDay[6]),
  todayIdx: todayIdx,
  nowTopPct: nowTopPct,
  startEpoch: monday,
};

