func_jlrue.functionBody:
const offset = {{ var_PQxHS['value'] }} || 0;
const now = new Date();
const day = now.getDay();
const diffToMonday = day === 0 ? -6 : 1 - day;
const monday = new Date(now.getFullYear(), now.getMonth(), now.getDate() + diffToMonday + offset * 7);
monday.setHours(0, 0, 0, 0);
const sunday = new Date(monday.getTime() + 7 * 24 * 60 * 60 * 1000 - 1);
const fmt = function (d) {
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
};
const label = fmt(monday) + ' – ' + sunday.getDate() + ', ' + sunday.getFullYear();
return {
  startEpoch: monday.getTime(),
  endEpoch: sunday.getTime(),
  label: label,
};

func_9ceYU.functionBody:
const monday = {{ func_jlrue['value']['startEpoch'] }} || 0;
const DAY_MS = 24 * 60 * 60 * 1000;
const today = new Date();
today.setHours(0, 0, 0, 0);
const todayTs = today.getTime();
const out = {};
for (let i = 0; i < 7; i++) {
  const ts = monday + i * DAY_MS;
  out['day' + i] = { date: new Date(ts).getDate(), isToday: ts === todayTs };
}
return out;

