// Overall Analytics: which panels have nothing to show.
// A panel is empty when its list is empty or every count in it is 0,
// because the automations return zero-filled rows for a quiet range.
var num = function (v) {
  var n = Number(v);
  return isNaN(n) ? 0 : n;
};
var allZero = function (rows, keys) {
  var list = Array.isArray(rows) ? rows : [];
  if (!list.length) {
    return true;
  }
  return list.every(function (r) {
    return keys.every(function (k) {
      return num((r || {})[k]) === 0;
    });
  });
};
var flag = function (b) {
  return b ? 'true' : 'false';
};
var s = {{ var_LOVry['value'] }} || {};
var labels = Array.isArray(s.labels) ? s.labels : [];
var points = [].concat(Array.isArray(s.current) ? s.current : [], Array.isArray(s.previous) ? s.previous : []);
var activityEmpty = !labels.length || points.every(function (v) {
  return num(v) === 0;
});

return {
  activity: flag(activityEmpty),
  tasks: flag(allZero({{ var_lBFOu['value'] }}, ['completed', 'skipped', 'overdue'])),
  calls: flag(allZero({{ var_iMxQy['value'] }}, ['count'])),
  email: flag(allZero({{ var_UMNRZ['value'] }}, ['count'])),
  funnel: flag(allZero({{ var_gSVma['value'] }}, ['widthPct'])),
  sentiment: flag(allZero({{ var_B4A1u['value'] }}, ['pct'])),
  seniority: flag(allZero({{ var_103oN['value'] }}, ['pct'])),
};

