  ['left_voicemail', 'Left Voicemail'],
  ['gatekeeper', 'Gatekeeper'],
  ['bad_number', 'Bad Number'],
  ['no_longer_with_company', 'No Longer with Company'],
  ['answered_wrong_poc', 'Answered – Wrong Person'],
  ['answered_not_interested', 'Answered – Not Interested'],
  ['answered_referral', 'Answered – Referral'],
  ['answered_call_back', 'Answered – Call Back'],
  ['answered_meeting_set', 'Answered – Meeting Set'],
