const findTemplate = (res, id) => {
  const all = ((res || {})['templates']) || [];
  return (id && all.find((t) => t.templateId === id)) || {};
};
// HTML body to plain text, keeping line breaks and blank lines
const plain = (html) => String(html || '')
  .replace(/\r\n/g, '\n')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|h[1-6]|li|blockquote)>/gi, '\n')
  .replace(/<li[^>]*>/gi, '• ')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'")
  .replace(/&amp;/g, '&')
  .trim();
// Plain-text template body to editor HTML: one paragraph per line, an empty paragraph per blank line
const toHtml = (text) => {
  const raw = String(text || '');
  if (!raw || /<\/?(p|br|div|ul|ol|li|strong|b|em|i|a|span|h[1-6])\b/i.test(raw)) {
    return raw;
  }
  const esc = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return raw
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => '<p>' + esc(line) + '</p>')
