const toFiles = (a) => (Array.isArray(a) && a.length
  ? a.filter((f) => f && f.url).map((f, i) => ({ id: 'saved-' + i, name: f.name || 'file', url: f.url, sourceType: 'URL', isUploaded: true, progress: 100 }))
  : undefined);
const fill = (list, chosenId, templateId, res, prev) => {
  const rows = Array.isArray(list) ? list : [];
  const latest = rows[0] || null;
  const chosen = (chosenId && rows.find((v) => v.id === chosenId)) || latest;
  let subject = '';
  let body = '';
  if (chosen) {
    subject = chosen.subject || '';
    body = chosen.body || '';
  } else if (templateId) {
    const hit = findTemplate(res, templateId);
    const pv = prev && prev.id && prev.id === templateId ? (prev.properties || {}) : {};
    subject = pv.subject || hit.subject || '';
    body = pv.body || hit.body || '';
  }
  return {
    versionId: latest ? latest.id : undefined,
    chosenId: chosen ? chosen.id : undefined,
