};
const std = fill(versions.std, {{ b_KdWu8?.['data']?.['templateVersionId'] }}, {{ b_KdWu8?.['data']?.['templateId'] }}, tmpl, preview);
const ifTrue = fill(versions.ifTrue, {{ b_yMtEb?.['data']?.['templateVersionId'] }}, {{ b_yMtEb?.['data']?.['templateId'] }}, tmpl, preview);
const elseFill = fill(versions.else, {{ b_aL2ID?.['data']?.['templateVersionId'] }}, {{ b_aL2ID?.['data']?.['templateId'] }}, tmplElse, previewElse);
const isEdit = {{ var_CtMEb?.['value']?.['operation'] }} === 'edit_step';
const step = isEdit ? ({{ var_pCxV8?.['value'] }} || {}) : {};
const editTemplateId = {{ b_5Evnu?.['data']?.['templateId'] }};
const editChosenId = {{ b_5Evnu?.['data']?.['templateVersionId'] }};
const editBase = fill(versions.edit, editChosenId, editTemplateId, tmpl, preview);
