func_0sYpl.functionBody:
// Step config (design v4) for triggerCondition.ifTrue
const d = ({{ b_yMtEb?.['data'] }}) || {};
const top = ({{ b_sqpNo?.['data'] }}) || {};
const type = String(top.field5 || '').toLowerCase();
const list = (a) => (Array.isArray(a) ? a : (a ? [a] : []))
  .map((v) => String(v == null ? '' : v).trim())
  .filter((v) => v !== '');
// Cc, Bcc and attendees: comma-, semicolon- or space-separated text (or a list) to a list of addresses
const emails = (a) => (Array.isArray(a) ? a : [a])
  .flatMap((v) => String(v == null ? '' : v).split(/[,;\s]+/))
  .map((v) => v.trim())
  .filter((v) => v !== '');
const files = (a) => (Array.isArray(a) ? a : (a ? [a] : []))
  .filter((f) => f && f.url)
  .map((f) => ({ name: f.name || '', url: f.url }));
// Time picker value ("HH:mm:ss", or a typed "9:30 AM") to "HH:mm" (24h)
const hhmm = (t) => {
  const s = String(t == null ? '' : t).trim();
  const m = s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*([AaPp][Mm])?$/);
  if (!m) {
    return '';
  }
  let h = Number(m[1]);
  const ap = (m[3] || '').toLowerCase();
  if (ap === 'pm' && h < 12) {
    h += 12;
  }
  if (ap === 'am' && h === 12) {
    h = 0;
  }
  return String(h).padStart(2, '0') + ':' + m[2];
};
const out = {
