  };
  if (d.durationMin !== undefined && d.durationMin !== null && d.durationMin !== '') {
    out.meetingConfig.durationMin = Math.round(Number(d.durationMin));
  }
  const startTime = hhmm(d.meetingStartTime);
  if (startTime) {
    out.meetingConfig.startTime = startTime;
  }
}
if (type === 'linkedin') {
  out.linkedInConfig = {
    draftMessage: d.linkedInMessage || '',
  };
}
if (type === 'task') {
  const rows = Array.isArray(d.stepsToComplete) ? d.stepsToComplete : [];
  out.genericConfig = {
    stepsToComplete: rows
      .map((r) => ({
        stepname: String((r && r.stepname) || '').trim(),
        stepDesc: String((r && r.stepDesc) || '').trim(),
      }))
      .filter((r) => r.stepname !== ''),
    links: list(d.links),
