func_hDQ9F.functionBody:
// Conditional block: every earlier step as "Day N · Type · Title · Time", the conditions for each row's picked step type, the conditions to save, and the row add/remove helpers
const raw = {{ e_6a564c0fe37aa80dd4ab9c56?.['data']?.['previousSteps'] }};
const f = ({{ b_simvY?.['data'] }}) || {};
const MAX_ROWS = 5;
const count = Math.min(MAX_ROWS, Math.max(1, Number({{ var_TANQc?.['value'] }}) || 1));
// Call outcomes come from Admin Settings (sdr_sync_settings org_call_settings) through orgCallOutcomes (func_LqRAd): every outcome, hidden ones marked, stored by code.
const ORG_CALL = {{ func_LqRAd['value'] }} || {};
const ORG_CALL_LABELS = ORG_CALL.labels || {};
const ORG_CALL_PAIRS = (Array.isArray(ORG_CALL.options) && ORG_CALL.options.length ? ORG_CALL.options : [
  { id: 'no_answer', name: 'No Answer' },
  { id: 'left_voicemail', name: 'Left Voicemail' },
  { id: 'gatekeeper', name: 'Gatekeeper' },
  { id: 'bad_number', name: 'Bad Number' },
  { id: 'no_longer_with_company', name: 'No Longer with Company' },
  { id: 'answered_wrong_poc', name: 'Answered – Wrong Person' },
  { id: 'answered_not_interested', name: 'Answered – Not Interested' },
  { id: 'answered_referral', name: 'Answered – Referral' },
  { id: 'answered_call_back', name: 'Answered – Call Back' },
  { id: 'answered_meeting_set', name: 'Answered – Meeting Set' },
  { id: 'answered_other', name: 'Answered – Other' },
]).map(function (item) {
  return [item.id, item.name];
});
const typeLabels = {
  email: 'Email',
  call: 'Call',
  meeting: 'Meeting',
  linkedin: 'LinkedIn',
  task: 'Task',
};
const normType = (t) => {
  const s = String(t || '').toLowerCase();
  if (s.indexOf('linkedin') >= 0) {
    return 'linkedin';
  }
  if (s.indexOf('meeting') >= 0) {
    return 'meeting';
  }
  if (s.indexOf('call') >= 0) {
    return 'call';
  }
  if (s.indexOf('task') >= 0 || s.indexOf('generic') >= 0) {
    return 'task';
  }
  if (s.indexOf('mail') >= 0) {
    return 'email';
  }
  return '';
};
const steps = (Array.isArray(raw) ? raw : [])
  .map((s) => {
    const item = s || {};
    const type = normType(item.type || item.actionType || item.stepType);
    const day = (item.dayNumber !== undefined && item.dayNumber !== null && item.dayNumber !== '') ? item.dayNumber : item.day;
    const time = (item.time !== undefined && item.time !== null) ? String(item.time).trim() : '';
    const parts = [];
    if (day !== undefined && day !== null && day !== '') {
      parts.push('Day ' + day);
    }
    if (type) {
      parts.push(typeLabels[type]);
    }
    parts.push(item.title || item.stepTitle || 'Untitled step');
    if (time) {
      parts.push(time);
    }
    return {
      id: String(item.taskId || item.stepId || ''),
      type: type,
      time: time,
      label: parts.join(' · '),
    };
  })
  .filter((s) => s.id !== '');
// Label shown -> stored code (conditionName), per step type
const conditionsByType = {
  email: [['sent', 'Sent'], ['not-sent', 'Not sent'], ['opened', 'Opened'], ['not-opened', 'Not opened'], ['replied', 'Replied'], ['no-reply', 'Not replied'], ['bounced', 'Bounced']],
  call: [['call_done', 'Done'], ['call_not_done', 'Not done'], ['call_skipped', 'Skipped'], ['call_outcome', 'Outcome is …']],
  meeting: [['meeting_booked', 'Booked'], ['meeting_not_booked', 'Not booked'], ['meeting_held', 'Held'], ['meeting_no_show', 'No-show'], ['meeting_outcome', 'Outcome is …'], ['meeting_skipped', 'Skipped']],
  linkedin: [['linkedin_sent', 'Sent'], ['linkedin_not_sent', 'Not sent'], ['linkedin_skipped', 'Skipped']],
  task: [['task_done', 'Done'], ['task_not_done', 'Not done'], ['task_skipped', 'Skipped']],
};
const outcomesByCondition = {
  call_outcome: ORG_CALL_PAIRS,
  meeting_outcome: [['qualified', 'Qualified'], ['not_qualified', 'Not qualified'], ['opp_created', 'Opportunity created'], ['rescheduled', 'Rescheduled']],
};
// A saved call outcome code that is no longer in the list still counts and still shows as selected.
const pairsFor = (condition, picked) => {
  const base = outcomesByCondition[condition] || [];
  if (condition !== 'call_outcome') {
    return base;
  }
  const extra = (Array.isArray(picked) ? picked : [])
    .filter((code) => code && !base.some((p) => p[0] === code))
    .map((code) => [code, ORG_CALL_LABELS[code] || code]);
  return base.concat(extra);
};
const toOptions = (pairs) => pairs.map((p) => ({ value: p[0], label: p[1] }));
const rows = [];
for (let n = 1; n <= MAX_ROWS; n += 1) {
  rows.push({
    n: n,
    stepId: f['prevStep' + n],
    condition: f['condition' + n],
    outcomes: f['outcomes' + n],
    on: n <= count,
  });
}
const conditionOptions = [];
const outcomeOptions = [];
const conditions = [];
rows.forEach((row) => {
  const step = steps.find((s) => s.id === row.stepId);
  // A step whose type is unknown (older dropdown output) keeps the email conditions it always had
  const pairs = conditionsByType[(step && step.type) || 'email'];
  const codes = pairs.map((p) => p[0]);
  const outcomePairs = pairsFor(row.condition, row.outcomes);
  conditionOptions.push(toOptions(pairs));
  outcomeOptions.push(toOptions(outcomePairs));
  if (!row.on || !row.stepId || codes.indexOf(row.condition) < 0) {
    return;
  }
  let event = row.condition;
  if (outcomePairs.length) {
    const allowed = outcomePairs.map((p) => p[0]);
    const picked = (Array.isArray(row.outcomes) ? row.outcomes : []).filter((v) => allowed.indexOf(v) >= 0);
    if (!picked.length) {
      return;
    }
    event = row.condition + ':' + picked.join(',');
  }
  conditions.push({
    event: event,
    stepRef: row.stepId,
  });
});
// Removing row k moves every later row up one place; the last shown row is then emptied and hidden
// Outcomes are written a moment later (deleteShiftOutcomes), once the moved condition has shown its Outcomes field
const deleteShift = rows.map((row) => {
  const moves = [];
  for (let j = row.n; j < count; j += 1) {
    moves.push({ fieldId: 'prevStep' + j, value: f['prevStep' + (j + 1)] ?? null });
    moves.push({ fieldId: 'condition' + j, value: f['condition' + (j + 1)] ?? null });
  }
  return moves;
});
const deleteShiftOutcomes = rows.map((row) => {
  const moves = [];
  for (let j = row.n; j < count; j += 1) {
    const next = f['outcomes' + (j + 1)];
    moves.push({ fieldId: 'outcomes' + j, value: Array.isArray(next) ? next : [] });
  }
  return moves;
});
// Same as sequenceDetail (func_BeYBO): 'yes' only when every shown row is complete (a row 2-5 left fully empty is skipped) and there is at least one condition
let ready = true;
rows.forEach((row) => {
  if (!row.on) {
    return;
  }
  if (!row.stepId && !row.condition && row.n > 1) {
    return;
  }
  const step = steps.find((s) => s.id === row.stepId);
  const pairs = conditionsByType[(step && step.type) || 'email'];
  const codes = pairs.map((p) => p[0]);
  if (!row.stepId || codes.indexOf(row.condition) < 0) {
    ready = false;
    return;
  }
  const outcomePairs = pairsFor(row.condition, row.outcomes);
  if (outcomePairs.length) {
    const allowed = outcomePairs.map((p) => p[0]);
    const picked = (Array.isArray(row.outcomes) ? row.outcomes : []).filter((v) => allowed.indexOf(v) >= 0);
    if (!picked.length) {
      ready = false;
    }
  }
});
return {
  steps: steps,
  conditionOptions: conditionOptions,
  outcomeOptions: outcomeOptions,
  conditions: conditions,
  first: conditions[0] || null,
  ready: ready && conditions.length > 0 ? 'yes' : 'no',
  operator: count > 1 && f.mainOperator === 'OR' ? 'OR' : 'AND',
  rowCount: count,
  deleteShift: deleteShift,
  deleteShiftOutcomes: deleteShiftOutcomes,
  lastRowKeys: ['prevStep' + count, 'condition' + count, 'outcomes' + count],
};

func_cE2xo.functionBody:
// A/B test on email steps in the Add step (b_pcaKt) and Edit step (b_wzNyk) modals. Same rules as sequenceDetail (stepAbTestCfg there).
// Per step form: Template B options and versions, the A and B previews, the check that blocks saving,
// and the abTestEnabled / variants / variantAWeight that Add / Edit Step In Sequence receives (contract: drafts/ab-contract.md).
// With A/B on, tab A edits the form's own emailSubject / emailBody and tab B edits abSubjectB / abBodyB;
// each variant sends its own subjectOverride / bodyOverride. bSubject / bBody pre-fill tab B like the common Message is pre-filled.
const versionRows = {{ e_6ad9fb10ceac1b55f2dde03a?.['data']?.['objects'] }} || [];
const templateRows = [];
const prefill = {{ func_VGUNl['value'] }} || {};
const lookups = { add: prefill.std || {}, edit: prefill.edit || {}, ifTrue: prefill.ifTrue || {}, elseBranch: prefill.else || {} };
const event = {{ var_CtMEb['value'] }} || {};
const savedStep = event.operation === 'edit_step' ? ({{ var_pCxV8['value'] }} || {}) : {};
const stepKind = {{ b_eXtqz['selectedOption'] }}?.id;
const listMain = {{ e_6a564c0fe37aa80dd4ab9c58['data'] }}?.templates || [];
const listElse = {{ e_6a58864ee37aa80dd4b85827['data'] }}?.templates || [];

const forms = {
  add: { top: {{ b_Uj8wV['data'] }} || {}, adv: {{ b_KdWu8['data'] }} || {}, list: listMain },
  edit: { top: {{ b_EAFLO['data'] }} || {}, adv: {{ b_5Evnu['data'] }} || {}, list: listMain },
  ifTrue: { top: {{ b_sqpNo['data'] }} || {}, adv: {{ b_yMtEb['data'] }} || {}, list: listMain },
  elseBranch: { top: {{ b_9X3D5['data'] }} || {}, adv: {{ b_aL2ID['data'] }} || {}, list: listElse },
};

// Template text can hold double-brace merge fields; shown as single braces so the page does not read them as bindings.
const plainBraces = function (text) {
  return String(text || '').replace(/\{\{\s*/g, '{').replace(/\s*\}\}/g, '}');
};
const toText = function (html) {
  return String(html || '')
    .replace(/\r\n/g, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|h[1-6]|li)>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/[\u200b-\u200d\ufeff]/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/\{\{\s*/g, '{')
    .replace(/\s*\}\}/g, '}')
    .trim();
};
// Same conversion the common Body uses (stepConfigPrefill): HTML kept as is, plain text one paragraph per line.
const toHtml = function (value) {
  const raw = String(value || '');
  if (!raw || /<\/?(p|br|div|ul|ol|li|strong|b|em|i|a|span|h[1-6])\b/i.test(raw)) {
    return raw;
  }
  const esc = function (t) {
    return t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  };
  return raw
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map(function (line) { return '<p>' + esc(line) + '</p>'; })
    .join('');
};
const versionsOf = function (templateId) {
  return versionRows
    .filter(function (row) {
      return row && row.properties && templateId && row.properties.templateId === templateId;
    })
    .sort(function (a, b) {
      return Number(b.properties.version || 0) - Number(a.properties.version || 0);
    });
};
const versionLabel = function (row, latestId) {
  return 'v' + (row.properties.version ?? '?') + (row.id === latestId ? ' (latest)' : '');
};
const nameOf = function (list, templateId) {
  const hit = list.find(function (row) { return row && row.templateId === templateId; });
  const row = templateRows.find(function (r) { return r && r.id === templateId; });
  return (hit && hit.templateName) || (row && row.properties && row.properties.templateHeading) || '';
};

const savedVariants = Array.isArray(savedStep.variants) ? savedStep.variants : [];
const savedB = savedVariants.find(function (v) { return v && v.variantKey === 'B'; }) || {};
const stored = {
  enabled: savedStep.abTestEnabled === true,
  bTemplateId: savedStep.abTestEnabled === true ? savedB.templateId : undefined,
  bVersionId: savedStep.abTestEnabled === true ? savedB.templateVersionId : undefined,
};

const build = function (key) {
  const form = forms[key];
  const top = form.top;
  const adv = form.adv;
  const group = lookups[key] || {};
  const actionType = String(top.field5 || '').toLowerCase();
  const isEmail = actionType === 'email';
  const enabled = isEmail && adv.abTestEnabled === true;
  const aId = adv.templateId || '';
  const aVersionId = adv.templateVersionId || group.versionId || '';
  const bId = adv.abTemplateB || '';

  const bList = versionsOf(bId);
  const bLatestId = bList.length ? bList[0].id : undefined;
  const keepStored = key === 'edit' && stored.bTemplateId && stored.bTemplateId === bId
    && bList.some(function (row) { return row.id === stored.bVersionId; });
  const bDefaultVersionId = keepStored ? stored.bVersionId : bLatestId;
  const bVersionId = adv.abTemplateBVersionId || bDefaultVersionId || '';
  const bActive = bList.find(function (row) { return row.id === bVersionId; });
  const bTemplate = { properties: form.list.find(function (row) { return row && row.templateId === bId; }) };
  const bSource = (bActive && bActive.properties) || (bTemplate && bTemplate.properties) || {};
  // Tab B starts from the saved B text when editing the same B template and version, else from that template version.
  const keepSavedB = key === 'edit' && stored.enabled && !!bId && stored.bTemplateId === bId
    && (!stored.bVersionId || bVersionId === stored.bVersionId);
  const bSubject = (keepSavedB && savedB.subjectOverride) || bSource.subject || '';
  const bBody = toHtml(keepSavedB && savedB.bodyOverride) || toHtml(bSource.body);

  let error = '';
  if (enabled) {
    if (!aId) {
      error = 'Pick Template A first.';
    } else if (!bId) {
      error = 'Pick Template B to run the test.';
    } else if (bId === aId) {
      error = 'Pick two different templates for the A/B test.';
    }
  }

  let payload = {};
  if (isEmail && enabled) {
    payload = {
      abTestEnabled: true,
      variants: [
        {
          variantKey: 'A',
          templateId: aId,
          templateVersionId: aVersionId || undefined,
          subjectOverride: adv.emailSubject || '',
          bodyOverride: adv.emailBody || '',
        },
        {
          variantKey: 'B',
          templateId: bId,
          templateVersionId: bVersionId || undefined,
          subjectOverride: adv.abSubjectB || '',
          bodyOverride: adv.abBodyB || '',
        },
      ],
      variantAWeight: 50,
    };
  } else if (actionType) {
    payload = { abTestEnabled: false, variants: [], variantAWeight: 50 };
  }

  const aActive = versionsOf(aId).find(function (row) { return row.id === aVersionId; });
  return {
    isEmail: isEmail,
    enabled: enabled,
    bOptions: form.list
      .filter(function (row) { return row && row.templateId && row.templateId !== aId; })
      .map(function (row) { return { id: row.templateId, name: row.templateName || row.templateId }; }),
    bVersions: bList.map(function (row) { return { id: row.id, name: versionLabel(row, bLatestId) }; }),
    bDefaultVersionId: bDefaultVersionId,
    bSubject: bSubject,
    bBody: bBody,
    preview: {
      a: {
        title: aId ? (nameOf(form.list, aId) || 'Template A') + (aActive ? ' · v' + (aActive.properties.version ?? '?') : '') : 'No template picked yet',
        subject: plainBraces(adv.emailSubject || group.subject),
        body: toText(adv.emailBody || group.body) || 'This email has no body yet.',
      },
      b: {
        title: bId ? (nameOf(form.list, bId) || 'Template B') + (bActive ? ' · v' + (bActive.properties.version ?? '?') : '') : 'No template picked yet',
        subject: plainBraces(bSource.subject),
        body: bId ? (toText(bSource.body) || 'This template has no body.') : 'Pick Template B above to see it here.',
      },
    },
    invalid: error ? 'yes' : 'no',
    error: error,
    payload: payload,
  };
};

const add = build('add');
const edit = build('edit');
const ifTrue = build('ifTrue');
const elseBranch = build('elseBranch');
const isConditional = stepKind === 'button2';

return {
  add: add,
  edit: edit,
  ifTrue: ifTrue,
  elseBranch: elseBranch,
  stored: stored,
  blocked: {
    addModal: isConditional
      ? (ifTrue.invalid === 'yes' || elseBranch.invalid === 'yes' ? 'yes' : 'no')
      : add.invalid,
    editModal: edit.invalid,
  },
  payload: {
    standard: event.operation === 'add_step' ? add.payload : edit.payload,
    ifTrue: ifTrue.payload,
    elseBranch: elseBranch.payload,
  },
};

