var text = {{ e_6a509cb995c542323d18ac42['data']['object']['properties']['emails']['emailContent'] }};
text = (text === null || text === undefined) ? '' : String(text);

function plainTextDoc(t) {
  var paragraphs = t.length ? t.split(/\n{2,}/) : [''];
  return paragraphs.map(function (p) {
    var lines = p.split('\n');
    var nodes = [];
    lines.forEach(function (line, i) {
      if (i > 0) {
        nodes.push({ type: 'hardBreak' });
      }
      if (line.length) {
        nodes.push({ type: 'text', text: line });
      }
    });
    return nodes.length ? { type: 'paragraph', content: nodes } : { type: 'paragraph' };
  });
}

function decodeEntities(s) {
  return s
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, function (m, n) {
      return String.fromCharCode(Number(n));
    })
    .replace(/&#x([0-9a-f]+);/gi, function (m, n) {
      return String.fromCharCode(parseInt(n, 16));
    })
    .replace(/&amp;/g, '&');
}

function htmlDoc(html) {
  var blocks = [];
  var lists = [];
  var para = null;
  var marks = { bold: 0, italic: 0, underline: 0, strike: 0 };
  var links = [];

  function target() {
    if (!lists.length) {
      return blocks;
    }
    var list = lists[lists.length - 1];
    if (!list.content.length) {
      list.content.push({ type: 'listItem', content: [] });
    }
    return list.content[list.content.length - 1].content;
  }
  function openPara() {
    para = { type: 'paragraph', content: [] };
    target().push(para);
  }
  function ensurePara() {
    if (!para) {
      openPara();
    }
  }
  function currentMarks() {
    var out = [];
    if (marks.bold > 0) out.push({ type: 'bold' });
    if (marks.italic > 0) out.push({ type: 'italic' });
    if (marks.underline > 0) out.push({ type: 'underline' });
    if (marks.strike > 0) out.push({ type: 'strike' });
    if (links.length && links[links.length - 1]) {
      out.push({ type: 'link', attrs: { href: links[links.length - 1] } });
    }
    return out;
  }

  var tokens = html.split(/(<[^>]+>)/);
  tokens.forEach(function (tok) {
    if (!tok) return;
    var m = tok.match(/^<\s*(\/?)\s*([a-zA-Z0-9]+)([^>]*)>$/);
    if (!m) {
      var t = decodeEntities(tok.replace(/[\r\n\t]+/g, ' '));
      if (!t.length || (!para && !t.trim())) return;
      ensurePara();
      var node = { type: 'text', text: t };
      var mk = currentMarks();
      if (mk.length) node.marks = mk;
      para.content.push(node);
      return;
    }
    var closing = m[1] === '/';
    var tag = m[2].toLowerCase();
    var attrs = m[3] || '';
    if (/^(p|div|h[1-6]|blockquote)$/.test(tag)) {
      para = null;
      if (!closing) openPara();
    } else if (tag === 'br') {
      ensurePara();
      para.content.push({ type: 'hardBreak' });
    } else if (tag === 'ul' || tag === 'ol') {
      para = null;
      if (closing) {
        lists.pop();
      } else {
        var list = { type: tag === 'ul' ? 'bulletList' : 'orderedList', content: [] };
        target().push(list);
        lists.push(list);
      }
    } else if (tag === 'li') {
      para = null;
      if (!closing && lists.length) {
        lists[lists.length - 1].content.push({ type: 'listItem', content: [] });
      }
    } else if (tag === 'strong' || tag === 'b') {
      marks.bold += closing ? -1 : 1;
    } else if (tag === 'em' || tag === 'i') {
      marks.italic += closing ? -1 : 1;
    } else if (tag === 'u') {
      marks.underline += closing ? -1 : 1;
    } else if (tag === 's' || tag === 'strike' || tag === 'del') {
      marks.strike += closing ? -1 : 1;
    } else if (tag === 'a') {
      if (closing) {
        links.pop();
      } else {
        var h = attrs.match(/href\s*=\s*["']([^"']*)["']/i);
        links.push(h ? decodeEntities(h[1]) : '');
      }
    }
  });

  function clean(nodes) {
    nodes.forEach(function (n) {
      if (n.type === 'paragraph' && n.content && !n.content.length) {
        delete n.content;
      } else if (n.type === 'listItem' && !n.content.length) {
        n.content.push({ type: 'paragraph' });
      }
      if (n.content) clean(n.content);
    });
  }
  clean(blocks);
  var kept = blocks.filter(function (n) {
    return !(n.type === 'paragraph' && !n.content);
  });
  return kept.length ? kept : [{ type: 'paragraph' }];
}

var looksHtml = /<\/?(p|br|div|ul|ol|li|strong|b|em|i|u|a|span|h[1-6])\b[^>]*>/i.test(text);
var docContent = looksHtml ? htmlDoc(text) : plainTextDoc(text);
return JSON.stringify({ type: 'doc', content: docContent });

