const META = {
  no_answer: { label: 'No Answer', description: 'Rang out, no voicemail', icon: 'SvgPhone02' },
  left_voicemail: { label: 'Left Voicemail', description: 'No answer, left a message', icon: 'Microphone01' },
  gatekeeper: { label: 'Gatekeeper', description: 'Reached an assistant or front desk', icon: 'SvgShield01' },
  bad_number: { label: 'Bad Number', description: 'Disconnected or invalid number', icon: 'AlertTriangle' },
  no_longer_with_company: { label: 'No Longer with Company', description: 'Prospect has left the company', icon: 'SvgBuilding05' },
  answered_wrong_poc: { label: 'Answered – Wrong Person', description: 'Someone else picked up', icon: 'SvgUsersX' },
  answered_not_interested: { label: 'Answered – Not Interested', description: 'Declined to proceed', icon: 'ThumbsDown' },
  answered_referral: { label: 'Answered – Referral', description: 'Pointed to a better contact', icon: 'Share04' },
  answered_call_back: { label: 'Answered – Call Back', description: 'Asked to call back later', icon: 'ClockRefresh' },
  answered_meeting_set: { label: 'Answered – Meeting Set', description: 'Meeting booked on the call', icon: 'SvgCalendarCheck01' },
  answered_other: { label: 'Answered – Other', description: 'Connected, other outcome', icon: 'DotsHorizontal' },
};
const ORDER = [
  'no_answer',
  'left_voicemail',
  'gatekeeper',
  'bad_number',
  'no_longer_with_company',
  'answered_wrong_poc',
  'answered_not_interested',
  'answered_referral',
  'answered_call_back',
  'answered_meeting_set',
  'answered_other',
];
const rows = ({{ e_6adfcfe533138b70ed82cd82['data'] }} || {})['objects'] || [];
const row = rows[0];
let value = row && row.properties ? row.properties.value : null;
if (typeof value === 'string') {
  try {
    value = JSON.parse(value);
  } catch (e) {
    value = null;
  }
}
const stored = value && Array.isArray(value.outcomes) && value.outcomes.length ? value.outcomes : null;
const list = stored || ORDER.map(function (code) {
  return { code: code, label: META[code].label, shown: true, system: true };
});
const outcomes = list
  .filter(function (item) {
    return item && item.code && item.shown !== false;
  })
  .map(function (item) {
    const code = String(item.code);
    const meta = META[code] || {};
    return {
      code: code,
      label: String(item.label || meta.label || code),
      description: meta.description || '',
      icon: meta.icon || 'MessageTextSquare02',
    };
  });
return {
  requireNotes: !!(value && value.requireNotes === true),
  outcomes: outcomes,
};

