var props = ({{ e_6adc5b1a925d282255e5be6d['data']['properties'] }}) || {};
var calls = props.calls || {};

function norm(s) {
  return String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

var aiSummary = String(calls.aiSummary || '').trim();
var talkTrack = Array.isArray(calls.talkTrack)
  ? calls.talkTrack.filter(function (s) { return s && String(s).trim(); })
  : [];
var openActionItems = Array.isArray(calls.openActionItems)
  ? calls.openActionItems.filter(function (s) { return s && String(s).trim(); })
  : [];
var script = String(props.callScript || '').trim();

var hasTalkingPoints = !!(aiSummary || talkTrack.length || openActionItems.length);
var hasScript = !!script;

var scriptNorm = norm(script);
var pointsNormList = [norm(aiSummary)]
  .concat(talkTrack.map(norm))
  .concat(openActionItems.map(norm))
  .filter(function (s) { return s; });
var scriptOverlaps = hasScript && hasTalkingPoints && (
  pointsNormList.indexOf(scriptNorm) !== -1 ||
  pointsNormList.join(' ').indexOf(scriptNorm) !== -1
);

var mode;
var summary = aiSummary;
var lastDiscussed = talkTrack;
var actionItems = openActionItems;

if (!hasTalkingPoints && hasScript) {
  mode = 'scriptAsTalkingPoints';
  var lines = script.split(/\n+/).map(function (s) { return s.trim(); }).filter(function (s) { return s; });
  summary = lines.length ? lines[0] : script;
  lastDiscussed = lines.slice(1);
  actionItems = [];
