func_SvgUa.functionBody:
const meetingAtIso = {{ b_0387D['data']['meetingAt'] }};
const rawStart = meetingAtIso ? new Date(meetingAtIso).getTime() : undefined;
const durationLabel = String({{ b_OpUGN['value'] }} || '');

function pad(n) {
  return String(n).padStart(2, '0');
}

function toIsoWithOffset(ms) {
  const d = new Date(ms);
  const offsetMin = -d.getTimezoneOffset();
  const sign = offsetMin >= 0 ? '+' : '-';
  const abs = Math.abs(offsetMin);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate())
    + 'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds())
    + sign + pad(Math.floor(abs / 60)) + ':' + pad(abs % 60);
}

const hourMatch = durationLabel.match(/(\d+)\s*hr/);
const minuteMatch = durationLabel.match(/(\d+)\s*min/);
const durationMinutes = (hourMatch ? Number(hourMatch[1]) * 60 : 0) + (minuteMatch ? Number(minuteMatch[1]) : 0);

let startMs = Number(rawStart);
if (Number.isFinite(startMs) && startMs > 0 && startMs < 1000000000000) {
  startMs = startMs * 1000;
}
const ready = Number.isFinite(startMs) && startMs > 0 && durationMinutes > 0;

return {
  ready: ready,
  durationMinutes: durationMinutes,
  startDateTime: ready ? toIsoWithOffset(startMs) : '',
  endDateTime: ready ? toIsoWithOffset(startMs + durationMinutes * 60000) : ''
};

