var activitySrc = {{ e_6a57aa2f271a1b5f9e376054['data'] }};
var acts = (activitySrc && activitySrc['activties']) ? activitySrc['activties'].slice() : [];

function toTime(v) {
  if (v === null || v === undefined || v === '') {
    return 0;
  }
  var raw = String(v).trim();
  if (/^[0-9]+$/.test(raw)) {
    var n = Number(raw);
    return n < 1e12 ? n * 1000 : n;
  }
  var t = new Date(raw).getTime();
  return isNaN(t) ? 0 : t;
}

acts.sort(function (a, b) {
  return toTime(b.activityDate) - toTime(a.activityDate);
});

var recent = acts.slice(0, 3);
var last = recent[0];

var taskSrc = {{ e_6a509cb995c542323d18ac42['data'] }};
var taskObj = (taskSrc && taskSrc['object']) ? taskSrc['object'] : {};
var props = taskObj['properties'] ? taskObj['properties'] : {};
var step = props['dayOfSequence'];
var stepTitle = props['stepTitle'];

var stepLine = '';
if (step || stepTitle) {
  stepLine = 'This is step ' + (step ? step : '') + (stepTitle ? (' - ' + stepTitle) : '') + ' of the sequence.';
}

var talkingPointsList = [];
if (!last) {
  talkingPointsList.push('No prior activity on record yet for this prospect.');
  if (stepLine) {
    talkingPointsList.push(stepLine);
  }
} else {
  var lastType = last.taskType ? last.taskType : 'activity';
  var lastDesc = last.description ? last.description : 'no summary recorded';
  var lastDate = last.activityDate ? last.activityDate : '';
  talkingPointsList.push('Last touchpoint: ' + lastType + (lastDate ? (' on ' + lastDate) : '') + ' - ' + lastDesc + '.');
  if (stepLine) {
    talkingPointsList.push(stepLine);
  }
}

var talkingPoints = talkingPointsList.map(function (p) { return '•  ' + p; }).join('\n');

return {
  recent: recent,
  talkingPoints: talkingPoints.trim(),
  talkingPointsList: talkingPointsList,
};

