func_UHa5E.functionBody:
var viewerZone = {{ var_ZB8Dk['value'] }};
var rows = {{ e_6ace46e070b66f5702f6448b['data']?.['schedule'] }} || [];

// One display time per rail row, in the VIEWER's own time zone, parallel to
// the schedule array the rail repeats over.
//
// The rail is fed from the TASK queue (scheduleTodayFeed), so every row comes
// from that source's transformer carrying utcTimeEpoch -- the task's true
// instant in epoch milliseconds -- and, where the record had none, sortMs: the
// wall-clock `time` converted from the record's own IANA zone. The transformer
// orders the rail on exactly those two, in that order, so the time a card
// shows and the place it sits can never disagree.

// Same h:mm a convention nowMarkerDisplayTime (func_Mw7XP) uses.
function formatHM(instant, zone) {
  var parts = new Intl.DateTimeFormat('en-US', {
    hour: '2-digit', minute: '2-digit', hour12: false, timeZone: zone
  }).formatToParts(instant);
  var map = {};
  parts.forEach(function (p) { map[p.type] = p.value; });
  var hour = parseInt(map.hour === '24' ? '00' : map.hour, 10);
  var minute = map.minute;
  var ampm = hour >= 12 ? 'PM' : 'AM';
  var hour12 = hour % 12;
  if (hour12 === 0) hour12 = 12;
  return hour12 + ':' + minute + ' ' + ampm;
}

function toMs(raw) {
  var n = typeof raw === 'number' ? raw : parseInt(String(raw == null ? '' : raw), 10);
  return isNaN(n) ? null : n;
}

// utcTimeEpoch first, exactly the field the rail is ordered by; sortMs is the
// converted wall clock the transformer fills in only where the record carried
// no epoch.
function epochOf(item) {
  var epoch = toMs(item.utcTimeEpoch);
  return epoch !== null ? epoch : toMs(item.sortMs);
}

var effectiveZone = viewerZone || 'America/New_York';

return rows.map(function (item) {
  if (!item || item.isNowMarker) {
    // The Now row's own display comes from nowMarkerDisplayTime (func_Mw7XP),
    // already in the viewer's zone -- this entry is never read for it.
    return item ? (item.time || '') : '';
  }
  var epoch = epochOf(item);
  if (epoch !== null) {
    try {
      return formatHM(new Date(epoch), effectiveZone);
    } catch (e) {
      // Fall back to the time the source's transformer already formatted in
      // the task record's own zone rather than showing nothing.
      return item.time || '';
    }
  }
  // No instant at all: show the transformer's formatted time if the row has
  // one, and nothing rather than an invented time if it does not.
  return item.time || '';
});

