// Title, helper line and icon for the AI-prioritized queue's empty state,
// worded for the type tab, the Task Status select and the DUE RANGE chip.
var tab = String({{ var_activeTab['value'] }} || 'All');
var status = String({{ b_80n40['value'] }} || 'All');
var range = String({{ var_E89kn['value'] }} || 'Today').toLowerCase();
var search = String({{ var_2aLw7['value'] }} || '').trim();
var priority = String({{ var_AQw2F['value'] }} || 'All');
var source = String({{ var_TRYfI['value'] }} || 'All');

var rangeWord = 'today';
if (range.indexOf('week') >= 0) { rangeWord = 'this week'; }
else if (range.indexOf('month') >= 0) { rangeWord = 'this month'; }
else if (range.indexOf('custom') >= 0) { rangeWord = 'in this date range'; }
else if (range.indexOf('overdue') >= 0) { rangeWord = 'overdue'; }
var rangeFor = rangeWord === 'today' ? 'for today' : rangeWord;

var typeWords = {
  'Call': 'call',
  'Email': 'email',
  'LinkedIn': 'LinkedIn',
  'Meeting': 'meeting',
  'Generic': 'generic',
  'Auto-Exec': 'auto-executed'
};
var typeIcons = {
  'All': 'SvgCalendarCheck01',
  'Call': 'SvgPhone',
  'Email': 'Mail01',
  'LinkedIn': 'SvgUserSquare',
  'Meeting': 'SvgUsers01',
  'Generic': 'SvgClipboard',
  'Skipped': 'SvgClipboardCheck',
  'Auto-Exec': 'Zap'
};
var typeWord = typeWords[tab] || '';
var tasksWord = typeWord ? typeWord + ' tasks' : 'tasks';
var hasStatus = ['Pending', 'Upcoming', 'Due', 'Completed', 'Cancelled', 'Paused'].indexOf(status) >= 0;

var title = '';
var subtitle = '';
var icon = typeIcons[tab] || 'SvgCalendarCheck01';

if (search) {
  title = 'No results for "' + search + '"';
  subtitle = 'Try a different search term, or clear filters to see every task.';
  icon = 'SvgSearchMd';
} else if (tab === 'Skipped') {
  title = 'No skipped tasks';
  subtitle = 'Tasks you skip ' + rangeWord + ' will show up here to revisit later.';
} else if (status === 'Completed') {
  title = 'No completed ' + tasksWord + ' yet';
  subtitle = 'Tasks you finish ' + rangeWord + ' will show up here.';
  icon = 'SvgCheckCircle';
} else if (status === 'Pending') {
  title = 'No pending ' + tasksWord;
  subtitle = 'Nothing is waiting on you ' + rangeWord + '. Try another status or a wider due range.';
} else if (status === 'Upcoming') {
  title = 'No upcoming ' + tasksWord;
  subtitle = 'Nothing new is scheduled ' + rangeWord + '. New tasks will appear here as they are planned.';
} else if (status === 'Cancelled') {
  title = 'No cancelled ' + tasksWord;
  subtitle = 'No tasks were cancelled ' + rangeWord + '. Try another status or a wider due range.';
} else if (status === 'Paused') {
  title = 'No paused ' + tasksWord;
  subtitle = 'No tasks are paused ' + rangeWord + '. Try another status or a wider due range.';
} else if (status === 'Due') {
  title = typeWord ? 'No ' + tasksWord + ' due ' + rangeWord : 'Nothing due ' + rangeWord;
  subtitle = 'You are on top of your queue. Tasks that fall due will appear here.';
} else if (typeWord) {
  title = 'No ' + tasksWord + ' ' + rangeFor;
  subtitle = 'Try another task type or a wider due range.';
} else if (rangeWord === 'overdue') {
  title = "Nothing overdue";
  subtitle = "You're all caught up — no overdue tasks right now.";
  icon = 'SvgCheckCircle';
} else if (rangeWord === 'today') {
  title = "You're all caught up";
  subtitle = 'No tasks are due today. New tasks will appear here as they are scheduled.';
} else {
  title = 'No tasks ' + rangeWord;
  subtitle = 'Nothing is due ' + rangeWord + '. Try a wider date range or check back later.';
}

return {
  title: title,
  subtitle: subtitle,
  icon: icon,
  showReset: tab !== 'All' || hasStatus || search !== '' || priority !== 'All' || source !== 'All' || range !== 'today'
};

