func_whCVi.functionBody:
var objects = {{ e_6a4f7c9dd92545720039a9fc['data']?.['objects'] }} || [];
var nowMs = Date.now();

// Right-rail counters. These are UNFILTERED by the queue's own client-side
// controls (search, priority, status, sequence, account, source toggle) --
// they reflect the server's own fetch (its date range, task-type tab and
// skipped/auto-exec toggles), never the extra client-side narrowing below
// the fetch. The queue source re-runs on its own 25-minute poll and whenever
// its inputs change, which is also when this recomputes, so "before now" is
// evaluated against the clock at the last refresh rather than live.
function fieldsOf(row) {
  return (row && row.properties) || row || {};
}
function statusOf(row) {
  var s = fieldsOf(row).taskStatus;
  return String(s == null ? '' : s).trim().toLowerCase();
}
// Due instant: utcTimeEpoch, else dueTime (epoch ms, epoch seconds, a numeric
// string or an ISO string) -- the same rule as the Due time column (func_1Rtn8).
function toMs(raw) {
  if (raw === undefined || raw === null || raw === '') { return null; }
  if (typeof raw === 'number') { return isNaN(raw) ? null : (Math.abs(raw) < 100000000000 ? raw * 1000 : raw); }
  var s = String(raw).trim();
  if (/^-?\d+(\.\d+)?$/.test(s)) { var n = parseFloat(s); return Math.abs(n) < 100000000000 ? n * 1000 : n; }
  var parsed = Date.parse(s);
  return isNaN(parsed) ? null : parsed;
}
function epochOf(row) { var f = fieldsOf(row); var ms = toMs(f.utcTimeEpoch); return ms === null ? toMs(f.dueTime) : ms; }
// A task is "skipped" either via the stored boolean-ish properties.skipped flag
// (1 / "1" / true -- the flag the unskip action clears back to 0) or, if the
// automation ever surfaces it that way, a literal taskStatus of 'skipped'.
function isSkipped(row) {
  var v = fieldsOf(row).skipped;
  return v === 1 || v === '1' || v === true || statusOf(row) === 'skipped';
}

var overdue = 0;
var completed = 0;
var skipped = 0;

objects.forEach(function (row) {
  var status = statusOf(row);
  if (status === 'completed') { completed = completed + 1; return; }
  if (status !== 'upcoming' && isSkipped(row)) { skipped = skipped + 1; }
  // Overdue -- the fetch's taskStatus "overdue" rule: due before now and
  // neither completed nor cancelled; skipped tasks are included.
  if (status === 'cancelled') { return; }
  var ms = epochOf(row);
  if (ms !== null && ms < nowMs) { overdue = overdue + 1; }
});

return { overdue: overdue, completed: completed, skipped: skipped };

