func_1Rtn8.functionBody:
// Each queue row's due date-time for the REP (viewer, var_ZB8Dk) and for the
// PROSPECT, both shown with a standard UTC offset instead of an ambiguous
// zone abbreviation (CDT, GMT, IST...), since an abbreviation like IST is
// ambiguous (India or Israel).
// Zone order for the prospect's side is UNCHANGED from before: the prospect
// record's timeZone (charge_point_cm_prospects, fetched by queueProspectZones),
// then the task row's own timeZone. If neither validates, we still fall back
// to the viewer's own zone so SOME time renders, but prospectKnown is false so
// the UI hides the whole prospect line rather than mislabeling the viewer's
// time as the prospect's.
// Reads properties.utcTimeEpoch first, else properties.dueTime (epoch ms,
// epoch seconds, a numeric string or an ISO string) -- unchanged.
// Per row, keyed by row id:
//   state           'overdue' | 'due' | 'none' -- unchanged rule.
//   repText         'MMM D, h:mm A' in the rep's (viewer's) own zone, or an
//                   em dash when there is no due time at all.
//   repOffset       'UTC+5:30' style offset for the rep's zone, AT the due
//                   instant (so DST is correct for that specific date).
//   prospectText    'h:mm A', date-prefixed with 'MMM D, ' only when the
//                   prospect's local date differs from the rep's. Empty when
//                   prospectKnown is false, or when sameOffset is true (the
//                   UI shows 'Same time zone' instead).
//   prospectOffset  'UTC-5' style offset for the prospect's zone, AT the due
//                   instant. Empty exactly when prospectKnown is false --
//                   the UI uses this emptiness to hide the whole line.
//   sameOffset      true when the rep and prospect resolve to the SAME
//                   numeric UTC offset at this due instant (two different
//                   IANA zones can still share an offset on a given date --
//                   that still counts as "same", per the offset-based spec).
//   prospectKnown   true only when a prospect-specific or task-specific zone
//                   actually validated -- not merely falling back to the
//                   viewer's own zone.
//   lineTwoText     the fully composed line-2 string -- 'Same time zone',
//                   or '<time> \u00B7 <offset>'; empty when
//                   prospectKnown is false. Composed here, not in the block's
//                   own binding, so the block only reads a value.
//   tooltip         two-line markdown tooltip text, 'Rep: ...' then (when
//                   prospectKnown) a markdown hard break and 'Prospect: ...',
//                   each with the full weekday date, time, offset and IANA
//                   zone name.
// A row with no due time at all gets state 'none' and every text field empty.
// Speed: Intl formatters and offset parts are cached per zone/instant, not
// rebuilt per row, so a 250-row list still costs a few ms.
var rows = {{ func_LyPuN['value'] }} || [];
var prospects = {{ e_6adcfda80881d2257a421243['data']?.['objects'] }} || [];
var viewerZoneRaw = {{ var_ZB8Dk['value'] }};
var nowMs = Date.now();
var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

var zoneByProspect = {};
prospects.forEach(function (p) {
  var tz = p && p.properties ? String(p.properties.timeZone || '').trim() : '';
  if (p && p.id && tz) {
    zoneByProspect[p.id] = tz;
  }
});

var validCache = {};
function validZone(tz) {
  if (!tz) {
    return false;
  }
  if (validCache[tz] === undefined) {
    try {
      new Intl.DateTimeFormat('en-US', { timeZone: tz }).format(new Date(nowMs));
      validCache[tz] = true;
    } catch (e) {
      validCache[tz] = false;
    }
  }
  return validCache[tz];
}

var viewerZone = validZone(viewerZoneRaw) ? viewerZoneRaw : 'America/New_York';

function toMs(raw) {
  if (raw === undefined || raw === null || raw === '') {
    return null;
  }
  var n = null;
  if (typeof raw === 'number') {
    n = raw;
  } else {
    var s = String(raw).trim();
    if (/^-?\d+(\.\d+)?$/.test(s)) {
      n = parseFloat(s);
    } else {
      var parsed = Date.parse(s);
      return isNaN(parsed) ? null : parsed;
    }
  }
  if (isNaN(n)) {
    return null;
  }
  // An epoch in seconds (10 digits) is turned into milliseconds.
  return Math.abs(n) < 100000000000 ? n * 1000 : n;
}

var partFormatters = {};
function partFormatter(tz) {
  var key = tz || '__default__';
  if (partFormatters[key] === undefined) {
    partFormatters[key] = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      year: 'numeric', month: 'numeric', day: 'numeric',
      hour: '2-digit', minute: '2-digit', hourCycle: 'h23', weekday: 'short'
    });
  }
  return partFormatters[key];
}

function dateParts(ms, tz) {
  var parts = partFormatter(tz).formatToParts(new Date(ms));
  var map = {};
  parts.forEach(function (p) {
    map[p.type] = p.value;
  });
  var hour = parseInt(map.hour === '24' ? '0' : map.hour, 10);
  var ampm = hour >= 12 ? 'PM' : 'AM';
  var hour12 = hour % 12;
  if (hour12 === 0) {
    hour12 = 12;
  }
  return {
    year: parseInt(map.year, 10),
    month: parseInt(map.month, 10),
    day: parseInt(map.day, 10),
    weekday: map.weekday,
    hour12: hour12,
    minute: map.minute,
    ampm: ampm
  };
}

function shortDate(p) {
  return MONTHS[p.month - 1] + ' ' + p.day;
}

function shortTime(p) {
  return p.hour12 + ':' + p.minute + ' ' + p.ampm;
}

function fullDate(p) {
  return p.weekday + ', ' + MONTHS[p.month - 1] + ' ' + p.day + ', ' + p.year;
}

var offsetCache = {};
function offsetInfo(tz, ms) {
  var key = tz + '|' + ms;
  if (offsetCache[key] !== undefined) {
    return offsetCache[key];
  }
  var minutes = 0;
  var label = 'UTC\u00B10';
  try {
    var fmt = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'shortOffset' });
    var raw = '';
    fmt.formatToParts(new Date(ms)).forEach(function (p) {
      if (p.type === 'timeZoneName') {
        raw = p.value;
      }
    });
    var m = /^GMT([+-])?(\d+)?(?::(\d+))?$/.exec(raw);
    var sign = (m && m[1]) || '+';
    var hh = (m && m[2]) ? parseInt(m[2], 10) : 0;
    var mm = (m && m[3]) ? parseInt(m[3], 10) : 0;
    minutes = (sign === '-' ? -1 : 1) * (hh * 60 + mm);
    if (hh === 0 && mm === 0) {
      label = 'UTC\u00B10';
    } else {
