  }

  var prospectParts = prospectZone ? dateParts(ms, prospectZone) : null;
  var prospectOff = prospectZone ? offsetInfo(prospectZone, ms) : null;
  var sameOffset = !!(prospectOff && prospectOff.minutes === repOff.minutes);
  var dateDiffers = !!(prospectParts && (prospectParts.year !== repParts.year || prospectParts.month !== repParts.month || prospectParts.day !== repParts.day));
  var prospectText = (prospectKnown && !sameOffset && prospectParts) ? (dateDiffers ? shortDate(prospectParts) + ', ' : '') + shortTime(prospectParts) : '';

