func_xajTw.functionBody:
// Per queue row (keyed by row id): the prospect sub-line and the status tag.
// status.key drives the tag colour: due, overdue, completed, skipped, paused,
// upcoming, inprogress, cancelled. statusColor is the Tag colour name for that
// key, so the row's tag reads one plain value instead of seven conditions.
// Nothing here ever returns undefined text.
var rows = {{ func_LyPuN['value'] }} || [];
var nowMs = Date.now();
var COLOR_BY_KEY = {
  overdue: 'error',
  completed: 'success',
  skipped: 'gray',
  paused: 'warning',
  upcoming: 'cyan',
  inprogress: 'purple',
  due: 'blue'
};

function clean(v) {
  return v == null ? '' : String(v).trim();
}

function titleCase(s) {
  return s.split(/[\s_]+/).filter(function (w) {
    return w.length > 0;
  }).map(function (w) {
    return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
  }).join(' ');
}

// Due instant: utcTimeEpoch, else dueTime (epoch ms, epoch seconds, a numeric
// string or an ISO string) -- the same rule as the Due time column and the
// Overdue filter in queueOverdueDisplayRows.
function toMs(raw) {
  if (raw === undefined || raw === null || raw === '') { return null; }
  if (typeof raw === 'number') { return isNaN(raw) ? null : (Math.abs(raw) < 100000000000 ? raw * 1000 : raw); }
  var s = String(raw).trim();
  if (/^-?\d+(\.\d+)?$/.test(s)) { var n = parseFloat(s); return Math.abs(n) < 100000000000 ? n * 1000 : n; }
  var parsed = Date.parse(s);
  return isNaN(parsed) ? null : parsed;
}

function epochOf(f) {
  var ms = toMs(f.utcTimeEpoch);
  return ms === null ? toMs(f.dueTime) : ms;
}

// A cancelled task is never shown as Overdue (the overdue rule excludes
// completed and cancelled); a past-due skipped task is overdue in the list
// but its tag still reads Skipped.
function statusOf(f) {
  var s = clean(f.taskStatus).toLowerCase();
  var skippedFlag = f.skipped === 1 || f.skipped === '1' || f.skipped === true;
  if (s === 'completed' || s === 'done') {
    return { key: 'completed', label: 'Completed' };
  }
  if (s === 'cancelled') {
    return { key: 'cancelled', label: 'Cancelled' };
  }
  if (s === 'skipped' || skippedFlag) {
    return { key: 'skipped', label: 'Skipped' };
  }
  if (s === 'paused') {
    return { key: 'paused', label: 'Paused' };
  }
  if (s === 'upcoming') {
    return { key: 'upcoming', label: 'Upcoming' };
  }
  if (s === 'in progress' || s === 'in_progress' || s === 'inprogress' || s === 'started') {
    return { key: 'inprogress', label: 'In progress' };
  }
  var ms = epochOf(f);
  if (ms !== null && ms < nowMs) {
    return { key: 'overdue', label: 'Overdue' };
  }
  return { key: 'due', label: s ? titleCase(s) : 'Due' };
}

function subOf(f) {
  var name = clean(f.prospectName);
  if (!name) {
    return '—';
  }
  var role = clean(f.prospectDesignation);
  var account = clean(f.accountName);
  if (role && account) {
    return role + ' · ' + account;
  }
  return role || account || '—';
}

var out = {};
rows.forEach(function (row) {
  if (!row || row.id == null) {
    return;
  }
  var f = row.properties || row;
  var st = statusOf(f);
  out[row.id] = {
    sub: subOf(f),
    statusKey: st.key,
    statusLabel: st.label,
    statusColor: COLOR_BY_KEY[st.key] || 'gray'
  };
});
return out;

func_xrkrQ.functionBody:
// Range bounds for the queue's due-range chips, as epoch-ms strings, in the
// VIEWER's own time zone (the browser's zone, the same one viewerTimeZone
// var_ZB8Dk resolves). A task is placed by its real due instant
// (utcTimeEpoch, else dueTime), so these bounds are compared to that instant
// by the fetch. The week runs Monday 00:00 to Sunday 23:59:59.999.
// The page's day/month/year variables are read only so this re-runs once
// onPageLoad has set them; the date itself is taken from the browser clock.
var day = {{ var_cQ3h5['value'] }};
var month = {{ var_iBSpm['value'] }};
var year = {{ var_S7SkY['value'] }};
var viewerZone = {{ var_ZB8Dk['value'] }};

var now = new Date();
var y = now.getFullYear();
var m = now.getMonth();
var d = now.getDate();

function startOf(yy, mm, dd) {
  return new Date(yy, mm, dd, 0, 0, 0, 0).getTime();
}
function endOf(yy, mm, dd) {
  return new Date(yy, mm, dd, 23, 59, 59, 999).getTime();
}

var backToMonday = (now.getDay() + 6) % 7;

return {
  zone: viewerZone || '',
  todayStart: String(startOf(y, m, d)),
  todayEnd: String(endOf(y, m, d)),
  weekStart: String(startOf(y, m, d - backToMonday)),
  weekEnd: String(endOf(y, m, d - backToMonday + 6)),
  monthStart: String(startOf(y, m, 1)),
  monthEnd: String(endOf(y, m + 1, 0)),
  next7Start: String(startOf(y, m, d)),
  next7End: String(endOf(y, m, d + 6)),
  next14Start: String(startOf(y, m, d)),
  next14End: String(endOf(y, m, d + 13)),
  next30Start: String(startOf(y, m, d)),
  next30End: String(endOf(y, m, d + 29)),
  last7Start: String(startOf(y, m, d - 6)),
  last7End: String(endOf(y, m, d)),
  last30Start: String(startOf(y, m, d - 29)),
  last30End: String(endOf(y, m, d))
};

