var objects = {{ e_6a4f7c9dd92545720039a9fc['data']?.['objects'] }} || [];
var preset = String({{ var_E89kn['value'] }} || 'Today');
var nowMs = Date.now();
function fieldsOf(row) { return (row && row.properties) || row || {}; }
function statusOf(row) { var s = fieldsOf(row).taskStatus; return String(s == null ? '' : s).trim().toLowerCase(); }
// Due instant: utcTimeEpoch, else dueTime (epoch ms, epoch seconds, a numeric
// string or an ISO string) -- the same rule as the Due time column (func_1Rtn8).
function toMs(raw) {
  if (raw === undefined || raw === null || raw === '') { return null; }
  if (typeof raw === 'number') { return isNaN(raw) ? null : (Math.abs(raw) < 100000000000 ? raw * 1000 : raw); }
  var s = String(raw).trim();
  if (/^-?\d+(\.\d+)?$/.test(s)) { var n = parseFloat(s); return Math.abs(n) < 100000000000 ? n * 1000 : n; }
  var parsed = Date.parse(s);
  return isNaN(parsed) ? null : parsed;
}
function epochOf(row) { var f = fieldsOf(row); var ms = toMs(f.utcTimeEpoch); return ms === null ? toMs(f.dueTime) : ms; }
function isSkipped(row) {
  var v = fieldsOf(row).skipped;
  return v === 1 || v === '1' || v === true || statusOf(row) === 'skipped';
}
function isCompleted(row) { return statusOf(row) === 'completed'; }
function isCancelled(row) { return statusOf(row) === 'cancelled'; }
// Overdue -- the same rule the fetch applies for taskStatus "overdue":
// due instant before now AND taskStatus is neither completed nor cancelled.
// Skipped tasks that are past due ARE overdue. The row's own status tag is a
// separate, mutually-exclusive display decision (queueRowDisplay).
function isOverdue(row) {
  if (isCompleted(row) || isCancelled(row)) { return false; }
  var ms = epochOf(row);
  return ms !== null && ms < nowMs;
}
function isDueNotYet(row) {
  var status = statusOf(row);
  if (status === 'completed' || status === 'upcoming' || status === 'paused' || isSkipped(row)) { return false; }
  var ms = epochOf(row);
  return ms === null || ms >= nowMs;
}

// Under the Overdue chip the fetch already returns exactly the overdue set
// (taskStatus "overdue"); filtering again here keeps the list honest if a row
// fell due or was closed between the fetch and now.
var byPreset = preset === 'Overdue' ? objects.filter(isOverdue) : objects;

var seqFilter = String({{ var_5qgjw['value'] }} || '').trim().toLowerCase();
var acctFilter = String({{ var_l8yTu['value'] }} || '').trim().toLowerCase();
var autoManualFilter = String({{ var_TRYfI['value'] }} || 'All');
var priorityFilter = String({{ var_AQw2F['value'] }} || 'All');
var statusFilter = String({{ b_80n40['value'] }} || 'All');

// Free-text search box in the filter bar: matches the task title, the
// prospect's name, the account name, the task type, the source or the
// sequence name, all case-insensitively, as a plain substring -- the same
// columns the table shows. properties.sequenceName is populated by newer
// writes only -- older/seeded rows carry a sequenceId with no sequenceName,
// so this match covers rows that do carry it; it does not resolve a name
// from sdr_sequences (that join only happens for display, in
// queueSequenceStepLines).
var searchFilter = String({{ var_2aLw7['value'] }} || '').trim().toLowerCase();

return byPreset.filter(function (row) {
  var f = fieldsOf(row);
  if (seqFilter && !String(f.sequenceName || '').toLowerCase().includes(seqFilter)) { return false; }
  if (acctFilter && !String(f.accountName || '').toLowerCase().includes(acctFilter)) { return false; }
  if (autoManualFilter !== 'All') {
    var isAuto = String(f.source || '').toLowerCase() !== 'manual';
    if (autoManualFilter === 'Automated' && !isAuto) { return false; }
    if (autoManualFilter === 'Manual' && isAuto) { return false; }
  }
  if (priorityFilter !== 'All') {
    var rowPriority = String(f.priority || '').trim().toLowerCase();
    if (rowPriority !== priorityFilter.toLowerCase()) { return false; }
  }
  if (statusFilter !== 'All') {
    if (statusFilter === 'Due' && !isDueNotYet(row)) { return false; }
    if (statusFilter === 'Overdue' && !isOverdue(row)) { return false; }
    if (statusFilter === 'Completed' && !isCompleted(row)) { return false; }
    if (statusFilter === 'Skipped' && !isSkipped(row)) { return false; }
    if (statusFilter === 'Pending' && !(statusOf(row) === 'pending' && !isSkipped(row))) { return false; }
    if (statusFilter === 'Cancelled' && !isCancelled(row)) { return false; }
    if (statusFilter === 'Paused' && statusOf(row) !== 'paused') { return false; }
  }
  if (searchFilter) {
    var title = String(f.title || f.stepTitle || '').toLowerCase();
    var prospect = String(f.prospectName || '').toLowerCase();
    var account = String(f.accountName || '').toLowerCase();
    var taskType = String(f.taskType || '').toLowerCase();
    var source = String(f.source || '').toLowerCase();
    var sequenceName = String(f.sequenceName || '').toLowerCase();
    var hit = title.includes(searchFilter) || prospect.includes(searchFilter) || account.includes(searchFilter) || taskType.includes(searchFilter) || source.includes(searchFilter) || sequenceName.includes(searchFilter);
    if (!hit) { return false; }
  }
  return true;
});

