var tz = {{ var_ZB8Dk['value'] }} || 'America/New_York';
var raw = {{ b_yG0Up['data']['dueAt'] }};
if (!raw) {
  return { day: '', month: '', year: '', time: '', dueTimeString: '', utcTimeEpoch: null };
}
var inst = new Date(raw);
var utcTimeEpoch = inst.getTime();
var fmt = new Intl.DateTimeFormat('en-US', {
  timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23'
});
var parts = {};
fmt.formatToParts(inst).forEach(function (p) { parts[p.type] = p.value; });
var hh = parseInt(parts.hour, 10);
var ampm = hh >= 12 ? 'PM' : 'AM';
var hour12 = hh % 12;
if (hour12 === 0) { hour12 = 12; }
var dueTimeString = hour12 + ':' + parts.minute + ' ' + ampm;
var time = parts.hour + ':' + parts.minute + ':' + parts.second + '.000';
return {
  day: parts.day,
  month: parts.month,
