func_ayRN3.functionBody:
var rows = {{ func_LyPuN['value'] }} || [];
var sequences = {{ e_6ada3ac7ceac1b55f2e6846b['data']?.['objects'] }} || [];
var steps = {{ e_6ada3ac71a10ec0c91374dc8['data']?.['objects'] }} || [];
function fieldsOf(row) {
  return (row && row.properties) || row || {};
}

var seqById = {};
sequences.forEach(function (s) {
  seqById[s.id] = fieldsOf(s);
});

var stepsBySeq = {};
steps.forEach(function (s) {
  var f = fieldsOf(s);
  var sid = String(f.seqId || '');
  if (!stepsBySeq[sid]) {
    stepsBySeq[sid] = [];
  }
  stepsBySeq[sid].push(f);
});

return rows.map(function (row) {
  var f = fieldsOf(row);
  var sequenceId = String(f.sequenceId || '').trim();
  if (!sequenceId) {
    return { name: '', stepLabel: '' };
  }

  var seq = seqById[sequenceId];
  var name = (seq && seq.title) ? String(seq.title) : '';
  var totalRaw = seq ? seq.noOfSteps : null;
  var total = (totalRaw === undefined || totalRaw === null || totalRaw === '') ? null : parseInt(String(totalRaw), 10);

  // The task's own stepCount is never populated and sequenceName is never
  // populated either, so the name comes from sdr_sequences.title and the
  // step position is matched against sdr_sequence_wise_tasks (the frozen
  // per-sequence step list), by title first, then by day + task type.
  var taskStepTitle = String(f.stepTitle || '').trim().toLowerCase();
  var taskDayRaw = f.dayOfSequence;
  var taskDay = (taskDayRaw === undefined || taskDayRaw === null || taskDayRaw === '') ? null : parseInt(String(taskDayRaw), 10);
  var taskType = String(f.taskType || '').trim().toLowerCase();

  var candidates = stepsBySeq[sequenceId] || [];
  var match = null;
  if (taskStepTitle) {
    candidates.forEach(function (c) {
      if (!match && String(c.title || '').trim().toLowerCase() === taskStepTitle) {
        match = c;
      }
    });
  }
  if (!match && taskDay !== null && !isNaN(taskDay) && taskType) {
    candidates.forEach(function (c) {
      if (!match && parseInt(String(c.dayNumber), 10) === taskDay && String(c.taskType || '').trim().toLowerCase() === taskType) {
        match = c;
      }
    });
  }

  // Line 2 always leads with the sequence's total step count, then adds
  // the task's own position in it when a matching step was found: "Y
  // steps \u00b7 Step X of Y". With no total known, line 2 stays empty
  // (hidden) rather than showing a bare step position.
  var stepLabel = '';
  if (total !== null && !isNaN(total) && total > 0) {
    if (match && match.stepNumber !== undefined && match.stepNumber !== null) {
      stepLabel = total + ' steps · Step ' + match.stepNumber + ' of ' + total;
    } else {
      stepLabel = total + ' steps';
    }
  }

  return { name: name || sequenceId, stepLabel: stepLabel };
});

