func_y5Gzz.functionBody:
// Time zone words after the step time on the Sequence-tab step cards (b_xuMR2, b_c5bj5, b_nxOml).
// Follows Settings > Sending > Time zone: var timeZoneMode (var_VZRuu), set from loadSequenceSettings,
// the same source of truth as stepTimeZoneHint (func_laxwa). Not loaded or no settings row -> 'prospect time'.
var mode = String({{ var_VZRuu['value'] }} || 'prospect');
var settings = {{ e_6adb1b2e0905960470b15221['data'] }} || {};

var shortZoneName = function (zone) {
  var locales = ['en-US', 'en-GB', 'en-IN', 'en-AU', 'en-SG', 'en-ZA'];
  for (var i = 0; i < locales.length; i++) {
    try {
      var parts = new Intl.DateTimeFormat(locales[i], { timeZone: zone, timeZoneName: 'short' }).formatToParts(new Date());
      var part = parts.filter(function (p) { return p.type === 'timeZoneName'; })[0];
      if (part && part.value && !/^(GMT|UTC)/.test(part.value)) {
        return part.value;
      }
    } catch (e) {
      return zone;
    }
  }
  return zone;
};

if (mode === 'owner') {
  return 'rep time';
}
if (mode === 'fixed') {
  var zone = settings['fixedTimeZone'] || settings['fixedTimezone'] || '';
  return zone ? shortZoneName(String(zone)) : 'prospect time';
}
return 'prospect time';

