func_50yy8.functionBody:
const src = {{ e_6adb44c80881d2257a7c631f }} || {};
const data = src.data || null;
const softError = !!data && data.status === 'error' && /variant/i.test(data.message || '');
const failed = !!src.error || (!!data && data.status === 'error' && !softError);
const steps = (data && Array.isArray(data.steps)) ? data.steps : [];
const stepOptions = (data && Array.isArray(data.stepOptions)) ? data.stepOptions : [];
const loaded = !!data && !failed;
const hasAb = loaded && !softError && (stepOptions.length > 0 || steps.length > 0);
const isEmpty = loaded && !hasAb;
const isLoading = !data && !src.error;
const testStatus = (data && data.testStatus) || 'running';
const running = hasAb && testStatus !== 'stopped';
const stopped = hasAb && testStatus === 'stopped';
const winnerKey = String((data && data.winnerVariantKey) || '').toUpperCase();
const suggested = String((data && data.suggestedWinner) || '').toUpperCase();
const variants = (data && Array.isArray(data.variants)) ? data.variants : [];

const pct = (v) => {
  if (v === undefined || v === null || v === '' || isNaN(Number(v))) {
    return '—';
  }
  return (Math.round(Number(v) * 10) / 10) + '%';
};
const num = (v) => Number(v || 0).toLocaleString('en-US');
const fmtDate = (ms) => {
  if (!ms || Number(ms) <= 0) {
    return '';
  }
  return new Date(Number(ms)).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
};

const pick = (key) => {
  const v = variants.find((x) => String(x.variantKey || '').toUpperCase() === key) || {};
  const isWinner = stopped && winnerKey === key;
  const isLost = stopped && !!winnerKey && winnerKey !== key;
  const isSuggested = running && suggested === key;
  const state = isWinner ? 'winner' : (isLost ? 'lost' : (isSuggested ? 'suggested' : 'neutral'));
  return {
    key: key,
    label: 'TEMPLATE ' + key,
    name: v.templateName || ('Template ' + key),
    assigned: num(v.assigned),
    sent: num(v.sent),
    delivered: num(v.delivered),
    openPct: pct(v.openPct),
    replyPct: pct(v.replyPct),
    meetings: num(v.meetings),
    state: state,
    badge: isWinner ? 'Winner' : (isLost ? 'Not chosen' : (isSuggested ? 'Suggested' : '')),
    summary: num(v.sent) + ' sent · ' + pct(v.openPct) + ' open · ' + pct(v.replyPct) + ' reply',
    present: !!v.variantKey,
  };
};

const A = pick('A');
const B = pick('B');
const cleanLabel = (s) => String(s || '').replace(/^Step\s*\?\s*·\s*/, '').replace(/^A\/B test\s*·\s*Step\s*\?\s*/, '');
const cleanOptions = stepOptions.map((o) => ({
  value: o.value,
  label: cleanLabel(o.label) || o.value,
}));
const currentStep = steps.find((s) => s && s.stepKey === (data && data.stepKey)) || {};
const currentOption = cleanOptions.find((o) => o.value === (data && data.stepKey)) || {};
const stepTitle = cleanLabel(currentStep.stepTitle || currentStep.title || '') || currentOption.label || cleanLabel((data && data.title) || '');
const declared = fmtDate(data && data.winnerDeclaredAt);
const winnerName = winnerKey === 'A' ? A.name : (winnerKey === 'B' ? B.name : '');
const statusDetail = stopped
  ? ('Winner: Template ' + (winnerKey || '—') + (winnerName ? ' (' + winnerName + ')' : '') + (declared ? ' · ' + declared : ''))
  : 'New prospects alternate between Template A and B';
const minSent = Number((data && data.minSentForSuggestion) || 20);
const reasonText = String((data && data.suggestedReason) || '');
const reason = running
  ? (suggested ? ('Suggested: Template ' + suggested + (reasonText ? ' · ' + reasonText : '')) : (reasonText || ('No suggestion until each template has ' + minSent + ' sends')))
  : (stopped ? ('Every prospect who reaches this step now gets Template ' + (winnerKey || '—') + '.') : '');

return {
  isLoading: isLoading,
  failed: failed,
  loaded: loaded,
  hasAb: hasAb,
  isEmpty: isEmpty,
  showPicker: hasAb && stepOptions.length > 1,
  running: running,
  stopped: stopped,
  statusLabel: stopped ? 'Stopped' : 'Running',
  statusState: stopped ? 'stopped' : 'running',
  statusDetail: statusDetail,
  stepTitle: stepTitle,
  stepKey: (data && data.stepKey) || '',
  stepOptions: cleanOptions,
  reason: reason,
  suggested: suggested,
  winnerKey: winnerKey,
  canStop: running && A.present && B.present,
  A: A,
  B: B,
};

func_5pZiA.functionBody:
// Delete step modal (b_9ckHw), opened from a step card's ⋯ menu in the Edit in Builder timeline (b_jMLCS).
// var editStepTarget holds the card's step (its edit target is under ['edit']). This works out the draft
// sequence without that step, and refuses the delete while a condition still watches the step.
var target = {{ var_uML2z['value'] }} || {};
var edit = target.edit || {};
var stepId = edit.stepId || '';
var res = ({{ e_6a55dd9de37aa80dd4a95737['data'] }} || {})['res'] || {};
var lock = {{ e_6addcd45925d282255282e61['data'] }} || {};
var blocks = Array.isArray(res.blocks) ? res.blocks : [];

var numberById = {};
var counter = 0;
for (var i = 0; i < blocks.length; i++) {
  var leaves = blocks[i].kind === 'conditional' ? (blocks[i].ifTrue || []).concat(blocks[i].else || []) : [blocks[i]];
  for (var j = 0; j < leaves.length; j++) {
    counter++;
    numberById[leaves[j].id] = counter;
  }
}

function watches(block) {
  var list = Array.isArray(block.conditions) ? block.conditions : [];
  for (var k = 0; k < list.length; k++) {
    if (list[k] && list[k].stepRef === stepId) {
      return true;
    }
  }
  return false;
}

var found = false;
var removedConditionDay = null;
var watchedBy = [];
var newBlocks = [];

for (var b = 0; b < blocks.length; b++) {
  var block = blocks[b];
  if (block.kind === 'conditional') {
    var ifSteps = (block.ifTrue || []).filter(function (s) { return s.id !== stepId; });
    var elseSteps = (block.else || []).filter(function (s) { return s.id !== stepId; });
    var hadStep = ifSteps.length !== (block.ifTrue || []).length || elseSteps.length !== (block.else || []).length;
    if (watches(block) && !hadStep) {
      var first = (block.ifTrue || [])[0] || (block.else || [])[0];
      watchedBy.push('the condition on Day ' + (block.day || 1) + (first && numberById[first.id] ? ' (it leads to Step ' + numberById[first.id] + ')' : ''));
    }
    if (hadStep) {
      found = true;
      if (ifSteps.length === 0 && elseSteps.length === 0) {
        removedConditionDay = block.day || 1;
        continue;
      }
      newBlocks.push(Object.assign({}, block, { ifTrue: ifSteps, else: elseSteps }));
      continue;
    }
    newBlocks.push(block);
  } else if (block.id === stepId) {
    found = true;
  } else {
    newBlocks.push(block);
  }
}

var number = numberById[stepId] || '';
var title = target.title || (edit.raw && edit.raw.title) || 'this step';
var locked = lock.locked === true;
var blocked = watchedBy.length > 0;

return {
  stepId: stepId,
  found: found,
  heading: number ? 'Delete Step ' + number + '?' : 'Delete this step?',
  message: '"' + title + '" on Day ' + (edit.day || 1) + ' is removed from the sequence draft. Prospects are affected only after you save the sequence.',
  conditionNote: removedConditionDay ? 'This is the last step under its condition, so the condition on Day ' + removedConditionDay + ' is removed too.' : '',
  blockedNote: blocked
    ? 'You can\'t delete this step yet: ' + watchedBy.join(' and ') + ' watches it. Change or remove that condition first.'
    : (locked ? 'This sequence is locked. Unlock it in Settings to delete steps.' : ''),
  canDelete: found && !blocked && !locked,
  newSequence: Object.assign({}, res, { blocks: newBlocks })
};

