func_laxwa.functionBody:
// Help line under the Time field (field2) of the Add step (b_Uj8wV standard, b_simvY conditional) and Edit step (b_EAFLO) forms.
// Follows the Settings 'Time zone' toggle (var timeZoneMode: 'owner' = Rep's, 'prospect' = Prospect's; empty = prospect, the page default).
// Rep's zone = this browser's zone (the page has no rep-settings source), shown as abbreviation + UTC offset, e.g. "IST (UTC+5:30)".
// Each form gets its own line with the time typed in its own field2, e.g. "Rep's time zone: 9:00 AM IST (UTC+5:30)".
// Prospect's mode also shows the viewer's current local time beside the rep's zone. It is taken on each run: the function
// re-runs when a form's data, the toggle, or the canvas event / selected step (set when Add or Edit step is clicked) changes.
const rawMode = {{ var_VZRuu['value'] }};
const mode = String(rawMode || 'prospect');

const read = function (get) {
  try {
    return get() || {};
  } catch (e) {
    return {};
  }
};
const stdTime = read(function () { return {{ b_Uj8wV['data'] }}; })['field2'];
const condTime = read(function () { return {{ b_simvY['data'] }}; })['field2'];
const editTime = read(function () { return {{ b_EAFLO['data'] }}; })['field2'];
// Read only so the function re-runs (and refreshes the current time) when Add step / Edit step is opened.
read(function () { return {{ var_CtMEb['value'] }}; });
read(function () { return {{ var_pCxV8['value'] }}; });

let zone = '';
try {
  zone = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
} catch (e) {
  zone = '';
}

const shortName = function (locale) {
  try {
    const parts = new Intl.DateTimeFormat(locale, { timeZone: zone || undefined, timeZoneName: 'short' }).formatToParts(new Date());
    const part = parts.find(function (p) { return p.type === 'timeZoneName'; });
    return part ? part.value : '';
  } catch (e) {
    return '';
  }
};

let abbr = '';
const locales = ['en-US', 'en-IN', 'en-GB', 'en-AU'];
for (let i = 0; i < locales.length && !abbr; i++) {
  const name = shortName(locales[i]);
  if (/^[A-Z]{2,6}$/.test(name) && name !== 'UTC') {
    abbr = name;
  }
}

const offsetMinutes = -new Date().getTimezoneOffset();
const sign = offsetMinutes < 0 ? '-' : '+';
const absMinutes = Math.abs(offsetMinutes);
const offset = 'UTC' + sign + Math.floor(absMinutes / 60) + ':' + String(absMinutes % 60).padStart(2, '0');

const repZone = abbr ? abbr + ' (' + offset + ')' : offset;

// "13:30:00", "13:30" or "1:30 PM" -> "1:30 PM"; anything else -> ''.
const formatTime = function (value) {
  const text = String(value || '').trim();
  const match = /^(\d{1,2}):(\d{2})(?::\d{2})?\s*([AaPp][Mm])?$/.exec(text);
  if (!match) {
    return '';
  }
  let hour = Number(match[1]);
  const minute = match[2];
  let suffix = match[3] ? match[3].toUpperCase() : '';
  if (!suffix) {
    if (hour > 23 || Number(minute) > 59) {
      return '';
    }
    suffix = hour >= 12 ? 'PM' : 'AM';
    hour = hour % 12 === 0 ? 12 : hour % 12;
  }
  return hour + ':' + minute + ' ' + suffix;
};

const now = new Date();
const nowTime = formatTime(now.getHours() + ':' + String(now.getMinutes()).padStart(2, '0'));

const hintFor = function (value) {
  const time = formatTime(value);
  if (mode === 'owner') {
    return "Rep's time zone: " + (time ? time + ' ' : '') + repZone;
  }
  return "Prospect's time zone" + (time ? ': ' + time : '') + " · Rep's time zone: " + (nowTime ? nowTime + ' ' : '') + repZone;
};

return {
  mode: mode,
  repZone: repZone,
  nowTime: nowTime,
  hint: hintFor(''),
  hintStd: hintFor(stdTime),
  hintCond: hintFor(condTime),
  hintEdit: hintFor(editTime),
};

