func_Jwh8t.functionBody:
// "Choose the winning email" modal (b_EZg42), opened from the "Stop A/B test" button on an email step card
// in the Edit in Builder timeline (b_jMLCS). That button sets abStopFocusStepId (var_elcto), so the modal lists only that step.
// A running A/B test = an email step in the DRAFT sequence (fetch_sequence_json) with abTestEnabled true,
// no completed abResult, and its sdr_step_variants rows A and B both still active (no winner yet).
var MIN_SENDS = 20;
var res = ({{ e_6a55dd9de37aa80dd4a95737['data'] }} || {})['res'] || {};
var blocks = Array.isArray(res.blocks) ? res.blocks : [];
var variantRows = ({{ e_6adf5394dc07493166cf4b9d['data'] }} || {})['objects'] || [];
var templateRows = ({{ e_6ad9fb281a10ec0c912e7759['data'] }} || {})['objects'] || [];
var versionRows = ({{ e_6ad9fb28a965b115459b662c['data'] }} || {})['objects'] || [];
var lock = {{ e_6addcd45925d282255282e61['data'] }} || {};
var focusStepId = {{ var_elcto['value'] }} || '';

function templateName(templateId) {
  if (!templateId) {
    return '';
  }
  for (var i = 0; i < templateRows.length; i++) {
    if (templateRows[i] && templateRows[i].id === templateId) {
      return (templateRows[i].properties || {}).templateHeading || '';
    }
  }
  return '';
}

function rowProps(rows, id) {
  if (!id) {
    return null;
  }
  for (var i = 0; i < rows.length; i++) {
    if (rows[i] && rows[i].id === id) {
      return rows[i].properties || {};
    }
  }
  return null;
}

// The subject line the variant sends: step override (Template A only), else the version's, else the template's.
function subjectFor(step, key, templateId, versionId) {
  var cfg = step.emailConfig || {};
  if (key === 'A' && cfg.subjectOverride) {
    return cfg.subjectOverride;
  }
  var v = rowProps(versionRows, versionId);
  var t = rowProps(templateRows, templateId);
  return (v && v.subject) || (t && t.subject) || '';
}

function pct(part, whole) {
  if (!whole) {
    return 0;
  }
  return Math.round((part / whole) * 1000) / 10;
}

function rowFor(stepId, key) {
  for (var i = 0; i < variantRows.length; i++) {
    var p = (variantRows[i] && variantRows[i].properties) || {};
    if (p.stepId === stepId && String(p.variantKey || '').toUpperCase() === key) {
      return p;
    }
  }
  return null;
}

function stepVariant(step, key) {
  var list = Array.isArray(step.variants) ? step.variants : [];
  for (var i = 0; i < list.length; i++) {
    if (list[i] && String(list[i].variantKey || '').toUpperCase() === key) {
      return list[i];
    }
  }
  return {};
}

function variantView(step, key, row) {
  var sent = Number(row.sentCount || 0);
  var opens = Number(row.openCount || 0);
  var replies = Number(row.replyCount || 0);
  var meetingsRaw = row.meetingCount != null ? row.meetingCount : row.meetingsCount;
  var hasMeetings = meetingsRaw != null && meetingsRaw !== '';
  var templateId = row.templateId || stepVariant(step, key).templateId || (key === 'A' ? step.templateId : '');
  var name = templateName(templateId) || ('Template ' + key);
  var openPct = pct(opens, sent);
  var replyPct = pct(replies, sent);
  var versionId = row.templateVersionId || stepVariant(step, key).templateVersionId || (key === 'A' ? step.templateVersionId : '');
  var subject = subjectFor(step, key, templateId, versionId);
  return {
    key: key,
    label: 'Template ' + key,
    name: name,
    subjectText: subject ? 'Subject: ' + subject : 'No subject line saved',
    sent: sent,
    openPct: openPct,
    replyPct: replyPct,
    sentText: String(sent),
    openText: sent > 0 ? openPct + '%' : '—',
    replyText: sent > 0 ? replyPct + '%' : '—',
    meetingsText: hasMeetings ? String(meetingsRaw) : '—',
    statsLine: 'Sent ' + sent + '  ·  Open ' + (sent > 0 ? openPct + '%' : '—') + '  ·  Reply ' + (sent > 0 ? replyPct + '%' : '—') + (hasMeetings ? '  ·  Meetings ' + meetingsRaw : '')
  };
}

var running = [];
var stepNumber = 0;
for (var bi = 0; bi < blocks.length; bi++) {
  var block = blocks[bi] || {};
  var leaves = block.kind === 'conditional' ? (block.ifTrue || []).concat(block.else || []) : [block];
  for (var li = 0; li < leaves.length; li++) {
    var step = leaves[li] || {};
    stepNumber++;
    if (focusStepId && step.id !== focusStepId) {
      continue;
    }
    if (String(step.type || '').toLowerCase() !== 'email' || step.abTestEnabled !== true) {
      continue;
    }
    if (step.abResult && String(step.abResult.status || '').toLowerCase() === 'completed') {
      continue;
    }
    var rowA = rowFor(step.id, 'A');
    var rowB = rowFor(step.id, 'B');
    if (!rowA || !rowB) {
      continue;
    }
    if ((rowA.status || 'active') !== 'active' || (rowB.status || 'active') !== 'active') {
      continue;
    }
    var a = variantView(step, 'A', rowA);
    var b = variantView(step, 'B', rowB);
    var enough = a.sent >= MIN_SENDS && b.sent >= MIN_SENDS;
    // Highlight the higher open and reply rate once both templates have sent something.
    var bothSent = a.sent > 0 && b.sent > 0;
    a.betterOpen = bothSent && a.openPct > b.openPct;
    b.betterOpen = bothSent && b.openPct > a.openPct;
    a.betterReply = bothSent && a.replyPct > b.replyPct;
    b.betterReply = bothSent && b.replyPct > a.replyPct;
    var fewA = a.sent < MIN_SENDS;
    var fewB = b.sent < MIN_SENDS;
    var collectingText = fewA && fewB
      ? 'Not enough data yet — fewer than ' + MIN_SENDS + ' sends on each. You can still pick a winner.'
      : 'Not enough data yet — Template ' + (fewA ? 'A' : 'B') + ' has fewer than ' + MIN_SENDS + ' sends. You can still pick a winner.';
    var suggested = '';
    if (enough) {
      if (a.replyPct !== b.replyPct) {
        suggested = a.replyPct > b.replyPct ? 'A' : 'B';
      } else if (a.openPct !== b.openPct) {
        suggested = a.openPct > b.openPct ? 'A' : 'B';
      }
    }
    running.push({
      stepId: step.id,
      title: step.title || 'Email step',
      heading: 'Step ' + stepNumber + '  ·  Day ' + (step.day || block.day || 1),
      A: a,
      B: b,
      suggested: suggested,
      collecting: !enough,
      collectingText: enough ? '' : collectingText,
      suggestedText: suggested ? 'Template ' + suggested + ' has the higher ' + ((a.replyPct !== b.replyPct) ? 'reply rate' : 'open rate') + ', so we suggest it.' : '',
      tieNote: enough && !suggested ? 'Both templates have the same open and reply rates so far. Pick the one you prefer.' : ''
    });
  }
}

return {
  steps: running,
  count: running.length,
  hasRunning: running.length > 0,
  focusStepId: focusStepId,
  locked: lock.locked === true
};

