func_BeYBO.functionBody:
const raw = {{ e_6a561e9d87cd3b7aa8c4777d['data'] }}?.previousSteps || [];
const form = {{ b_simvY['data'] }} || {};
const rowCount = Math.min(Math.max(Number({{ var_CYkn7['value'] }}) || 1, 1), 5);

// Call outcomes come from Admin Settings (sdr_sync_settings org_call_settings) through orgCallOutcomes (func_K6LL3): every outcome, hidden ones marked, stored by code.
const ORG_CALL = {{ func_K6LL3['value'] }} || {};
const ORG_CALL_LABELS = ORG_CALL.labels || {};
const ORG_CALL_PAIRS = (Array.isArray(ORG_CALL.options) && ORG_CALL.options.length ? ORG_CALL.options : [
  { id: 'no_answer', name: 'No Answer' },
  { id: 'left_voicemail', name: 'Left Voicemail' },
  { id: 'gatekeeper', name: 'Gatekeeper' },
  { id: 'bad_number', name: 'Bad Number' },
  { id: 'no_longer_with_company', name: 'No Longer with Company' },
  { id: 'answered_wrong_poc', name: 'Answered – Wrong Person' },
  { id: 'answered_not_interested', name: 'Answered – Not Interested' },
  { id: 'answered_referral', name: 'Answered – Referral' },
  { id: 'answered_call_back', name: 'Answered – Call Back' },
  { id: 'answered_meeting_set', name: 'Answered – Meeting Set' },
  { id: 'answered_other', name: 'Answered – Other' },
]).map(function (item) {
  return [item.id, item.name];
});

const TYPE_LABELS = {
  email: 'Email',
  call: 'Call',
  meeting: 'Meeting',
  linkedin: 'LinkedIn',
  task: 'Task',
};
const CONDITIONS = {
  email: [
    ['sent', 'Sent'],
    ['not-sent', 'Not sent'],
    ['opened', 'Opened'],
    ['not-opened', 'Not opened'],
    ['replied', 'Replied'],
    ['no-reply', 'Not replied'],
    ['bounced', 'Bounced'],
  ],
  call: [
    ['call_done', 'Done'],
    ['call_not_done', 'Not done'],
    ['call_skipped', 'Skipped'],
    ['call_outcome', 'Outcome is …'],
  ],
  meeting: [
    ['meeting_booked', 'Booked'],
    ['meeting_not_booked', 'Not booked'],
    ['meeting_held', 'Held'],
    ['meeting_no_show', 'No-show'],
    ['meeting_outcome', 'Outcome is …'],
    ['meeting_skipped', 'Skipped'],
  ],
  linkedin: [
    ['linkedin_sent', 'Sent'],
    ['linkedin_not_sent', 'Not sent'],
    ['linkedin_skipped', 'Skipped'],
  ],
  task: [
    ['task_done', 'Done'],
    ['task_not_done', 'Not done'],
    ['task_skipped', 'Skipped'],
  ],
};
const OUTCOMES = {
  call_outcome: ORG_CALL_PAIRS,
  meeting_outcome: [
    ['qualified', 'Qualified'],
    ['not_qualified', 'Not qualified'],
    ['opp_created', 'Opportunity created'],
    ['rescheduled', 'Rescheduled'],
  ],
};

const outcomePairs = function (event, picked) {
  const base = OUTCOMES[event] || [];
  if (event !== 'call_outcome') {
    return base;
  }
  // A saved code that is no longer in the list still shows as selected.
  const extra = (picked || []).filter(function (code) {
    return !base.some(function (pair) { return pair[0] === code; });
  }).map(function (code) {
    return [code, ORG_CALL_LABELS[code] || code];
  });
  return base.concat(extra);
};
const toOptions = function (pairs) {
  return (pairs || []).map(function (pair) {
    return { id: pair[0], name: pair[1] };
  });
};
const normType = function (value) {
  const text = String(value || '').trim().toLowerCase();
  if (text.indexOf('linkedin') === 0) {
    return 'linkedin';
  }
  return CONDITIONS[text] ? text : '';
};

const steps = (Array.isArray(raw) ? raw : [])
  .map(function (row) {
    const type = normType(row && (row.type || row.actionType));
    const day = row && (row.dayNumber ?? row.day);
    const parts = [];
    if (day !== undefined && day !== null && day !== '') {
      parts.push('Day ' + day);
    }
    if (TYPE_LABELS[type]) {
      parts.push(TYPE_LABELS[type]);
    }
    parts.push((row && row.title) || 'Untitled step');
    return {
      id: String((row && (row.taskId || row.stepId || row.id)) || ''),
      type: type,
      name: parts.join(' · '),
    };
  })
  .filter(function (step) { return step.id; });

const typeOf = function (stepId) {
  const step = steps.find(function (item) { return item.id === stepId; });
  return (step && step.type) || 'email';
};

const ROWS = [
  { name: 'c1', step: 'field3', event: 'field5', outcomes: 'c1Outcomes' },
  { name: 'c2', step: 'c2Step', event: 'c2Event', outcomes: 'c2Outcomes' },
  { name: 'c3', step: 'c3Step', event: 'c3Event', outcomes: 'c3Outcomes' },
  { name: 'c4', step: 'c4Step', event: 'c4Event', outcomes: 'c4Outcomes' },
  { name: 'c5', step: 'c5Step', event: 'c5Event', outcomes: 'c5Outcomes' },
];

const rows = {};
const conditions = [];
let ready = true;

ROWS.forEach(function (def, index) {
  const stepId = form[def.step];
  const event = form[def.event];
  const type = stepId ? typeOf(stepId) : '';
  const allowed = stepId ? CONDITIONS[type] : [];
  const picked = Array.isArray(form[def.outcomes]) ? form[def.outcomes].filter(Boolean) : [];
  rows[def.name] = {
    conditions: toOptions(allowed),
    outcomes: toOptions(outcomePairs(event, picked)),
  };
  if (index >= rowCount) {
    return;
  }
  if (!stepId && !event && index > 0) {
    return;
  }
  const valid = !!stepId && !!event && allowed.some(function (pair) { return pair[0] === event; });
  if (!valid) {
    ready = false;
    return;
  }
  if (OUTCOMES[event]) {
    if (!picked.length) {
      ready = false;
      return;
    }
    conditions.push({ event: event + ':' + picked.join(','), stepRef: stepId });
    return;
  }
  conditions.push({ event: event, stepRef: stepId });
});

// What the remove button of each row writes: rows below move up one place.
// Outcomes are written a moment later, once their row shows the outcome field again.
const remove = {};
ROWS.forEach(function (def, index) {
  const reset = [];
  const set = [];
  const outcomes = [];
  for (let at = index; at < rowCount; at += 1) {
    reset.push(ROWS[at].step, ROWS[at].event, ROWS[at].outcomes);
    const from = ROWS[at + 1];
    if (!from || at + 1 >= rowCount) {
      continue;
    }
    if (form[from.step]) {
      set.push({ fieldId: ROWS[at].step, value: form[from.step] });
    }
    if (form[from.event]) {
      set.push({ fieldId: ROWS[at].event, value: form[from.event] });
    }
    if (Array.isArray(form[from.outcomes]) && form[from.outcomes].length) {
      outcomes.push({ fieldId: ROWS[at].outcomes, value: form[from.outcomes] });
    }
  }
  remove['r' + (index + 1)] = { reset: reset, set: set, outcomes: outcomes };
});

return {
  steps: steps,
  c1: rows.c1,
  c2: rows.c2,
  c3: rows.c3,
  c4: rows.c4,
  c5: rows.c5,
  rowCount: rowCount,
  remove: remove,
  operator: rowCount > 1 && form.matchOperator === 'OR' ? 'OR' : 'AND',
  conditions: conditions,
  first: conditions[0] || null,
  ready: ready && conditions.length > 0 ? 'yes' : 'no',
};

