// Day rules for the Add step (b_pcaKt) and Edit step (b_wzNyk) modals, same rules as Create Sequence.
// Reads the sequence the edit canvas b_EBkkf shows (fetch_sequence_json) and the canvas event (updateValues).
const seq = {{ e_6a55dd9de37aa80dd4a95737['data'] }}?.res || {};
const event = {{ var_CtMEb['value'] }} || {};
const operation = String(event.operation || '');
const isNewDay = event.mode === 'new_day';
const blocks = Array.isArray(seq.blocks) ? seq.blocks : [];

const days = [];
const collect = function (node) {
  if (Array.isArray(node)) {
    node.forEach(collect);
    return;
  }
  if (!node || typeof node !== 'object') {
    return;
  }
  const day = Number(node.day ?? node.dayNumber);
  if (Number.isInteger(day) && day > 0 && days.indexOf(day) === -1) {
    days.push(day);
  }
  Object.keys(node).forEach(function (key) {
    if (node[key] && typeof node[key] === 'object') {
      collect(node[key]);
    }
  });
};
collect(blocks);
days.sort(function (left, right) { return left - right; });

const maxDay = days.length ? days[days.length - 1] : 0;
const onMaxDay = blocks.filter(function (block) { return block && Number(block.day) === maxDay; });
const lastBlockId = onMaxDay.length ? onMaxDay[onMaxDay.length - 1].id : '';

const pickedDay = event.day === '' || event.day === null || event.day === undefined ? NaN : Number(event.day);
const hasPickedDay = Number.isInteger(pickedDay) && pickedDay > 0;

// "Add step here" under a day: that day or any later one, or an earlier day that no step uses yet.
// "Add day": any whole number, 1 or more, that no step uses yet (lower than the highest is fine).
// A day exists when at least one step has it. The server (Add / Edit Step, Save Sequence) checks again.
const anchorAdd = operation === 'add_step' && !isNewDay && hasPickedDay;
const lockAdd = false;
// Edit step, and a branch step under an existing day: the day never changes once set.
const lockEdit = operation === 'edit_step' || (operation === 'add_branch_step' && hasPickedDay);
// minAddDay is kept for older readers: the order rule is now "a day not used yet" (dayAllowed).
const addMin = 1;
const usedText = days.length ? 'Days already used: ' + days.join(', ') : '';
const pickText = anchorAdd
  ? 'Pick Day ' + pickedDay + ' or later, or an earlier day not used yet'
  : 'Pick a day not used yet';
const laterDayMessage = 'Day must be a whole number, 1 or more';
const addDayMessage = 'That day already exists. ' + pickText;

const dayAllowed = function (n) {
  if (anchorAdd && n >= pickedDay) {
    return true;
  }
  return days.indexOf(n) === -1;
};

// The message under the Day field while the person types, '' when the value is fine.
const dayError = function (raw, checkExisting) {
  const text = raw === undefined || raw === null ? '' : String(raw).trim();
  if (!text) {
    return '';
  }
  if (!/^[1-9][0-9]*$/.test(text)) {
    return 'Day must be a whole number, 1 or more';
  }
  const n = Number(text);
  if (checkExisting && !dayAllowed(n)) {
    return 'Day ' + n + ' already exists. ' + pickText;
  }
  return '';
};

return {
  days: days,
  maxDay: maxDay,
  nextDay: maxDay + 1,
  lastBlockId: lastBlockId,
  anchorDay: anchorAdd ? pickedDay : null,
  lockAdd: lockAdd ? 'yes' : 'no',
  lockEdit: lockEdit ? 'yes' : 'no',
  minAddDay: addMin,
  dayMessage: addDayMessage,
  usedDays: usedText,
  hints: {
    add: pickText + (usedText ? ' · ' + usedText : ''),
    edit: operation === 'edit_step'
      ? 'Day cannot be changed after a step is created'
      : (lockEdit ? 'Day ' + pickedDay + ' is set by where you added this step' : ''),
  },
  errors: {
    addStandard: dayError({{ b_Uj8wV['data'] }}?.field1, true),
    addConditional: dayError({{ b_simvY['data'] }}?.field1, true),
    edit: dayError({{ b_EAFLO['data'] }}?.field1, false),
  },
};

