};
const toHtml = function (value) {
  const text = String(value || '');
  if (!text.trim()) {
    return '';
  }
  if (/<(p|div|br|ul|ol|li|h[1-6]|table|span|strong|em|b|i|u|a)\b/i.test(text)) {
    return text;
  }
  return text
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map(function (line) {
      return line.trim() ? '<p>' + escapeHtml(line) + '</p>' : '<p></p>';
    })
    .join('');
};

const group = function (pick, savedStep) {
  const templateId = pick.templateId || '';
  const list = versionRows
    .filter(function (row) {
      return row && row.properties && templateId && row.properties.templateId === templateId;
    })
    .sort(function (a, b) {
      return Number(b.properties.version || 0) - Number(a.properties.version || 0);
    });
  const latestId = list.length ? list[0].id : undefined;
  const sameTemplate = !!savedStep && !!templateId && savedStep.templateId === templateId;
  const savedVersionId = sameTemplate && list.some(function (row) { return row.id === savedStep.templateVersionId; })
    ? savedStep.templateVersionId
    : undefined;
  const defaultVersionId = savedVersionId || latestId;
  const activeId = pick.versionId || defaultVersionId;
  const active = list.find(function (row) { return row.id === activeId; });
  const template = templateRows.find(function (row) { return row.id === templateId; });
  const source = (active && active.properties) || (template && template.properties) || {};

  let subject = source.subject || '';
  let body = toHtml(source.body);
  let message = toText(source.body);
  let script = toText(source.body);
  const keepSaved = !!savedStep && (!templateId || (sameTemplate && (!activeId || activeId === (savedVersionId || latestId))));
  if (keepSaved) {
    // An A/B step keeps variant A's own text (the server mirrors it into emailConfig too).
    const savedA = savedStep.abTestEnabled === true && Array.isArray(savedStep.variants)
      ? (savedStep.variants.find(function (v) { return v && v.variantKey === 'A'; }) || {})
      : {};
    subject = savedA.subjectOverride || savedStep?.emailConfig?.subjectOverride || subject;
    body = toHtml(savedA.bodyOverride) || toHtml(savedStep?.emailConfig?.bodyOverride) || body;
    message = savedStep?.linkedInConfig?.draftMessage || message;
    script = savedStep?.callConfig?.callScript || script;
  }

  return {
    options: list.map(function (row) {
      return {
        id: row.id,
        name: versionLabel(row) + (row.id === latestId ? ' (latest)' : ''),
      };
    }),
    latestId: latestId,
    defaultVersionId: defaultVersionId,
    subject: subject,
    body: body,
    message: message,
    script: script,
  };
};

return {
  templates: named.map(toOption),
  add: group(picks.add, null),
  edit: group(picks.edit, saved),
  ifTrue: group(picks.ifTrue, null),
  elseBranch: group(picks.elseBranch, null),
};

func_krWs7.functionBody:
const rows = {{ b_4eWPg['currentData'] }} || [];
const steps = ({{ e_6adb45ba0881d2257a7c6d88['data'] }} || {})['objects'] || [];
const tasks = ({{ e_6adb45ba925d28225526a82c['data'] }} || {})['objects'] || [];
const rules = ({{ e_6adb45ba925d28225526a839['data'] }} || {})['objects'] || [];

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const TYPE_LABELS = {
  email: 'Email',
  call: 'Call',
  linkedin: 'LinkedIn',
  task: 'Task',
  generic: 'Task',
  meeting: 'Meeting',
};
const PAUSE_LABELS = {
  out_of_office: 'Out of office',
  manual: 'Paused manually',
  bounce_rate: 'Bounce rate',
  holiday: 'Holiday',
};
const EXIT_LABELS = {
  reply: 'Replied',
  meeting_booked: 'Meeting booked',
  call_meeting_set: 'Meeting set on call',
  call_not_interested: 'Not interested',
  left_company: 'Left company',
  wrong_person: 'Wrong person',
  referral: 'Referred',
  opportunity_created: 'Opportunity created',
  unsubscribed: 'Unsubscribed',
  hard_bounce: 'Hard bounce',
  stage_closed: 'Stage closed',
  stage_nurture: 'Moved to nurture',
  stage_do_not_contact: 'Do not contact',
  account_level: 'Account exit',
  health_threshold: 'Health threshold',
  manual: 'Exited manually',
  natural_finish: 'Finished',
  duplicate: 'Duplicate',
  ai_handoff: 'AI handoff',
};
const SOURCE_LABELS = {
  manual: 'Manual',
  rule: 'Rule',
  recycle: 'Recycled',
  api: 'API',
  ai_sdr: 'AI SDR',
};

const toDate = function (value) {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const date = new Date(typeof value === 'string' && /^\d+$/.test(value) ? Number(value) : value);
  return isNaN(date.getTime()) ? null : date;
};
const pad = function (n) {
  return n < 10 ? '0' + n : String(n);
};
const dayMonth = function (date) {
  return date.getDate() + ' ' + MONTHS[date.getMonth()];
};
const fullDate = function (date) {
  return dayMonth(date) + ' ' + date.getFullYear();
};
const touchTime = function (date) {
  return DAYS[date.getDay()] + ' ' + dayMonth(date) + ', ' + pad(date.getHours()) + ':' + pad(date.getMinutes());
};
const relative = function (date) {
  const diff = Date.now() - date.getTime();
  const minutes = Math.round(diff / 60000);
  if (minutes < 1) {
    return 'just now';
  }
  if (minutes < 60) {
    return minutes + (minutes === 1 ? ' minute ago' : ' minutes ago');
  }
  const hours = Math.round(minutes / 60);
  if (hours < 24) {
    return hours + (hours === 1 ? ' hour ago' : ' hours ago');
  }
  const days = Math.round(hours / 24);
  if (days < 30) {
    return days + (days === 1 ? ' day ago' : ' days ago');
  }
  const months = Math.round(days / 30);
  if (months < 12) {
    return months + (months === 1 ? ' month ago' : ' months ago');
  }
  const years = Math.round(months / 12);
  return years + (years === 1 ? ' year ago' : ' years ago');
};
const typeLabel = function (value) {
  const key = String(value || '').toLowerCase();
  return TYPE_LABELS[key] || (value ? String(value) : '');
};

const stepsByVersion = {};
steps.forEach(function (step) {
  const p = step['properties'] || {};
  if (!p['versionId']) {
    return;
  }
  (stepsByVersion[p['versionId']] = stepsByVersion[p['versionId']] || []).push(p);
});
Object.keys(stepsByVersion).forEach(function (key) {
  stepsByVersion[key].sort(function (a, b) {
    return (Number(a['stepNumber']) || 0) - (Number(b['stepNumber']) || 0);
  });
});

const tasksByEnrolment = {};
tasks.forEach(function (task) {
  const p = task['properties'] || {};
  if (!p['enrollmentId']) {
    return;
  }
  (tasksByEnrolment[p['enrollmentId']] = tasksByEnrolment[p['enrollmentId']] || []).push(p);
});

const ruleNames = {};
rules.forEach(function (rule) {
  ruleNames[rule['id']] = (rule['properties'] || {})['name'];
});

const pathOf = function (step) {
  const conditions = Array.isArray(step && step['condition']) ? step['condition'] : [];
  if (!conditions.length) {
    return '';
  }
  const parts = conditions.map(function (c) {
    const name = String((c && c['conditionName']) || '').split(':')[0].replace(/_/g, ' ');
    return (c && c['operator'] === 'NOT' ? 'not ' : '') + name;
  }).filter(Boolean);
  return parts.length ? 'IF ' + parts.join(step['mainOperator'] === 'OR' ? ' or ' : ' and ') : '';
};

const byId = {};
rows.forEach(function (row) {
  const p = row['properties'] || {};
  const status = p['status'];
  const versionSteps = stepsByVersion[p['sequenceVersionId']] || [];
  const curNumber = p['cur_step'] !== undefined && p['cur_step'] !== null && p['cur_step'] !== '' ? Number(p['cur_step']) : null;
  const active = status === 'PENDING' || status === 'IN_PROGRESS' || status === 'PAUSED';
  const enrolmentTasks = tasksByEnrolment[row['id']] || [];

  let statusLabel = 'Pending';
  let statusTone = 'gray';
  let statusReason = '';
  const finished = toDate(p['finishedAt']);
  if (p['failureReason']) {
    statusLabel = 'Failed';
    statusTone = 'error';
    statusReason = String(p['failureReason']);
  } else if (status === 'IN_PROGRESS') {
    statusLabel = 'Active';
    statusTone = 'blue';
  } else if (status === 'PAUSED') {
    statusLabel = 'Paused';
    statusTone = 'warning';
    const until = toDate(p['pausedUntil']);
    statusReason = [PAUSE_LABELS[p['pauseReason']] || '', until ? 'until ' + dayMonth(until) : ''].filter(Boolean).join(' · ');
  } else if (status === 'COMPLETED') {
    statusLabel = 'Finished – no reply';
    statusTone = 'success';
    statusReason = finished ? dayMonth(finished) : '';
  } else if (status === 'MATCHED_EXIT_CONDITION' || status === 'CANCELLED') {
    statusLabel = 'Exited';
    statusTone = 'purple';
    statusReason = [EXIT_LABELS[p['exitReason']] || (p['exitReason'] ? String(p['exitReason']) : ''), finished ? dayMonth(finished) : ''].filter(Boolean).join(' · ');
  }

  const current = curNumber !== null ? versionSteps.find(function (s) { return Number(s['stepNumber']) === curNumber; }) : null;
  let stepLabel = '—';
  let stepPath = '';
  if (current) {
    stepLabel = ['Step ' + current['stepNumber'], typeLabel(current['taskType']), current['dayNumber'] !== undefined && current['dayNumber'] !== null ? 'D' + current['dayNumber'] : ''].filter(Boolean).join(' · ');
    stepPath = pathOf(current);
  } else if (curNumber !== null) {
    stepLabel = 'Step ' + curNumber;
    stepPath = p['currentStep'] ? String(p['currentStep']) : '';
  } else if (status === 'PENDING') {
    stepLabel = 'Not started';
  }

  let nextLabel = '—';
  let nextWhen = '';
  if (active) {
    const next = versionSteps.find(function (s) {
      return Number(s['stepNumber']) > (curNumber === null ? 0 : curNumber);
    });
    const nextAt = toDate(p['nextTouchAt']);
    if (next) {
      nextLabel = 'Step ' + next['stepNumber'] + ' · ' + typeLabel(next['taskType']);
    } else if (nextAt) {
      nextLabel = 'Next touch';
    }
    nextWhen = nextAt ? touchTime(nextAt) : '';
  }

  let opened = false;
  let clicked = false;
  let replied = !!p['firstReplyAt'] || p['exitReason'] === 'reply';
  let callConnected = p['exitReason'] === 'call_meeting_set' || p['exitReason'] === 'call_not_interested';
  let lastDone = null;
  enrolmentTasks.forEach(function (t) {
    (Array.isArray(t['emailActivity']) ? t['emailActivity'] : []).forEach(function (a) {
      if (a && a['emailOpened']) {
        opened = true;
      }
      if (a && a['emailReplied']) {
        replied = true;
      }
      if (a && a['emailClicked']) {
        clicked = true;
      }
    });
    if (Number(t['clickCount']) > 0) {
      clicked = true;
    }
    if (String(t['taskType'] || '').toLowerCase() === 'call' && /connect|meeting|interested/i.test(String(t['outcome'] || ''))) {
      callConnected = true;
    }
    if (t['taskStatus'] === 'completed' && t['completedAt'] && (!lastDone || Number(t['completedAt']) > Number(lastDone['completedAt']))) {
      lastDone = t;
    }
  });
  if (clicked || replied) {
    opened = true;
  }

  const lastAt = toDate(p['lastTouchedAt']);
  const lastText = lastAt ? [relative(lastAt), lastDone ? typeLabel(lastDone['taskType']) : ''].filter(Boolean).join(' · ') : '—';

  const enrolledAt = toDate(p['enrolledAt'] || row['createdTime']);
  let sourceLabel = SOURCE_LABELS[p['source']] || (p['source'] ? String(p['source']) : '');
  if (p['source'] === 'rule' && ruleNames[p['ruleId']]) {
    sourceLabel = 'Rule: ' + ruleNames[p['ruleId']];
  }

  byId[row['id']] = {
    statusLabel: statusLabel,
    statusTone: statusTone,
    statusReason: statusReason,
    stepLabel: stepLabel,
    stepPath: stepPath,
    nextLabel: nextLabel,
    nextWhen: nextWhen,
    opened: opened,
    clicked: clicked,
    replied: replied,
    callConnected: callConnected,
    lastTouched: lastText,
    enrolledDate: enrolledAt ? fullDate(enrolledAt) : '—',
    enrolledSource: sourceLabel,
  };
});

return byId;

func_ogvdP.functionBody:
// Link prospects: the "Some prospects weren't added" dialog (b_ skipDialog modal).
// var skipDialogSource names the result to show: 'manual' = AddProspectManually,
// 'aiRule' = aiEnrollProspects, 'aiSelected' = aiEnrollSelected.
const source = {{ var_5wbKC['value'] }} || '';
const read = function (getData) {
  try {
    return getData() || {};
  } catch (e) {
    return {};
  }
};
const manual = read(function () { return {{ e_6a54e5c287cd3b7aa8baf3c6['data'] }}; });
const aiRule = read(function () { return {{ e_6ada1f5e1a10ec0c91345a35['data'] }}; });
const aiSelected = read(function () { return {{ e_6ada33ef1a10ec0c91368ae1['data'] }}; });
const orgRows = read(function () { return {{ e_6adfc893b373722e3cb0617c['data'] }}; })['objects'] || [];

// Refusal codes from SDR | Enroll Prospect, in plain words.
const PHRASES = {
  IN_OTHER_ACTIVE_SEQUENCE: 'Already active in another sequence',
  OWNED_BY_ANOTHER_REP: 'Owned by another rep',
  OPEN_OPPORTUNITY: 'Has an open opportunity',
  MAX_ACTIVE_SEQUENCES: 'Already in the maximum number of active sequences',
  OPTED_OUT: 'Has opted out of contact',
  DO_NOT_CONTACT: 'On the do-not-contact list',
  UNSUBSCRIBED_FROM_SEQUENCE: 'Unsubscribed from this sequence',
  PROSPECT_ARCHIVED: 'Archived',
  SEQUENCE_ARCHIVED: 'This sequence is archived',
  NO_PUBLISHED_VERSION: 'This sequence has no published version',
  REENROLMENT_DISABLED: 'Re-enrolment is turned off by admin',
  REENROL_COOLDOWN: 'In the re-enrolment cooldown for this sequence',
};
const tidy = function (phrase) {
  const text = String(phrase || '').trim().replace(/\.$/, '').replace(/^is /, '');
  return text ? text.charAt(0).toUpperCase() + text.slice(1) : 'Could not be added';
};

// "N prospects weren't added. A wasn't added: x; y. B wasn't added: z. To add them, ..."
const parseMessage = function (message) {
  let text = String(message || '').replace(/^ERROR:\s*/, '').trim();
  const hintAt = text.indexOf(' To add them,');
  if (hintAt >= 0) {
    text = text.slice(0, hintAt).trim();
  }
  text = text.replace(/^\d+ prospects weren't added\.\s*/, '');
  // Each line is "<name> wasn't added: <reasons>." A reason ends at the first ". " after its marker.
  const MARK = " wasn't added: ";
  const out = [];
  let cursor = 0;
  let at = text.indexOf(MARK, cursor);
  while (at >= 0) {
    const name = text.slice(cursor, at).trim();
    const from = at + MARK.length;
    const next = text.indexOf(MARK, from);
    let stop = text.length;
    if (next >= 0) {
      const dot = text.indexOf('. ', from);
      stop = dot >= 0 && dot < next ? dot + 1 : next;
    }
    out.push({
      name: name || 'This prospect',
      reason: text.slice(from, stop).trim().replace(/\.$/, '').split('; ').map(tidy).join(' · '),
    });
    cursor = stop;
    at = next;
  }
  return out;
};

let rows = [];
let added = null;
if (source === 'manual') {
  const res = String(manual['res'] || '');
  if (res.indexOf('ERROR') === 0) {
    rows = parseMessage(manual['message'] || res);
  }
} else if (source === 'aiRule' || source === 'aiSelected') {
  const data = source === 'aiRule' ? aiRule : aiSelected;
  const skipped = Array.isArray(data['skipped']) ? data['skipped'] : [];
  rows = skipped.map(function (s) {
    const codes = Array.isArray(s && s.reasons) ? s.reasons : [];
    const words = [];
    codes.forEach(function (code) {
      const phrase = PHRASES[String(code)] || tidy(String(code).toLowerCase().replace(/_/g, ' '));
      if (words.indexOf(phrase) === -1) {
        words.push(phrase);
      }
    });
    return {
      name: String((s && s.prospectName) || 'This prospect'),
      reason: words.length ? words.join(' · ') : 'Could not be added',
      codes: codes,
    };
  });
  if (!rows.length && Number(data['skippedCount']) > 0) {
    rows = parseMessage(data['message']);
    if (!rows.length) {
      rows = [{
        name: data['skippedCount'] + ' prospects',
        reason: tidy(data['message'] || 'Could not be added'),
      }];
    }
  }
  added = Number(data['enrolledCount']) || 0;
}

const anyActive = rows.some(function (r) {
  return (r.codes || []).indexOf('IN_OTHER_ACTIVE_SEQUENCE') >= 0 || /active in another sequence/i.test(r.reason);
});
const anyMax = rows.some(function (r) {
  return (r.codes || []).indexOf('MAX_ACTIVE_SEQUENCES') >= 0 || /maximum number of active sequences/i.test(r.reason);
});
const orgRow = orgRows.find(function (r) { return r && r.properties && r.properties.scope === 'org'; }) || orgRows[0] || null;
let org = orgRow && orgRow.properties ? orgRow.properties.value : null;
if (typeof org === 'string') {
  try { org = JSON.parse(org); } catch (e) { org = null; }
}
org = org && typeof org === 'object' ? org : {};
const activeLocked = String(org.activeSequence || '').toLowerCase() === 'block';

const notes = [];
if (anyActive) {
  notes.push(activeLocked
    ? 'Admin Settings block prospects who are in another active sequence. Remove them from that sequence first.'
    : "To add them, remove them from the other sequence first, or set 'In another active sequence' to Allow in Settings › Enrollment.");
}
if (anyMax) {
  notes.push('The limit on active sequences per prospect is set in Admin Settings.');
}

const count = rows.length;
let intro = count === 1 ? "This prospect wasn't added to the sequence:" : 'These ' + count + " prospects weren't added to the sequence:";
if (added !== null && added > 0) {
  intro = added + (added === 1 ? ' prospect was added. ' : ' prospects were added. ') + (count === 1 ? "This one wasn't:" : 'These ' + count + " weren't:");
}

return {
  show: count > 0,
  count: count,
  rows: rows.map(function (r, i) { return { id: String(i), name: r.name, reason: r.reason }; }),
  intro: intro,
  note: notes.join(' '),
};

func_Awyqx.functionBody:
// Sequence tab timeline (seqTimelineSection b_qAXC4, live sequence) and the Edit in Builder
// timeline (seqTimelineSection1 b_jMLCS, DRAFT sequence fetch_sequence_json). Same joins for both;
// the edit view also carries each step's edit target (blockId, branch, day, raw step) and per-day
// and per-branch 'Add step here' anchors. Read the edit view at ['edit'].
var LIVE_RAW = ({{ e_6a5519e86454dc4d22e3f4da['data'] }} || {})['res'] || {};
var DRAFT_RAW = ({{ e_6a55dd9de37aa80dd4a95737['data'] }} || {})['res'] || {};

function buildTimeline(seqRaw, editMode) {
  var blocksArr = seqRaw.blocks || [];
  var seqProps = ({{ e_6a4cca1b2dae9d196020c5f9['data'] }} || {}).properties || {};
  var launched = !!seqProps.lastRun || ['Live', 'Paused'].indexOf(seqProps.status) !== -1;
  var stepsContentArr = ({{ e_6adb44c85236864dd8ae251c['data'] }} || {}).steps || [];
  var enrolRows = ({{ e_6adf5394dc07493166cf4b9f['data'] }} || {}).objects || [];
  var abRowsAll = ({{ e_6adf5394dc07493166cf4b9d['data'] }} || {}).objects || [];
  var overviewKpis = (({{ e_6adb44c8925d282255251268['data'] }} || {}).kpis) || {};
  var templatesArr = ({{ e_6ad9fb281a10ec0c912e7759['data'] }} || {}).objects || [];
  var versionsArr = ({{ e_6ad9fb28a965b115459b662c['data'] }} || {}).objects || [];

  var EVENT_LABELS = {
    opened: 'Opened',
    'not-opened': 'Not opened',
    replied: 'Replied',
    'no-reply': 'Not replied',
    sent: 'Sent',
    'not-sent': 'Not sent',
    bounced: 'Bounced',
    linkedin_sent: 'Sent',
    linkedin_not_sent: 'Not sent',
    linkedin_skipped: 'Skipped',
    call_done: 'Done',
    call_not_done: 'Not done',
    call_skipped: 'Skipped',
    task_done: 'Done',
    task_not_done: 'Not done',
    task_skipped: 'Skipped',
    meeting_booked: 'Booked',
    meeting_not_booked: 'Not booked',
    meeting_held: 'Held'
  };

  function dayNum(d) {
    var n = parseInt(d, 10);
    return isNaN(n) ? 1 : n;
  }

  function typeOf(step) {
    return String((step && step.type) || '').toLowerCase();
  }

  // Step number in sequence order, counting branch steps (IF steps, then OTHERWISE steps).
  var stepNumberById = {};
  var stepCounter = 0;
  for (var si = 0; si < blocksArr.length; si++) {
    var sb = blocksArr[si];
    var sLeaves = sb.kind === 'conditional' ? (sb.ifTrue || []).concat(sb.else || []) : [sb];
    for (var sj = 0; sj < sLeaves.length; sj++) {
      stepCounter++;
      stepNumberById[sLeaves[sj].id] = stepCounter;
    }
  }

  function findStepById(id, list) {
    for (var i = 0; i < list.length; i++) {
      var item = list[i];
      if (item.id === id) return item;
      if (item.kind === 'conditional') {
        var found = findStepById(id, item.ifTrue || []) || findStepById(id, item.else || []);
        if (found) return found;
      }
    }
    return null;
  }

  function metricsByStepKey(key) {
    for (var i = 0; i < stepsContentArr.length; i++) {
      if (stepsContentArr[i].stepKey === key) return stepsContentArr[i];
    }
    return null;
  }

  function countsForStep(stepId) {
    var active = 0;
    var paused = 0;
    for (var i = 0; i < enrolRows.length; i++) {
      var p = enrolRows[i].properties || {};
      if (p.currentStep === stepId) {
        if (p.status === 'IN_PROGRESS') active++;
        else if (p.status === 'PAUSED') paused++;
      }
    }
    return { active: active, paused: paused };
  }

  function pct(n, d) {
    return d > 0 ? Math.round((n / d) * 100) : 0;
  }

  function templateById(templateId) {
    if (!templateId) return null;
    for (var i = 0; i < templatesArr.length; i++) {
      if (templatesArr[i].id === templateId) return templatesArr[i].properties || {};
    }
    return null;
  }

  function versionById(versionId) {
    if (!versionId) return null;
    for (var i = 0; i < versionsArr.length; i++) {
      if (versionsArr[i].id === versionId) return versionsArr[i].properties || {};
    }
    return null;
  }

  // Readable template name: its heading + the version the step uses (else the template's current version).
  function templateLabelFor(templateId, versionId) {
    var t = templateById(templateId);
    if (!t || !t.templateHeading) return null;
    var v = versionById(versionId);
    var num = (v && v.version != null) ? v.version : t.currentVersion;
    return t.templateHeading + (num != null && num !== '' ? ' · v' + num : '');
  }

  function templateNameFor(templateId) {
    return templateLabelFor(templateId, null);
  }

  function firstLine(text) {
    var s = String(text || '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|h[1-6])>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>');
    var lines = s.split('\n');
    for (var i = 0; i < lines.length; i++) {
      if (lines[i].trim()) return lines[i].trim();
    }
    return '';
  }

  function hhmm(t) {
    var m = /^(\d{1,2}):(\d{2})/.exec(String(t || ''));
    if (!m) return String(t || '');
    return (m[1].length === 1 ? '0' + m[1] : m[1]) + ':' + m[2];
  }

  // A/B panel trailing-tag state (Board 6), drives the tag colour from custom CSS.
  function abTagState(tag) {
    if (!tag) return '';
    if (tag === 'Leading' || tag === 'Suggested') return 'leading';
    if (tag === 'Winner') return 'winner';
    if (tag === 'Stopped') return 'stopped';
    if (/more to go$/.test(tag)) return 'more-to-go';
    return '';
  }

  var NBSP3 = '   ';

  // A step whose A/B test was stopped keeps its Winner badge even after abTestEnabled turned false.
  function hasWinnerRow(stepId) {
    for (var i = 0; i < abRowsAll.length; i++) {
      var p = abRowsAll[i].properties || {};
      if (p.stepId === stepId && p.status === 'winner') return true;
    }
    return false;
  }

  function abForStep(stepId, winnerHint) {
    var a = null;
    var b = null;
    for (var i = 0; i < abRowsAll.length; i++) {
      var p = abRowsAll[i].properties || {};
      if (p.stepId !== stepId) continue;
      if (p.variantKey === 'A') a = p;
      else if (p.variantKey === 'B') b = p;
    }
    if (!a && !b) return null;

    function rowView(v) {
      if (!v) return null;
      var sent = v.sentCount || 0;
      return {
        label: v.variantKey || '',
        title: 'Template ' + (v.variantKey || ''),
        name: templateLabelFor(v.templateId, v.templateVersionId) || v.templateId || '(template)',
        sent: sent,
        openPct: pct(v.openCount || 0, sent),
        replyPct: pct(v.replyCount || 0, sent),
        status: v.status || 'active',
        tag: '',
        tagState: '',
        line: '',
        statsMd: ''
      };
    }

    var av = rowView(a);
    var bv = rowView(b);
    var winnerKey = (a && a.status === 'winner') ? 'A' : ((b && b.status === 'winner') ? 'B' : (winnerHint || null));
    var badge = 'A/B · Starts at launch';
    var state = 'starts-at-launch';
    var stateText = 'A/B test · Starts at launch';
    var canStop = false;
    var suggested = '';

    if (av && bv) {
      if (winnerKey) {
        badge = 'A/B · Winner ' + winnerKey;
        state = 'winner';
        var wv = winnerKey === 'A' ? av : bv;
        stateText = 'A/B test completed · Winner: Template ' + winnerKey + ' — ' + wv.name;
        if (winnerKey === 'A') {
          av.tag = 'Winner';
          bv.tag = 'Stopped';
        } else {
          bv.tag = 'Winner';
          av.tag = 'Stopped';
        }
      } else {
        // Running test: both variants still active and no winner, so it can be stopped from the card.
        canStop = av.status === 'active' && bv.status === 'active';
        if (launched || av.sent > 0 || bv.sent > 0) {
          if (av.sent < 20 && bv.sent < 20) {
            badge = 'A/B · Collecting data';
            state = 'collecting';
            stateText = 'A/B test · Collecting data — fewer than 20 sends';
          } else {
            badge = 'A/B · Running';
            state = 'running';
            stateText = 'A/B test · Running';
          }
          // Suggested only once both templates have 20+ sends: higher reply %, open % breaks a tie.
          if (av.sent >= 20 && bv.sent >= 20) {
            if (av.replyPct !== bv.replyPct) {
              suggested = av.replyPct > bv.replyPct ? 'A' : 'B';
            } else if (av.openPct !== bv.openPct) {
              suggested = av.openPct > bv.openPct ? 'A' : 'B';
            }
            if (suggested === 'A') av.tag = 'Suggested';
            if (suggested === 'B') bv.tag = 'Suggested';
          }
        }
      }
    }

    function line(v) {
      if (!v) return '';
      return v.label + '  ' + v.name + '    Sent ' + v.sent + '  Open ' + v.openPct + '%  Reply ' + v.replyPct + '%';
    }

    // Numbers only go into the markdown (bold); names render as plain text elsewhere.
    function statsMd(v) {
      if (!v) return '';
      return 'Sent **' + v.sent + '**' + NBSP3 + 'Open **' + v.openPct + '%**' + NBSP3 + 'Reply **' + v.replyPct + '%**';
    }

    if (av) { av.line = line(av); av.statsMd = statsMd(av); av.tagState = abTagState(av.tag); }
    if (bv) { bv.line = line(bv); bv.statsMd = statsMd(bv); bv.tagState = abTagState(bv.tag); }

    return { badge: badge, state: state, stateText: stateText, canStop: canStop, suggested: suggested, rowA: av, rowB: bv };
  }

  function cell(id, label, value, caption) {
    return { id: id, label: label, value: value, caption: caption };
  }

  function enrichStep(step) {
    var type = typeOf(step);
    var icon = 'SvgClipboardCheck';
    var kind = 'task';
    var eyebrowType = 'TASK';
    var iconBg = '#F0EDE8';
    var iconFg = '#525252';

    if (type === 'email') {
      var isAuto = String(step.activityType || '').toLowerCase() === 'automated';
      icon = 'Mail01';
      kind = 'email';
      iconBg = '#E6F0FB';
      iconFg = '#2F6DB5';
      eyebrowType = isAuto ? 'AUTO EMAIL' : 'MANUAL EMAIL';
    } else if (type === 'linkedin') {
      icon = 'Linkedin';
      kind = 'linkedin';
      iconBg = '#ECEBFB';
      iconFg = '#4B47B0';
      eyebrowType = 'LINKEDIN · CONNECT';
    } else if (type === 'call') {
      icon = 'SvgPhone01';
      kind = 'call';
      iconBg = '#EAF3DB';
      iconFg = '#3B6D11';
      eyebrowType = 'CALL';
    } else if (type === 'meeting') {
      icon = 'Calendar';
      eyebrowType = 'MEETING';
    }

    var stepNumber = stepNumberById[step.id] || null;
    var contentMatch = metricsByStepKey(step.id);
    var counts = countsForStep(step.id);
    // Discrete metric cells (label / value / caption), type-specific. A value the analytics
    // source does not expose stays '—' rather than an invented number.
    var metrics = [];
    var liveStatus = '';

    if (launched) {
      var sent = contentMatch ? (contentMatch.sentOrCreated || 0) : 0;
      var donePctNum = contentMatch && contentMatch.donePct != null ? contentMatch.donePct : null;
      var donePct = donePctNum != null ? donePctNum + '%' : '—';
      var openPct = contentMatch && contentMatch.openPct != null ? contentMatch.openPct + '%' : '—';
      var replyPct = contentMatch && contentMatch.replyPct != null ? contentMatch.replyPct + '%' : '—';
      var connectPct = contentMatch && contentMatch.connectPct != null ? contentMatch.connectPct + '%' : '—';
      var meetings = contentMatch ? (contentMatch.meetings || 0) : 0;
      var doneCount = donePctNum != null ? Math.round((donePctNum * sent) / 100) : null;

      if (type === 'email') {
        metrics = [
          cell('sent', 'Sent', String(sent), 'prospects'),
          cell('delivered', 'Delivered', donePct, '—'),
          cell('opened', 'Opened', openPct, '—'),
          cell('replied', 'Replied', replyPct, '—'),
          cell('bounced', 'Bounced', '—', '—')
        ];
      } else if (type === 'linkedin') {
        metrics = [
          cell('completed', 'Completed', donePct, doneCount != null ? doneCount + ' of ' + sent : '—'),
          cell('skipped', 'Skipped', '—', 'manual'),
          cell('overdue', 'Overdue', '—', 'due before today')
        ];
      } else if (type === 'call') {
        metrics = [
          cell('calls', 'Calls', String(sent), 'logged'),
          cell('connected', 'Connected', connectPct, '—'),
          cell('meetings', 'Meetings', String(meetings), 'booked')
        ];
      } else {
        metrics = [
          cell('completed', 'Completed', doneCount != null ? String(doneCount) : '—', 'of ' + sent),
          cell('skipped', 'Skipped', '—', 'manual'),
          cell('overdue', 'Overdue', '—', 'due before today')
        ];
      }

      liveStatus = type === 'linkedin'
        ? counts.active + ' active · ' + counts.paused + ' paused'
        : counts.active + ' active on step';
    }

    var previewLabel = 'Instruction';
    if (type === 'email') previewLabel = 'Subject';
    else if (type === 'linkedin') previewLabel = 'Note';
    else if (type === 'call') previewLabel = 'Script';

    var tmpl = templateById(step.templateId);
    var ver = versionById(step.templateVersionId);
    var emailCfg = step.emailConfig || {};
    var previewValue = '';
    if (type === 'email') {
      previewValue = emailCfg.subjectOverride || (ver && ver.subject) || (tmpl && tmpl.subject) || emailCfg.subject || step.description || '';
    } else if (type === 'linkedin') {
      previewValue = firstLine((step.linkedInConfig || {}).draftMessage) || firstLine(ver && ver.body) || step.description || '';
    } else if (type === 'call') {
      previewValue = firstLine((step.callConfig || {}).callScript) || (tmpl && tmpl.templateHeading) || step.description || '';
    } else {
      previewValue = step.description || firstLine((step.genericConfig || {}).instructions) || '';
    }
    previewValue = String(previewValue || '').trim();

    var templateLabel = type === 'email' ? templateLabelFor(step.templateId, step.templateVersionId) : null;
    // No thread setting is stored on a step: a subject that starts with "Re:" reads as a reply, any other as a new thread.
    var threadLabel = type === 'email' ? (/^\s*re:/i.test(previewValue) ? 'Reply' : 'New thread') : null;

    var abDone = step.abResult && String(step.abResult.status || '').toLowerCase() === 'completed';
    var abWinnerHint = abDone ? String(step.abResult.winnerVariantKey || '').toUpperCase() : '';
    var ab = (type === 'email' && (step.abTestEnabled || abDone || hasWinnerRow(step.id)))
      ? abForStep(step.id, abWinnerHint === 'A' || abWinnerHint === 'B' ? abWinnerHint : null)
      : null;

    return {
      id: step.id,
      day: dayNum(step.day),
      stepNumber: stepNumber,
      time: hhmm(step.time),
      title: step.title || '',
      eyebrow: 'STEP ' + (stepNumber || '') + ' · ' + eyebrowType,
      kind: kind,
      icon: icon,
      iconBg: iconBg,
      iconFg: iconFg,
      previewLabel: previewLabel,
      previewValue: previewValue || '—',
      previewLine: previewLabel + '   ' + (previewValue || '—'),
      threadLabel: threadLabel,
      templateLabel: templateLabel,
      metrics: metrics,
      liveStatus: liveStatus,
      notSentYet: !launched,
      ab: ab
    };
  }

  var days = {};
  var order = [];
  var lastBlockIdByDay = {};

  // Edit in Builder: what the canvas used to send for a step (updateValues + selectedStep).
  function withEdit(view, raw, blockId, branch, day) {
    view.edit = { stepId: raw.id, blockId: blockId, branch: branch, day: day, raw: raw };
    return view;
  }

  for (var i = 0; i < blocksArr.length; i++) {
    var b = blocksArr[i];
    var d = dayNum(b.day);
    if (!days[d]) {
      days[d] = [];
      order.push(d);
    }
    if (b.kind === 'conditional') {
      var cond = (b.conditions && b.conditions[0]) || {};
      var refStep = findStepById(cond.stepRef, blocksArr);
      var refN = refStep ? stepNumberById[refStep.id] : null;
      var refLabel = 'Step' + (refN ? ' ' + refN : '') + (refStep ? ' ' + typeOf(refStep) : '');
      var eventLabel = EVENT_LABELS[cond.event] || cond.event || '';
      var ifSteps = b.ifTrue || [];
      var elseSteps = b.else || [];
      days[d].push({
        id: 'cond_' + b.id,
        blockId: b.id,
        kind: 'condition',
        conditionText: refLabel + ' · ' + eventLabel,
        ifItems: ifSteps.map(function (s) { return withEdit(enrichStep(s), s, b.id, 'ifTrue', d); }),
        elseItems: elseSteps.map(function (s) { return withEdit(enrichStep(s), s, b.id, 'else', d); }),
        ifAdd: { day: d, blockId: b.id, branch: 'ifTrue', stepId: ifSteps.length ? ifSteps[ifSteps.length - 1].id : '' },
        elseAdd: { day: d, blockId: b.id, branch: 'else', stepId: elseSteps.length ? elseSteps[elseSteps.length - 1].id : '' }
      });
      lastBlockIdByDay[d] = b.id;
    } else {
      var enriched = withEdit(enrichStep(b), b, b.id, '', d);
      days[d].push({ id: enriched.id, kind: 'step', step: enriched });
      lastBlockIdByDay[d] = b.id;
    }
  }

  order.sort(function (x, y) { return x - y; });

  var dayGroups = [];
  for (var j = 0; j < order.length; j++) {
    var dd = order[j];
    dayGroups.push({
      day: dd,
      waitLabel: j === 0 ? '' : ('+' + (dd - order[j - 1]) + 'd wait'),
      items: days[dd],
      addAnchor: { day: dd, blockId: lastBlockIdByDay[dd] || '', branch: '', stepId: '' }
    });
  }

  var flatCount = 0;
  var autoCount = 0;
  for (var k = 0; k < blocksArr.length; k++) {
    var bb = blocksArr[k];
    var leaves = bb.kind === 'conditional' ? (bb.ifTrue || []).concat(bb.else || []) : [bb];
    for (var m = 0; m < leaves.length; m++) {
      flatCount++;
      if (typeOf(leaves[m]) === 'email' && String(leaves[m].activityType || '').toLowerCase() === 'automated') {
        autoCount++;
      }
    }
  }
  var automatedPct = flatCount > 0 ? Math.round((autoCount / flatCount) * 100) : 0;

  var enrolledCount = overviewKpis.enrolled != null ? overviewKpis.enrolled : enrolRows.length;
  var replyPctOverall = overviewKpis.replyRatePct;
  // The edit view counts the draft it shows; the live view keeps the published counts.
  var stepCount = editMode ? flatCount : Number(seqProps.noOfSteps || 0);
  var dayCount = editMode ? order.length : Number(seqProps.noOfDays || 0);

  var restLeft = ' · ' + dayCount + (dayCount === 1 ? ' day' : ' days') + ' · ' + automatedPct + '% automated' + (launched && replyPctOverall != null ? ' · ' + replyPctOverall + '% reply' : '');
  var summaryLeft = stepCount + ' steps' + restLeft;
  var summaryLeftMd = '**' + stepCount + (stepCount === 1 ? ' step' : ' steps') + '**' + restLeft;

  function shortDate(value) {
    var ms = Number(value);
    if (!ms) return '';
    if (ms < 100000000000) ms = ms * 1000;
    var dt = new Date(ms);
    if (isNaN(dt.getTime())) return '';
    return dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  }
  var launchDate = shortDate(seqProps.lastPublishedAt || seqProps.lastRun);

  var summaryRight = launched
    ? ('Since V' + (seqProps.currentVersion || 1) + ' launch' + (launchDate ? ' · ' + launchDate : '') + ' · ' + enrolledCount + ' enrolled')
    : ('Not launched · ' + enrolledCount + ' prospects linked');

  return {
    days: dayGroups,
    summaryLeft: summaryLeft,
    summaryLeftMd: summaryLeftMd,
    summaryRight: summaryRight,
    launched: launched,
    isEmpty: blocksArr.length === 0
  };
}

var viewModel = buildTimeline(LIVE_RAW, false);
viewModel.edit = buildTimeline(DRAFT_RAW, true);
return viewModel;

