// Link Prospects > AI Rule > Review matches: the 'Select all' checkbox above the match list.
// Selectable = the matches the list shows now (search applied) that are not conflicted.
// Conflicted matches (defaultSelected === false) stay with the 'Include conflicted' checkbox.
const visible = {{ func_1nEQq['value'] }} || [];
const selected = {{ var_65xH6['value'] }} || [];
const selectedSet = {};
selected.forEach(function (id) {
  selectedSet[id] = true;
});
const ids = visible
  .filter(function (p) {
    return !!p && !!p['id'] && p['defaultSelected'] !== false;
  })
  .map(function (p) {
    return p['id'];
  });
const selectedCount = ids.filter(function (id) {
  return selectedSet[id];
}).length;
return {
  ids: ids,
  count: ids.length,
