};

func_aGopS.functionBody:
// Prospects tab rows (fetchSequenceEnrolments) -> Last step and Last contacted, keyed by enrolment row id.
// Same mapping as Account Overview func_Xqy2k and Prospect Detail func_IEWAu.
const enrolments = ({{ e_6adb9bee0881d2257aa26ec0['data'] }} || {})['objects'] || [];
const tasksData = {{ e_6adca2bd925d282255f2ced4['data'] }};
const stepsData = {{ e_6adca2bd925d282255f2ced6['data'] }};
const tasksLoading = {{ e_6adca2bd925d282255f2ced4['isLoading'] }} === true;
const stepsLoading = {{ e_6adca2bd925d282255f2ced6['isLoading'] }} === true;
const failed = !!({{ e_6adca2bd925d282255f2ced4['error'] }} || {{ e_6adca2bd925d282255f2ced6['error'] }});
const now = Date.now();

function relAgo(ms) {
  const minutes = Math.floor(Math.max(0, now - ms) / 60000);
  if (minutes < 1) {
    return 'just now';
  }
  if (minutes < 60) {
    return minutes + 'm ago';
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return hours + 'h ago';
  }
  const days = Math.floor(hours / 24);
  if (days < 30) {
    return days + 'd ago';
  }
  if (days < 365) {
    return Math.floor(days / 30) + 'mo ago';
  }
  return Math.floor(days / 365) + 'y ago';
}

function channelOf(raw) {
  const v = String(raw || '').trim();
  const k = v.toLowerCase();
  if (k === 'email') return 'Email';
  if (k === 'linkedin') return 'LinkedIn';
  if (k === 'call') return 'Call';
  if (k === 'meeting') return 'Meeting';
  if (k === 'task' || k === 'generic') return 'Task';
  if (!v) return '';
  return v.charAt(0).toUpperCase() + v.slice(1);
}

const lastContacted = {};
enrolments.forEach(function (r) {
  const p = r.properties || {};
  const touched = Number(p.lastTouchedAt || 0);
  lastContacted[r.id] = touched > 0 ? relAgo(touched) : '—';
});

const lastStep = {};
let lastStepReady = false;
if (failed || enrolments.length === 0) {
  lastStepReady = true;
} else if (tasksData && stepsData && !tasksLoading && !stepsLoading) {
  const tasks = tasksData.objects || [];
  const steps = stepsData.objects || [];

  function better(a, b) {
    return !b || Number(a.versionNumber || 0) > Number(b.versionNumber || 0);
  }

  const byVersionKey = {};
  const bySeqKey = {};
  const byVersionNum = {};
  const bySeqNum = {};
  const latestVersionOfSeq = {};
  steps.forEach(function (s) {
    const p = s.properties || {};
    if (p.versionId && p.stepKey) {
      byVersionKey[p.versionId + '|' + p.stepKey] = p;
    }
    if (p.seqId && p.stepKey && better(p, bySeqKey[p.seqId + '|' + p.stepKey])) {
      bySeqKey[p.seqId + '|' + p.stepKey] = p;
    }
    if (p.versionId && p.stepNumber != null) {
      byVersionNum[p.versionId + '|' + p.stepNumber] = p;
    }
    if (p.seqId && p.stepNumber != null && better(p, bySeqNum[p.seqId + '|' + p.stepNumber])) {
      bySeqNum[p.seqId + '|' + p.stepNumber] = p;
    }
    if (p.seqId && better(p, latestVersionOfSeq[p.seqId])) {
      latestVersionOfSeq[p.seqId] = p;
    }
  });

  function timeOf(t) {
    const p = t.properties || {};
    return Number(p.completedAt || p.markedSentAt || t.modifiedTime || t.mTm || t.createdTime || t.cTm || 0);
  }

  const latestByEnrolment = {};
  const latestByProspectSeq = {};
  tasks.forEach(function (t) {
    const p = t.properties || {};
    if (p.enrollmentId) {
      const cur = latestByEnrolment[p.enrollmentId];
      if (!cur || timeOf(t) > timeOf(cur)) {
        latestByEnrolment[p.enrollmentId] = t;
      }
    }
    if (p.prospectId && p.sequenceId) {
      const key = p.prospectId + '|' + p.sequenceId;
      const cur = latestByProspectSeq[key];
      if (!cur || timeOf(t) > timeOf(cur)) {
        latestByProspectSeq[key] = t;
      }
    }
  });

  enrolments.forEach(function (r) {
    const e = r.properties || {};
    const seqId = e.sequenceId;
    const task = latestByEnrolment[r.id] || latestByProspectSeq[e.prospectId + '|' + seqId] || null;
    let label = '—';
    if (task) {
      const tp = task.properties || {};
      const runVersion = e.sequenceVersionId || (latestVersionOfSeq[seqId] || {}).versionId;
      let step = null;
      if (tp.blockId) {
        step = (runVersion && byVersionKey[runVersion + '|' + tp.blockId])
          || (tp.sequenceVersionId && byVersionKey[tp.sequenceVersionId + '|' + tp.blockId])
          || bySeqKey[seqId + '|' + tp.blockId]
          || null;
      }
      if (step && step.stepNumber != null) {
        const ch = channelOf(step.taskType) || channelOf(tp.taskType);
        label = 'Step ' + step.stepNumber + (ch ? ' · ' + ch : '');
      } else {
        const n = Number(e.cur_step || 0) - 1;
        if (n > 0) {
          const fs = (runVersion && byVersionNum[runVersion + '|' + n]) || bySeqNum[seqId + '|' + n] || null;
          const ch = channelOf(fs ? fs.taskType : tp.taskType);
          label = 'Step ' + n + (ch ? ' · ' + ch : '');
        }
      }
    }
    lastStep[r.id] = label;
  });
  lastStepReady = true;
}

return {
  lastStepReady: lastStepReady,
  lastStep: lastStep,
  lastContacted: lastContacted,
};

func_1UWR1.functionBody:
// Prospects tab bulk bar: the ticked enrolments on screen now, how many each bulk action can apply to,
// and the confirm text for the action in var bulkAction.
const rows = ({{ e_6adb9bee0881d2257aa26ec0['data'] }} || {})['objects'] || [];
const keys = {{ b_4eWPg['selectedRowKeys'] }} || [];
const action = {{ var_mm7em['value'] }} || '';

const ACTIONS = {
  launch: {
    verb: 'Launch',
    past: 'launched',
    statuses: ['PENDING'],
    note: 'They will start receiving steps from this sequence.',
  },
  pause: {
    verb: 'Pause',
    past: 'paused',
    statuses: ['PENDING', 'IN_PROGRESS'],
    note: 'Their upcoming steps will wait until you resume them.',
  },
  resume: {
    verb: 'Resume',
    past: 'resumed',
    statuses: ['PAUSED'],
    note: 'They will continue from the step they paused on.',
  },
  exit: {
    verb: 'Exit',
    past: 'exited',
    statuses: ['PENDING', 'IN_PROGRESS', 'PAUSED'],
    note: 'They will stop receiving steps from this sequence.',
  },
};

const picked = {};
keys.forEach(function (key) {
  picked[String(key)] = true;
});
const selected = rows.filter(function (row) {
  return row && picked[String(row['id'])];
});
const countWhere = function (statuses) {
  return selected.filter(function (row) {
    return statuses.indexOf((row['properties'] || {})['status']) !== -1;
  }).length;
};

const count = selected.length;
const noun = count === 1 ? 'prospect' : 'prospects';
const cfg = ACTIONS[action] || null;
const applicable = cfg ? countWhere(cfg.statuses) : 0;
const skipped = count - applicable;
const launchable = countWhere(ACTIONS.launch.statuses);
const pausable = countWhere(ACTIONS.pause.statuses);
const resumable = countWhere(ACTIONS.resume.statuses);
const exitable = countWhere(ACTIONS.exit.statuses);
const nothingApplies = count > 0 && launchable + pausable + resumable + exitable === 0;

return {
