const byId = {};
const lastSeven = function (list, key) {
  const counts = (Array.isArray(list) ? list : []).slice(-7).map(function (day) {
    return Number(day && day[key]) || 0;
  });
  while (counts.length < 7) {
    counts.unshift(0);
  }
  return counts;
};
prospects.forEach(function (prospect) {
