func_rhQiE.functionBody:
// Per-sequence enrolment counts for the Sequences table (b_oBLE6).
// Reads the two page sources that fetch only the table's visible sequence ids.
// Returns { ready, bySeq: { <sequenceId>: { prospects, contacted, ... } } }.
const enrolData = {{ e_6adc9aaa925d282255f1adf0['data'] }};
const enrolLoading = {{ e_6adc9aaa925d282255f1adf0['isLoading'] }};
const taskData = {{ e_6adc9aaa0881d2257a2923d7['data'] }};
const taskLoading = {{ e_6adc9aaa0881d2257a2923d7['isLoading'] }};

const ready = !!enrolData && !!taskData && enrolLoading !== true && taskLoading !== true;
const enrolments = (enrolData && enrolData.objects) || [];
const tasks = (taskData && taskData.objects) || [];

const bySeq = {};
const enrolmentSeq = {};
const enrolmentByProspect = {};

enrolments.forEach(function (row) {
  const props = (row && row.properties) || {};
  const seqId = props.sequenceId;
  if (!seqId) {
    return;
  }
  if (!bySeq[seqId]) {
    bySeq[seqId] = { enrolled: 0, active: 0, paused: 0, bounced: 0, touched: {} };
  }
  const entry = bySeq[seqId];
  entry.enrolled += 1;
  if (props.status === 'IN_PROGRESS') {
    entry.active += 1;
  }
  if (props.status === 'PAUSED') {
    entry.paused += 1;
  }
  if (props.exitReason === 'hard_bounce' || props.status === 'BOUNCED') {
    entry.bounced += 1;
  }
  enrolmentSeq[row.id] = seqId;
  if (props.prospectId) {
    enrolmentByProspect[seqId + '|' + props.prospectId] = row.id;
  }
});

tasks.forEach(function (row) {
  const props = (row && row.properties) || {};
  let enrolmentId = props.enrollmentId;
  if (!enrolmentId || !enrolmentSeq[enrolmentId]) {
    enrolmentId = enrolmentByProspect[props.sequenceId + '|' + props.prospectId];
  }
  const seqId = enrolmentId ? enrolmentSeq[enrolmentId] : null;
  if (seqId && bySeq[seqId]) {
    bySeq[seqId].touched[enrolmentId] = true;
  }
});

const result = {};
Object.keys(bySeq).forEach(function (seqId) {
  const entry = bySeq[seqId];
  const contactedCount = Object.keys(entry.touched).length;
  const parts = [];
  if (entry.active > 0) {
    parts.push(entry.active + ' active');
  }
  if (entry.paused > 0) {
    parts.push(entry.paused + ' paused');
  }
  if (entry.bounced > 0) {
    parts.push(entry.bounced + ' bounced');
  }
  result[seqId] = {
    enrolled: entry.enrolled,
    active: entry.active,
    paused: entry.paused,
    bounced: entry.bounced,
    contactedCount: contactedCount,
    prospects: parts.length ? parts.join(' · ') : '—',
    contacted: entry.enrolled > 0 ? Math.round((contactedCount / entry.enrolled) * 100) + '%' : '—'
  };
});

return {
  ready: ready,
  enrolmentRows: enrolments.length,
  enrolmentTotal: (enrolData && enrolData.total) || 0,
  taskRows: tasks.length,
  taskTotal: (taskData && taskData.total) || 0,
  bySeq: result
};

