func_18zn5.functionBody:
const rows = {{ e_6a56294e6454dc4d22e864b5['data'] }}?.objects || [];
const defs = {{ e_6acdf24970b66f5702ed4133['data'] }}?.objects || [];
const prospect = {{ e_6a4e49aaf0fc262d964315e9['data'] }}?.properties || {};
const STATES = { PENDING: 'Pending', PAUSED: 'Paused', IN_PROGRESS: 'In progress', COMPLETED: 'Completed', CANCELLED: 'Cancelled', MATCHED_EXIT_CONDITION: 'Exited' };
const lastContactedFallback = prospect.lastContactedAt
  ? Math.max(0, Math.floor((Date.now() - prospect.lastContactedAt) / 86400000)) + 'd ago'
  : (prospect.lastContacted || '-');
const byId = {};
const byTitle = {};
defs.forEach(d => { const p = d.properties || {}; byId[d.id] = p; if (p.title) { byTitle[p.title] = p; } });

function relTime(ms) {
  if (!ms) return null;
  const diff = Date.now() - ms;
  const abs = Math.abs(diff);
  const minute = 60000, hour = 3600000, day = 86400000, week = day * 7, month = day * 30;
  let out;
  if (abs < hour) {
    const m = Math.max(1, Math.round(abs / minute));
    out = m + 'm';
  } else if (abs < day) {
    const h = Math.floor(abs / hour);
    const m = Math.round((abs % hour) / minute);
    out = h + 'h ' + m + 'm';
  } else if (abs < month) {
    const d = Math.floor(abs / day);
    const h = Math.round((abs % day) / hour);
    out = d + 'd ' + h + 'h';
  } else {
    const mo = Math.floor(abs / month);
    const w = Math.round((abs % month) / week);
    out = mo + 'mo' + (w ? ' ' + w + 'w' : '');
  }
  return out;
}

const replyExitReasons = { reply: 1, meeting_booked: 1, call_meeting_set: 1, referral: 1, opportunity_created: 1 };
const finishedStatuses = { COMPLETED: 1, CANCELLED: 1, MATCHED_EXIT_CONDITION: 1, FAILED: 1 };

const out = {};
rows.forEach(r => {
  const p = r.properties || {};
  const def = byId[p.sequenceId] || byTitle[p.sequenceName] || {};
  const steps = def.noOfSteps;
  const cur = p.cur_step == null ? 0 : p.cur_step;
  const stepFull = p.currentStep ? p.currentStep : (steps ? ('Step ' + cur + ' of ' + steps) : '-');

  let statePill, stateCategory;
  if (finishedStatuses[p.status]) {
    if (replyExitReasons[p.exitReason]) {
      statePill = 'Finished (replied)';
      stateCategory = 'finished_replied';
    } else {
      statePill = 'Finished (no reply)';
      stateCategory = 'finished_no_reply';
    }
  } else if (p.status === 'PAUSED') {
    statePill = 'Disabled';
    stateCategory = 'disabled';
  } else if (p.nextTouchAt && p.nextTouchAt < Date.now()) {
    statePill = 'Email due ' + (relTime(p.nextTouchAt) || '-') + ' ago';
    stateCategory = 'due';
  } else {
    statePill = 'Active';
    stateCategory = 'active';
  }

  const lastContactedRel = p.lastTouchedAt ? (relTime(p.lastTouchedAt) || '-') : lastContactedFallback;

  out[r.id] = {
    title: def.title || p.sequenceName || 'Untitled sequence',
    step: steps ? cur + ' out of ' + steps : (p.currentStep || '-'),
    stepLabel: stepFull,
    state: STATES[p.status] || p.status || '-',
    statePill: statePill,
    stateCategory: stateCategory,
    lastContacted: lastContactedFallback,
    lastContactedRel: lastContactedRel,
    isLive: p.status !== 'PAUSED'
  };
});
return out;

