func_IEWAu.functionBody:
const enrolments = {{ e_6a56294e6454dc4d22e864b5['data'] }}?.objects || [];
const tasksData = {{ e_6adc81d05236864dd8130aa4['data'] }};
const stepsData = {{ e_6adc81d05236864dd8130aa3['data'] }};
const tasksLoading = {{ e_6adc81d05236864dd8130aa4['isLoading'] }} === true;
const stepsLoading = {{ e_6adc81d05236864dd8130aa3['isLoading'] }} === true;
const failed = !!({{ e_6adc81d05236864dd8130aa4['error'] }} || {{ e_6adc81d05236864dd8130aa3['error'] }});

if (failed) {
  return { ready: true, failed: true, byEnrolment: {}, bySequence: {}, details: {} };
}
if (!tasksData || !stepsData || tasksLoading || stepsLoading) {
  return { ready: false, byEnrolment: {}, bySequence: {}, details: {} };
}

const tasks = tasksData.objects || [];
const steps = stepsData.objects || [];

function channelOf(raw) {
  const v = String(raw || '').trim();
  const k = v.toLowerCase();
  if (k === 'email') return 'Email';
  if (k === 'linkedin') return 'LinkedIn';
  if (k === 'call') return 'Call';
  if (k === 'meeting') return 'Meeting';
  if (k === 'task' || k === 'generic') return 'Task';
  if (!v) return '';
  return v.charAt(0).toUpperCase() + v.slice(1);
}

function better(a, b) {
  return !b || Number(a.versionNumber || 0) > Number(b.versionNumber || 0);
}

const byVersionKey = {};
const bySeqKey = {};
const byVersionNum = {};
const bySeqNum = {};
const latestVersionOfSeq = {};
steps.forEach(function (s) {
  const p = s.properties || {};
  if (p.versionId && p.stepKey) {
    byVersionKey[p.versionId + '|' + p.stepKey] = p;
  }
  if (p.seqId && p.stepKey && better(p, bySeqKey[p.seqId + '|' + p.stepKey])) {
    bySeqKey[p.seqId + '|' + p.stepKey] = p;
  }
  if (p.versionId && p.stepNumber != null) {
    byVersionNum[p.versionId + '|' + p.stepNumber] = p;
  }
  if (p.seqId && p.stepNumber != null && better(p, bySeqNum[p.seqId + '|' + p.stepNumber])) {
    bySeqNum[p.seqId + '|' + p.stepNumber] = p;
  }
  if (p.seqId && better(p, latestVersionOfSeq[p.seqId])) {
    latestVersionOfSeq[p.seqId] = p;
  }
});

function timeOf(t) {
  const p = t.properties || {};
  return Number(p.completedAt || p.markedSentAt || t.modifiedTime || t.createdTime || 0);
}

const latestBySeq = {};
tasks.forEach(function (t) {
  const p = t.properties || {};
  if (!p.sequenceId) return;
  const cur = latestBySeq[p.sequenceId];
  if (!cur || timeOf(t) > timeOf(cur)) {
    latestBySeq[p.sequenceId] = t;
  }
});

const byEnrolment = {};
const bySequence = {};
const details = {};
enrolments.forEach(function (r) {
  const e = r.properties || {};
  const seqId = e.sequenceId;
  const task = seqId ? latestBySeq[seqId] : null;
  let label = '—';
  let via = 'none';
  let step = null;
  if (task) {
    const tp = task.properties || {};
    const runVersion = e.sequenceVersionId || (latestVersionOfSeq[seqId] || {}).versionId;
    if (tp.blockId) {
      step = (runVersion && byVersionKey[runVersion + '|' + tp.blockId])
        || (tp.sequenceVersionId && byVersionKey[tp.sequenceVersionId + '|' + tp.blockId])
        || bySeqKey[seqId + '|' + tp.blockId]
        || null;
    }
    if (step && step.stepNumber != null) {
      label = 'Step ' + step.stepNumber + ' · ' + (channelOf(step.taskType) || channelOf(tp.taskType));
      via = 'step';
    } else {
      const n = Number(e.cur_step || 0) - 1;
      if (n > 0) {
        const fs = (runVersion && byVersionNum[runVersion + '|' + n]) || bySeqNum[seqId + '|' + n] || null;
        const ch = channelOf(fs ? fs.taskType : tp.taskType);
        label = 'Step ' + n + (ch ? ' · ' + ch : '');
        via = 'cur_step';
      }
    }
  }
  byEnrolment[r.id] = label;
  if (seqId && (!bySequence[seqId] || via !== 'none')) {
    bySequence[seqId] = label;
  }
  details[r.id] = {
    label: label,
    via: via,
    taskId: task ? task.id : null,
    blockId: task ? (task.properties || {}).blockId : null,
    at: task ? timeOf(task) : null
  };
});

return {
  ready: true,
  byEnrolment: byEnrolment,
  bySequence: bySequence,
  details: details
};

