    values: [
      { field: 'properties_source', op: 'EQUAL', values: ['Manual'] },
      { field: 'properties_source', op: 'EQUAL', values: ['manual'] }
    ]
  };
}
var priorityCond = (priorityVal && priorityVal !== 'All') ? { field: 'properties_priority', op: 'EQUAL', values: [priorityVal] } : null;
var clauses = [];
if (typeCond) {
  clauses.push(typeCond);
}
if (statusCond) {
  clauses.push(statusCond);
}
if (sourceCond) {
  clauses.push(sourceCond);
}
if (priorityCond) {
  clauses.push(priorityCond);
}
