func_xvBhH.functionBody:
// The "Skipped (n)" tab count: this prospect's skipped tasks that pass every
// other filter (due range, source, search, priority, status), so it equals
// what the list shows when the Skipped tab is chosen. Same rules and helpers
// as func_HbS8B; keep the two bodies in step.
var rows = {{ func_Z23Vx['value'] }} || [];
var typeFilter = String({{ var_ofdL0['value'] }} || 'All');
var sourceFilter = String({{ var_zuiQL['value'] }} || 'All');
var dueRange = String({{ var_WRrMP['value'] }} || '');
var dueStartRaw = String({{ var_idRiB['value'] }} || '');
var dueEndRaw = String({{ var_SO7Ni['value'] }} || '');
var searchFilter = String({{ var_ue1n8['value'] }} || '').trim().toLowerCase();
var priorityFilter = String({{ var_YRQJV['value'] }} || 'All');
var statusFilter = String({{ var_fCQCG['value'] }} || 'All');
var nowMs = Date.now();

function fieldsOf(row) {
  return (row && row.properties) || row || {};
}
function rawStatusOf(row) {
  var s = fieldsOf(row).taskStatus;
  return String(s == null ? '' : s).trim();
}
// Epoch ms from a number, a numeric string (seconds or ms) or an ISO string.
function toMs(raw) {
  if (raw === undefined || raw === null || raw === '') {
    return null;
  }
  if (typeof raw === 'number') {
    return isNaN(raw) ? null : (Math.abs(raw) < 100000000000 ? raw * 1000 : raw);
  }
  var s = String(raw).trim();
  if (/^-?\d+(\.\d+)?$/.test(s)) {
    var n = parseFloat(s);
    return Math.abs(n) < 100000000000 ? n * 1000 : n;
  }
  var parsed = Date.parse(s);
  return isNaN(parsed) ? null : parsed;
}
// The task's real due instant: utcTimeEpoch, else dueTime. Never day/month/year
// (those are stored in the prospect's zone, not the viewer's).
function epochOf(row) {
  var f = fieldsOf(row);
  var ms = toMs(f.utcTimeEpoch);
  return ms === null ? toMs(f.dueTime) : ms;
}
function mappedStatusOf(row) {
  var raw = rawStatusOf(row);
  var low = raw.toLowerCase();
  var fixed = {
    completed: 'completed',
    skipped: 'skipped',
    paused: 'paused',
    in_progress: 'in progress',
    'in progress': 'in progress',
    cancelled: 'cancelled',
    canceled: 'cancelled',
    failed: 'failed'
  };
  if (fixed[low]) {
    return fixed[low];
  }
  if (raw === '' || ['pending', 'due', 'upcoming', 'not started', 'not_started', 'open'].indexOf(low) !== -1) {
    var ms = epochOf(row);
    if (ms === null) {
      return low === 'upcoming' ? 'upcoming' : 'due';
    }
    return ms > nowMs ? 'upcoming' : 'due';
  }
  return low;
}
function isSkipped(row) {
  var v = fieldsOf(row).skipped;
  return v === 1 || v === '1' || v === true || rawStatusOf(row).toLowerCase() === 'skipped';
}
function isCompleted(row) {
  return mappedStatusOf(row) === 'completed';
}
function isCancelled(row) {
  return mappedStatusOf(row) === 'cancelled';
}
