    return { label: 'Paused', tone: 'warning' };
  }
  if (ms !== Number.MAX_SAFE_INTEGER && ms < now) {
    return { label: 'Overdue', tone: 'error' };
  }
  return { label: 'Due', tone: 'blue' };
}

function sourceLabel(row) {
  var f = fieldsOf(row);
  var s = String(f.source || '').trim().toLowerCase();
  return s === 'manual' ? 'Manual' : 'Automated';
}

var enriched = rows.map(function (row) {
  var ms = dueMs(row);
  var st = statusInfo(row, ms);
  return {
    id: row.id,
    properties: fieldsOf(row),
    __dueMs: ms,
    __dueDisplay: fmtDue(ms),
    __statusLabel: st.label,
    __statusTone: st.tone,
    __sourceLabel: sourceLabel(row),
    __isCompleted: isCompletedRow(row)
  };
});

var sorted = enriched.slice().sort(function (a, b) {
  if (statusFilter === 'All') {
    var ac = a.__isCompleted ? 1 : 0;
    var bc = b.__isCompleted ? 1 : 0;
    if (ac !== bc) {
      return ac - bc;
    }
  }
  return a.__dueMs - b.__dueMs;
});

return sorted;

func_NfHtS.functionBody:
// Prospect Detail > Tasks: what the empty table says when the filter bar
// leaves no rows (func_HbS8B is empty). One empty view reads this.
// Same copy logic as Account Overview's taskEmptyStateCopy (func_Ve10t),
// for this page's variables. Precedence: search -> status -> priority ->
// type tab -> due range -> source.
// Priority and status start as '' here, which means All. A due range of ''
// means no date filter, the same as All time.
// showAll is false only when nothing narrows the list (All type, All time,
// All source, no search, All priority, All status): then the prospect truly
// has no tasks and "Show all tasks" would do nothing.
var search = String({{ var_ue1n8['value'] }} || '').trim();
var status = String({{ var_fCQCG['value'] }} || 'All');
var priority = String({{ var_YRQJV['value'] }} || 'All');
var typeTab = String({{ var_ofdL0['value'] }} || 'All');
var range = String({{ var_WRrMP['value'] }} || '');
var source = String({{ var_zuiQL['value'] }} || 'All');

var isAllTime = range === '' || range === 'All time';
var overdue = range === 'Overdue';

// " today", " this week", " this month", " in this date range", or "".
var when = '';
if (range === 'Today') {
  when = ' today';
} else if (range === 'This week') {
  when = ' this week';
} else if (range === 'This month') {
  when = ' this month';
} else if (range === 'Custom') {
  when = ' in this date range';
}

// The same range after a noun: " due today", " in this date range", or "".
var due = '';
if (range === 'Custom') {
  due = when;
} else if (when) {
  due = ' due' + when;
}

var showAll = !(
  typeTab === 'All' &&
  isAllTime &&
  source === 'All' &&
  !search &&
  priority === 'All' &&
  status === 'All'
);

function narrowed(kind) {
  if (due) {
    return 'None' + due + ' for this prospect.';
  }
  if (overdue) {
    return 'None of the overdue tasks match this ' + kind + '.';
  }
  return 'Try another ' + kind + ', or show all tasks.';
}

var title = 'No tasks for this prospect yet';
var message = 'Tasks appear here when a sequence step or rep creates one.';
var icon = 'SvgClipboardCheck';

if (search) {
  var shown = search.length > 40 ? search.slice(0, 40) + '…' : search;
  title = 'No tasks match "' + shown + '"';
  message = 'Try a different word or clear the search.';
  icon = 'SvgSearchMd';
} else if (status !== 'All') {
  title = 'No ' + status.toLowerCase() + ' tasks';
  message = narrowed('status');
  icon = 'SvgCheckCircle';
} else if (priority !== 'All') {
  title = 'No ' + priority + ' priority tasks';
  message = narrowed('priority');
  icon = 'SvgFlag01';
} else if (typeTab === 'Call') {
  title = 'No call tasks';
  message = overdue ? 'No overdue calls for this prospect.' : 'Nothing to call' + when + ' for this prospect.';
  icon = 'SvgPhone';
} else if (typeTab === 'Email') {
  title = 'No email tasks';
  message = overdue ? 'No overdue emails for this prospect.' : 'Nothing to email' + when + ' for this prospect.';
  icon = 'Mail01';
} else if (typeTab === 'LinkedIn') {
  title = 'No LinkedIn tasks';
  message = overdue ? 'No overdue LinkedIn steps for this prospect.' : 'Nothing to do on LinkedIn' + when + ' for this prospect.';
  icon = 'Linkedin';
} else if (typeTab === 'Meeting') {
  title = 'No meeting tasks';
  if (overdue) {
    message = 'No overdue meetings for this prospect.';
  } else if (range === 'Custom') {
    message = 'No meetings in this date range for this prospect.';
  } else {
    message = 'No meetings' + (when ? ' scheduled' + when : '') + ' for this prospect.';
  }
  icon = 'MessageTextSquare02';
} else if (typeTab === 'Generic') {
  title = 'No generic tasks';
  message = overdue ? 'No overdue generic tasks for this prospect.' : 'Nothing else' + due + ' for this prospect.';
  icon = 'CheckSquare';
} else if (typeTab === 'Skipped') {
  title = 'No skipped tasks';
  if (overdue) {
    message = 'None of the overdue tasks were skipped.';
  } else if (isAllTime) {
    message = 'Nothing has been skipped for this prospect.';
  } else {
    message = 'No tasks' + due + ' were skipped.';
  }
  icon = 'SvgFastForward';
} else if (range === 'Today') {
  title = 'No tasks due today';
  message = 'Nothing scheduled for today for this prospect.';
  icon = 'SvgClipboardCheck';
} else if (range === 'This week') {
  title = 'Nothing due this week';
  message = 'No tasks are due this week for this prospect.';
  icon = 'Calendar';
} else if (range === 'This month') {
  title = 'Nothing due this month';
  message = 'No tasks are due this month for this prospect.';
  icon = 'Calendar';
} else if (overdue) {
  title = 'No overdue tasks';
  message = "You're all caught up.";
  icon = 'SvgCheckCircle';
} else if (range === 'Custom') {
  title = 'No tasks in this date range';
  message = 'Try a wider range, or show all tasks.';
  icon = 'Calendar';
} else if (source === 'Automated') {
  title = 'No automated tasks';
  message = 'No sequence-created tasks for this prospect.';
  icon = 'SvgBolt';
} else if (source === 'Manual') {
  title = 'No manual tasks';
  message = 'No rep-created tasks for this prospect.';
  icon = 'User01';
}

return {
  title: title,
  message: message,
  icon: icon,
  showAll: showAll
};

