func_TKWzf.functionBody:
const data = {{ e_6adcba600881d2257a38a6bc['data'] }};
if (!data) {
  return null;
}
const rows = data['objects'] || [];
let pipelineValue = 0;
for (const row of rows) {
  pipelineValue += Number(row && row['properties'] && row['properties']['amount']) || 0;
}
return {
  pipelineValue: pipelineValue,
  fetchedCount: rows.length,
  openCount: data['total'],
};

