func_2xyOr.functionBody:
var type = String({{ var_y6uIV['value'] }} || 'All');
var source = String({{ var_SM2Am['value'] }} || 'All');
var range = String({{ var_0Lq3l['value'] }} || '');
var rangeStart = parseInt(String({{ var_KqWKi['value'] }} || ''), 10);
var rangeEnd = parseInt(String({{ var_CLwpx['value'] }} || ''), 10);
var priority = String({{ var_q4jDy['value'] }} || 'All');
var status = String({{ var_ZVuTt['value'] }} || 'All');
var nowMs = Date.now();

// Server-side filter trees for the Opportunity Detail Tasks card. Returns
//   list    -> fetchRecordsSdrTasks (the table, paged on the server)
//   skipped -> taskFilterSkippedCount (the "Skipped (n)" tab count): the same
//              filters with the type tab swapped for "skipped", so the count
//              equals what the list shows when the Skipped tab is picked.
// Rules (same as Homepage Tasks, agreed 2026-10-25):
// - The due instant is utcTimeEpoch, else dueTime (epoch ms). The day / month /
//   year fields are never used: sequence tasks store them in the PROSPECT's zone.
// - Today / This week (Mon 00:00 - Sun 23:59:59.999) / This month / Custom are
//   bounds in the VIEWER's own time zone (the browser's). '' or 'All time' = no
//   date filter.
// - Overdue = due instant before now, and not completed / skipped / cancelled.
// - Type tabs compare taskType case-insensitively (every casing is listed).
// - Skipped = skipped 1 OR taskStatus skipped. "All" and the type tabs SHOW
//   skipped tasks; only the Skipped tab narrows to them. Completed tasks show
//   under "All statuses".
// - No leaf ever carries a blank value (a blank fails the storage fetch).
var OVERDUE_FLOOR_MS = 946684800000;

function leaf(field, op, value) {
  return { field: field, op: op, values: [value] };
}
function list(field, op, values) {
  return { field: field, op: op, values: values };
}
function missing(field) {
  return { field: field, op: 'MISSING', values: [] };
}
function allOf(values) {
  return { op: 'AND', values: values };
}
function anyOf(values) {
  return { op: 'OR', values: values };
}
// Every casing of each word: as written, lower, UPPER, Title Case, Capitalised.
function variants(words) {
  var out = [];
  function add(x) {
    if (x && out.indexOf(x) === -1) {
      out.push(x);
    }
  }
  words.forEach(function (v) {
    add(v);
    add(v.toLowerCase());
    add(v.toUpperCase());
    add(v.split(' ').map(function (w) { return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase(); }).join(' '));
    add(v.charAt(0).toUpperCase() + v.slice(1).toLowerCase());
    add(v.charAt(0).toLowerCase() + v.slice(1));
  });
  return out;
}

// Viewer-local day bounds (the browser's own time zone).
function localStart(y, m, d) {
  return new Date(y, m - 1, d, 0, 0, 0, 0).getTime();
}
function localEnd(y, m, d) {
  return new Date(y, m - 1, d, 23, 59, 59, 999).getTime();
}
function localStartOf(ms) {
  var t = new Date(ms);
  return localStart(t.getFullYear(), t.getMonth() + 1, t.getDate());
}
function localEndOf(ms) {
  var t = new Date(ms);
  return localEnd(t.getFullYear(), t.getMonth() + 1, t.getDate());
}

var now = new Date(nowMs);
var y = now.getFullYear();
var m = now.getMonth() + 1;
var d = now.getDate();
var backToMonday = (now.getDay() + 6) % 7;

// The due instant inside [startMs, endMs]: utcTimeEpoch, else dueTime.
function dueBetween(startMs, endMs) {
  return anyOf([
    allOf([
      leaf('properties_utcTimeEpoch', 'GTE', startMs),
      leaf('properties_utcTimeEpoch', 'LTE', endMs)
    ]),
    allOf([
      missing('properties_utcTimeEpoch'),
      leaf('properties_dueTime', 'GTE', startMs),
      leaf('properties_dueTime', 'LTE', endMs)
    ])
  ]);
}

var isSkipped = anyOf([
  leaf('properties_skipped', 'EQUAL', 1),
  list('properties_taskStatus', 'IN', variants(['skipped']))
]);
var notClosed = allOf([
  list('properties_taskStatus', 'NOT_IN', variants(['completed', 'skipped', 'cancelled', 'canceled'])),
  anyOf([
    missing('properties_skipped'),
    leaf('properties_skipped', 'NOT_EQUAL', 1)
  ])
]);
var isOverdue = allOf([
  dueBetween(OVERDUE_FLOOR_MS, nowMs - 1),
  notClosed
]);
// Due = open and not overdue yet (due now or later, or no due time at all).
var isDue = allOf([
  notClosed,
  anyOf([
    leaf('properties_utcTimeEpoch', 'GTE', nowMs),
    allOf([
      missing('properties_utcTimeEpoch'),
      anyOf([
        missing('properties_dueTime'),
        leaf('properties_dueTime', 'GTE', nowMs)
      ])
    ])
  ])
]);
var typeWords = {
  Call: ['Call'],
  Email: ['Email'],
  LinkedIn: ['LinkedIn', 'Linkedin'],
  Meeting: ['Meeting'],
  Generic: ['Generic', 'Task', 'Other']
};

// Everything except the type tab.
var common = [];
if (source === 'Manual') {
  common.push(list('properties_source', 'IN', variants(['manual'])));
} else if (source === 'Automated') {
  common.push(list('properties_source', 'NOT_IN', variants(['manual'])));
}
if (range === 'Today') {
  common.push(dueBetween(localStart(y, m, d), localEnd(y, m, d)));
} else if (range === 'This week') {
  common.push(dueBetween(localStart(y, m, d - backToMonday), localEnd(y, m, d - backToMonday + 6)));
} else if (range === 'This month') {
  common.push(dueBetween(localStart(y, m, 1), localEnd(y, m + 1, 0)));
} else if (range === 'Overdue') {
  common.push(isOverdue);
} else if (range === 'Custom') {
  if (!isNaN(rangeStart) && !isNaN(rangeEnd) && rangeStart > 0 && rangeEnd > 0) {
    common.push(dueBetween(localStartOf(Math.min(rangeStart, rangeEnd)), localEndOf(Math.max(rangeStart, rangeEnd))));
  } else {
    common.push(dueBetween(localStart(y, m, d), localEnd(y, m, d)));
  }
}
if (priority !== 'All' && priority !== '') {
  common.push(list('properties_priority', 'IN', variants([priority])));
}
if (status === 'Due') {
  common.push(isDue);
} else if (status === 'Overdue') {
  common.push(isOverdue);
} else if (status === 'Completed') {
  common.push(list('properties_taskStatus', 'IN', variants(['completed'])));
} else if (status === 'Skipped') {
  common.push(isSkipped);
} else if (status === 'Pending') {
  common.push(allOf([
    list('properties_taskStatus', 'IN', variants(['pending'])),
    anyOf([missing('properties_skipped'), leaf('properties_skipped', 'NOT_EQUAL', 1)])
  ]));
} else if (status === 'Cancelled') {
  common.push(list('properties_taskStatus', 'IN', variants(['cancelled', 'canceled'])));
} else if (status === 'Paused') {
  common.push(list('properties_taskStatus', 'IN', variants(['paused'])));
}

var typeClause = null;
if (type === 'Skipped') {
  typeClause = isSkipped;
} else if (type !== 'All') {
  typeClause = list('properties_taskType', 'IN', variants(typeWords[type] || [type]));
}

var listClauses = common.slice();
if (typeClause) {
  listClauses.push(typeClause);
}
var skippedClauses = common.slice();
skippedClauses.push(isSkipped);

return {
  list: allOf(listClauses),
  skipped: allOf(skippedClauses)
};

func_FoLqc.functionBody:
// Opportunity Detail > Tasks: what the empty table says when the filter bar
// leaves no rows (fetchRecordsSdrTasks returns none). One empty view reads this.
// Same copy as Account Overview's taskEmptyStateCopy (func_Ve10t), for an opportunity.
// Precedence: search -> status -> priority -> type tab -> due range -> source.
// Range '' (no date filter) reads like "All time".
// showAll is false only when nothing narrows the list (All type, no range or
// All time, All source, no search, All priority, All status): then the
// opportunity truly has no tasks and "Show all tasks" would do nothing.
var search = String({{ var_WxRJN['value'] }} || '').trim();
var status = String({{ var_ZVuTt['value'] }} || 'All');
var priority = String({{ var_q4jDy['value'] }} || 'All');
var typeTab = String({{ var_y6uIV['value'] }} || 'All');
var range = String({{ var_0Lq3l['value'] }} || '');
var source = String({{ var_SM2Am['value'] }} || 'All');

var isAllTime = range === '' || range === 'All time';
var overdue = range === 'Overdue';

// " today", " this week", " this month", " in this date range", or "".
var when = '';
if (range === 'Today') {
  when = ' today';
} else if (range === 'This week') {
  when = ' this week';
} else if (range === 'This month') {
  when = ' this month';
} else if (range === 'Custom') {
  when = ' in this date range';
}

// The same range after a noun: " due today", " in this date range", or "".
var due = '';
if (range === 'Custom') {
  due = when;
} else if (when) {
  due = ' due' + when;
}

var showAll = !(
  typeTab === 'All' &&
  isAllTime &&
  source === 'All' &&
  !search &&
  priority === 'All' &&
  status === 'All'
);

function narrowed(kind) {
  if (due) {
    return 'None' + due + ' for this opportunity.';
  }
  if (overdue) {
    return 'None of the overdue tasks match this ' + kind + '.';
  }
  return 'Try another ' + kind + ', or show all tasks.';
}

var title = 'No tasks for this opportunity yet';
var message = 'Tasks appear here when a sequence step or rep creates one.';
var icon = 'SvgClipboardCheck';

if (search) {
  var shown = search.length > 40 ? search.slice(0, 40) + '…' : search;
  title = 'No tasks match "' + shown + '"';
  message = 'Try a different word or clear the search.';
  icon = 'SvgSearchMd';
} else if (status !== 'All') {
  title = 'No ' + status.toLowerCase() + ' tasks';
  message = narrowed('status');
  icon = 'SvgCheckCircle';
} else if (priority !== 'All') {
  title = 'No ' + priority + ' priority tasks';
  message = narrowed('priority');
  icon = 'SvgFlag01';
} else if (typeTab === 'Call') {
  title = 'No call tasks';
  message = overdue ? 'No overdue calls for this opportunity.' : 'Nothing to call' + when + ' for this opportunity.';
  icon = 'SvgPhone';
} else if (typeTab === 'Email') {
  title = 'No email tasks';
  message = overdue ? 'No overdue emails for this opportunity.' : 'Nothing to email' + when + ' for this opportunity.';
  icon = 'Mail01';
} else if (typeTab === 'LinkedIn') {
  title = 'No LinkedIn tasks';
  message = overdue ? 'No overdue LinkedIn steps for this opportunity.' : 'Nothing to do on LinkedIn' + when + ' for this opportunity.';
  icon = 'Linkedin';
} else if (typeTab === 'Meeting') {
  title = 'No meeting tasks';
  if (overdue) {
    message = 'No overdue meetings for this opportunity.';
  } else if (range === 'Custom') {
    message = 'No meetings in this date range for this opportunity.';
  } else {
    message = 'No meetings' + (when ? ' scheduled' + when : '') + ' for this opportunity.';
  }
  icon = 'MessageTextSquare02';
} else if (typeTab === 'Generic') {
  title = 'No generic tasks';
  message = overdue ? 'No overdue generic tasks for this opportunity.' : 'Nothing else' + due + ' for this opportunity.';
  icon = 'CheckSquare';
} else if (typeTab === 'Skipped') {
  title = 'No skipped tasks';
  if (overdue) {
    message = 'None of the overdue tasks were skipped.';
  } else if (isAllTime) {
    message = 'Nothing has been skipped for this opportunity.';
  } else {
    message = 'No tasks' + due + ' were skipped.';
  }
  icon = 'SvgFastForward';
} else if (range === 'Today') {
  title = 'No tasks due today';
  message = 'Nothing scheduled for today for this opportunity.';
  icon = 'SvgClipboardCheck';
} else if (range === 'This week') {
  title = 'Nothing due this week';
  message = 'No tasks are due this week for this opportunity.';
  icon = 'Calendar';
} else if (range === 'This month') {
  title = 'Nothing due this month';
  message = 'No tasks are due this month for this opportunity.';
  icon = 'Calendar';
} else if (overdue) {
  title = 'No overdue tasks';
  message = "You're all caught up.";
  icon = 'SvgCheckCircle';
} else if (range === 'Custom') {
  title = 'No tasks in this date range';
  message = 'Try a wider range, or show all tasks.';
  icon = 'Calendar';
} else if (source === 'Automated') {
  title = 'No automated tasks';
  message = 'No sequence-created tasks for this opportunity.';
  icon = 'SvgBolt';
} else if (source === 'Manual') {
  title = 'No manual tasks';
  message = 'No rep-created tasks for this opportunity.';
  icon = 'User01';
}

return {
  title: title,
  message: message,
  icon: icon,
  showAll: showAll
};

func_tvibe.functionBody:
const enrolmentSource = {{ e_6add298c0881d2257a4a6f11 }} || {};
const taskSource = {{ e_6add298c5236864dd82a5b2e }} || {};

const TYPE_LABELS = {
  call: 'Call',
  email: 'Email',
  linkedin: 'LinkedIn',
  meeting: 'Meeting',
  generic: 'Task',
  task: 'Task',
};
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

const typeLabel = (raw) => {
  const key = String(raw || '').toLowerCase();
  return TYPE_LABELS[key] || (raw ? String(raw) : 'Task');
};

const toMs = (value) => {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : null;
};

const clock = (date) => {
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const suffix = hours < 12 ? 'am' : 'pm';
  const hour12 = hours % 12 === 0 ? 12 : hours % 12;
  return hour12 + (minutes ? ':' + String(minutes).padStart(2, '0') : '') + suffix;
};

const startOfDay = (date) => new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();

const formatDue = (ms, now) => {
  const due = new Date(ms);
  const dayDiff = Math.round((startOfDay(due) - startOfDay(now)) / 86400000);
  const shortDate = MONTHS[due.getMonth()] + ' ' + due.getDate();
  if (ms < now.getTime()) {
    return 'Overdue · ' + (dayDiff === 0 ? clock(due) : shortDate);
  }
  if (dayDiff === 0) {
    return 'Today ' + clock(due);
  }
  if (dayDiff === 1) {
    return 'Tomorrow ' + clock(due);
  }
  if (dayDiff < 7) {
    return WEEKDAYS[due.getDay()] + ' ' + clock(due);
  }
  return shortDate + ' ' + clock(due);
};

const ago = (count, unit) => count + ' ' + unit + (count === 1 ? '' : 's') + ' ago';

const formatAgo = (ms, now) => {
  const minutes = Math.floor(Math.max(0, now.getTime() - ms) / 60000);
  if (minutes < 1) {
    return 'just now';
  }
  if (minutes < 60) {
    return ago(minutes, 'min');
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return ago(hours, 'hour');
  }
  const days = Math.floor(hours / 24);
  if (days < 7) {
    return ago(days, 'day');
  }
  if (days < 30) {
    return ago(Math.floor(days / 7), 'week');
  }
  if (days < 365) {
    return ago(Math.floor(days / 30), 'month');
  }
  return ago(Math.floor(days / 365), 'year');
};

const now = new Date();

const activeSequences = {};
((enrolmentSource.data || {}).objects || []).forEach((enrolment) => {
  const props = (enrolment && enrolment.properties) || {};
  if (props.prospectId && props.status === 'IN_PROGRESS') {
    activeSequences[props.prospectId] = (activeSequences[props.prospectId] || 0) + 1;
  }
});

const nextOpen = {};
const lastDone = {};
((taskSource.data || {}).objects || []).forEach((task) => {
  const props = (task && task.properties) || {};
  const prospectId = props.prospectId;
  if (!prospectId) {
    return;
  }
  if (props.taskStatus === 'pending' || props.taskStatus === 'in_progress') {
    const due = toMs(props.utcTimeEpoch) ?? toMs(props.dueTime);
    const current = nextOpen[prospectId];
    const sooner = Boolean(current) && due !== null && (current.due === null || due < current.due);
    if (!current || sooner) {
      nextOpen[prospectId] = { due: due, type: props.taskType };
    }
  } else if (props.taskStatus === 'completed') {
    const at = toMs(props.completedAt) ?? toMs(props.markedSentAt) ?? toMs(task.modifiedTime);
    const current = lastDone[prospectId];
    if (at !== null && (!current || at > current.at)) {
      lastDone[prospectId] = { at: at, type: props.taskType };
    }
  }
});

const nextTask = {};
Object.keys(nextOpen).forEach((prospectId) => {
  const item = nextOpen[prospectId];
  nextTask[prospectId] = typeLabel(item.type) + (item.due === null ? '' : ' · ' + formatDue(item.due, now));
});

const lastTask = {};
Object.keys(lastDone).forEach((prospectId) => {
  const item = lastDone[prospectId];
  lastTask[prospectId] = typeLabel(item.type) + ' · ' + formatAgo(item.at, now);
});

const pendingText = (source) => {
  if (source.error) {
    return '—';
  }
  if (source.isLoading === true || source.isFetching === true) {
    return '…';
  }
  return source.data ? '' : '…';
};

return {
  sequencesPending: pendingText(enrolmentSource),
  tasksPending: pendingText(taskSource),
  activeSequences: activeSequences,
  nextTask: nextTask,
  lastTask: lastTask,
};

func_lSzUL.functionBody:
// Opportunity Detail > Sequences: the enrolments of this opportunity's prospects.
// Status and search are filtered on the server by the table toolbar (fetch inputs),
// the same way Prospect Detail > Sequences does; this only joins prospect names and sorts.
const rows = (({{ e_6a575f2187cd3b7aa8cc5f94['data'] }} || {})['objects']) || [];
const prospects = (({{ e_6a4e7a37f0fc262d9643bf9f['data'] }} || {})['objects']) || [];
const nameById = {};
prospects.forEach(function (row) {
  nameById[row['id']] = (row['properties'] || {})['prospectName'];
});
const clean = function (v) {
  return (v === null || v === undefined || String(v).trim() === '') ? '—' : v;
};
const relTime = function (ms) {
  if (!ms) {
    return '';
  }
  const abs = Math.abs(Date.now() - ms);
  const minute = 60000;
  const hour = 3600000;
  const day = 86400000;
  const week = day * 7;
  const month = day * 30;
  if (abs < hour) {
    return Math.max(1, Math.round(abs / minute)) + 'm';
  }
  if (abs < day) {
    return Math.floor(abs / hour) + 'h ' + Math.round((abs % hour) / minute) + 'm';
  }
  if (abs < month) {
    return Math.floor(abs / day) + 'd ' + Math.round((abs % day) / hour) + 'h';
  }
  const w = Math.round((abs % month) / week);
  return Math.floor(abs / month) + 'mo' + (w ? ' ' + w + 'w' : '');
};

return rows
  .map(function (row) {
    const p = row['properties'] || {};
    return {
      id: row['id'],
      properties: Object.assign({}, p, {
        prospectName: clean(p['prospectName'] || nameById[p['prospectId']]),
        currentStep: clean(p['currentStep']),
        lastContactedRel: clean(relTime(p['lastTouchedAt'])),
        isLive: p['status'] !== 'PAUSED',
      }),
    };
  })
  .sort(function (a, b) {
    return Number(b['properties']['enrolledAt'] || 0) - Number(a['properties']['enrolledAt'] || 0);
  });

