const champ = chObjs.length && chObjs[0] && chObjs[0].properties ? chObjs[0].properties : null;
const blank = (v) => v === null || v === undefined || String(v).trim() === '';
const isNA = (s) => /^\s*((na|n\/a|null|none|undefined|-)\s*,?\s*)*$/i.test(String(s));
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const clean = (s) => String(s).trim().replace(/^\[\s*/, '').replace(/\s*\]$/, '').replace(/^"+/, '').replace(/"+$/, '').trim();
const parseList = (v) => {
  if (blank(v)) return [];
  let arr;
  if (Array.isArray(v)) {
    arr = v;
  } else {
    const t = String(v).trim();
    try {
      const j = JSON.parse(t);
      arr = Array.isArray(j) ? j : [j];
    } catch (e) {
      arr = [t];
    }
  }
  return arr
    .map((x) => (x && typeof x === 'object') ? (x.text || x.title || x.value || '') : x)
    .map((x) => clean(x))
    .filter((x) => x && !isNA(x))
    .map(esc);
};
const codes = { healthy: 'Healthy', watch_closely: 'Watch closely', needs_attention: 'Watch closely', at_risk: 'At risk' };
const tier = (n) => (n >= 80 ? 'healthy' : n >= 60 ? 'watch_closely' : 'at_risk');
const score = Number(p.health_score);
const scoreOk = has && !blank(p.health_score) && !isNaN(score);
const labelCode = codes[p.health_label] ? (p.health_label === 'needs_attention' ? 'watch_closely' : p.health_label) : (scoreOk ? tier(score) : '');
const chgRaw = blank(p.health_score_change) ? '' : String(p.health_score_change).replace(/[^0-9.+-]/g, '');
const chg = parseFloat(chgRaw);
const changeText = isNaN(chg) ? '' : ((chg >= 0 ? '+' : '') + chg + ' in the last 7 days');
let closeDate = '—';
const cdNum = Number(p.close_date);
if (!blank(p.close_date) && !isNaN(cdNum)) {
  const ms = cdNum < 100000000000 ? cdNum * 1000 : cdNum;
  closeDate = new Date(ms).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
}
const md = blank(p.meeting_date) ? '' : String(p.meeting_date).trim();
const mt = blank(p.meeting_time) ? '' : String(p.meeting_time).trim();
const hasMeeting = md !== '' && !isNA(md);
const amt = Number(p.amount);
