    checked = Array(totalCount).fill(true);
  } else if (checked.length === 0) {
    // no existing data -> initialize all as true (your original default)
    checked = Array(totalCount).fill(true);
  } else {
    // normal toggle behavior
    checked = checked.map(v => !v);
  }

  {{ var_ChgvJ.setValue(checked) }}
  console.log('✅ Success | selectAll:', selectAll, '| result:', checked);
