(() => {
  try {
    const oppData = b_tyVAv['currentData'] || [];
    const oppNotes = var_ChgvJ['value'] || [];

    const prospectData = b_Upiqf['currentData'] || [];
    const prospectNotes = var_NuCKU['value'] || [];

    const selected = [
      ...oppData
        .filter((_, index) => oppNotes[index])
        .map(item => item.properties.opportunityName),
      ...prospectData
        .filter((_, index) => prospectNotes[index])
        .map(item => item.properties.prospectName),
      ...(b_cRBNd['value'] ? ["General note"] : [])
    ];

    let result;
    if (selected.length === 0) result = "General note";
    else if (selected.length === 1) result = selected[0];
    else result = `${selected.length} selected`;

    console.log('✅ Success | selected:', selected, '| result:', result);
    return result;
  } catch (err) {
    console.error('❌ Failed to compute selected label:', err);
    return "General note";
  }
})()
}}

