func_ewRNP.functionBody:
// Prospects tab rows -> Active sequences count, Next task and Last task, keyed by prospect record id (row id).
// Same rules as the main Prospects table's func_pVmtr.
const enrolmentSource = {{ e_6adc9e8d5236864dd81993a0 }} || {};
const taskSource = {{ e_6adc9e8d5236864dd819939b }} || {};

const TYPE_LABELS = {
  call: 'Call',
  email: 'Email',
  linkedin: 'LinkedIn',
  meeting: 'Meeting',
  generic: 'Task',
  task: 'Task',
};
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

const typeLabel = (raw) => {
  const key = String(raw || '').toLowerCase();
  return TYPE_LABELS[key] || (raw ? String(raw) : 'Task');
};

const toMs = (value) => {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : null;
};

const clock = (date) => {
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const suffix = hours < 12 ? 'am' : 'pm';
  const hour12 = hours % 12 === 0 ? 12 : hours % 12;
  return hour12 + (minutes ? ':' + String(minutes).padStart(2, '0') : '') + suffix;
};

const startOfDay = (date) => new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();

const formatDue = (ms, now) => {
  const due = new Date(ms);
  const dayDiff = Math.round((startOfDay(due) - startOfDay(now)) / 86400000);
  const shortDate = MONTHS[due.getMonth()] + ' ' + due.getDate();
  if (ms < now.getTime()) {
    return 'Overdue · ' + (dayDiff === 0 ? clock(due) : shortDate);
  }
  if (dayDiff === 0) {
    return 'Today ' + clock(due);
  }
  if (dayDiff === 1) {
    return 'Tomorrow ' + clock(due);
  }
  if (dayDiff < 7) {
    return WEEKDAYS[due.getDay()] + ' ' + clock(due);
  }
  return shortDate + ' ' + clock(due);
};

const ago = (count, unit) => count + ' ' + unit + (count === 1 ? '' : 's') + ' ago';

const formatAgo = (ms, now) => {
  const minutes = Math.floor(Math.max(0, now.getTime() - ms) / 60000);
  if (minutes < 1) {
    return 'just now';
  }
  if (minutes < 60) {
    return ago(minutes, 'min');
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return ago(hours, 'hour');
  }
  const days = Math.floor(hours / 24);
  if (days < 7) {
    return ago(days, 'day');
  }
  if (days < 30) {
    return ago(Math.floor(days / 7), 'week');
  }
  if (days < 365) {
    return ago(Math.floor(days / 30), 'month');
  }
  return ago(Math.floor(days / 365), 'year');
};

const now = new Date();

const activeSequences = {};
((enrolmentSource.data || {}).objects || []).forEach((enrolment) => {
  const props = (enrolment && enrolment.properties) || {};
  if (props.prospectId && props.status === 'IN_PROGRESS') {
    activeSequences[props.prospectId] = (activeSequences[props.prospectId] || 0) + 1;
  }
});

const nextOpen = {};
const lastDone = {};
((taskSource.data || {}).objects || []).forEach((task) => {
  const props = (task && task.properties) || {};
  const prospectId = props.prospectId;
  if (!prospectId) {
    return;
  }
  if (props.taskStatus === 'pending' || props.taskStatus === 'in_progress') {
    const due = toMs(props.utcTimeEpoch) ?? toMs(props.dueTime);
    const current = nextOpen[prospectId];
    const sooner = Boolean(current) && due !== null && (current.due === null || due < current.due);
    if (!current || sooner) {
      nextOpen[prospectId] = { due: due, type: props.taskType };
    }
  } else if (props.taskStatus === 'completed') {
    const at = toMs(props.completedAt) ?? toMs(props.markedSentAt) ?? toMs(task.mTm) ?? toMs(task.modifiedTime);
    const current = lastDone[prospectId];
    if (at !== null && (!current || at > current.at)) {
      lastDone[prospectId] = { at: at, type: props.taskType };
    }
  }
});

const nextTask = {};
Object.keys(nextOpen).forEach((prospectId) => {
  const item = nextOpen[prospectId];
  nextTask[prospectId] = typeLabel(item.type) + (item.due === null ? '' : ' · ' + formatDue(item.due, now));
});

const lastTask = {};
Object.keys(lastDone).forEach((prospectId) => {
  const item = lastDone[prospectId];
  lastTask[prospectId] = typeLabel(item.type) + ' · ' + formatAgo(item.at, now);
});

const pendingText = (source) => {
  if (source.error) {
    return '—';
  }
  if (source.isLoading === true || source.isFetching === true) {
    return '…';
  }
  return source.data ? '' : '…';
};

return {
  sequencesPending: pendingText(enrolmentSource),
  tasksPending: pendingText(taskSource),
  activeSequences: activeSequences,
  nextTask: nextTask,
  lastTask: lastTask,
};

func_Ve10t.functionBody:
// Account Overview > Tasks: what the empty table says when the filter bar
// leaves no rows (func_trkvA is empty). One empty view reads this.
// Precedence: search -> status -> priority -> type tab -> due range -> source.
// showAll is false only when nothing narrows the list (All type, All time,
// All source, no search, All priority, All status): then the account truly
// has no tasks and "Show all tasks" would do nothing.
var search = String({{ var_ZAcID['value'] }} || '').trim();
var status = String({{ var_ppPJm['value'] }} || 'All');
var priority = String({{ var_YvTHt['value'] }} || 'All');
var typeTab = String({{ var_iGNmD['value'] }} || 'All');
var range = String({{ var_Dk3An['value'] }} || '');
var source = String({{ var_D0RUI['value'] }} || 'All');

var isAllTime = range === '' || range === 'All time';
var overdue = range === 'Overdue';

// " today", " this week", " this month", " in this date range", or "".
var when = '';
if (range === 'Today') {
  when = ' today';
} else if (range === 'This week') {
  when = ' this week';
} else if (range === 'This month') {
  when = ' this month';
} else if (range === 'Custom') {
  when = ' in this date range';
}

// The same range after a noun: " due today", " in this date range", or "".
var due = '';
if (range === 'Custom') {
  due = when;
} else if (when) {
  due = ' due' + when;
}

var showAll = !(
  typeTab === 'All' &&
  isAllTime &&
  source === 'All' &&
  !search &&
  priority === 'All' &&
  status === 'All'
);

function narrowed(kind) {
  if (due) {
    return 'None' + due + ' for this account.';
  }
  if (overdue) {
    return 'None of the overdue tasks match this ' + kind + '.';
  }
  return 'Try another ' + kind + ', or show all tasks.';
}

var title = 'No tasks for this account yet';
var message = 'Tasks appear here when a sequence step or rep creates one.';
var icon = 'SvgClipboardCheck';

if (search) {
  var shown = search.length > 40 ? search.slice(0, 40) + '…' : search;
  title = 'No tasks match "' + shown + '"';
  message = 'Try a different word or clear the search.';
  icon = 'SvgSearchMd';
} else if (status !== 'All') {
  title = 'No ' + status.toLowerCase() + ' tasks';
  message = narrowed('status');
  icon = 'SvgCheckCircle';
} else if (priority !== 'All') {
  title = 'No ' + priority + ' priority tasks';
  message = narrowed('priority');
  icon = 'SvgFlag01';
} else if (typeTab === 'Call') {
  title = 'No call tasks';
  message = overdue ? 'No overdue calls for this account.' : 'Nothing to call' + when + ' for this account.';
  icon = 'SvgPhone';
} else if (typeTab === 'Email') {
  title = 'No email tasks';
  message = overdue ? 'No overdue emails for this account.' : 'Nothing to email' + when + ' for this account.';
  icon = 'Mail01';
} else if (typeTab === 'LinkedIn') {
  title = 'No LinkedIn tasks';
  message = overdue ? 'No overdue LinkedIn steps for this account.' : 'Nothing to do on LinkedIn' + when + ' for this account.';
  icon = 'Linkedin';
} else if (typeTab === 'Meeting') {
  title = 'No meeting tasks';
  if (overdue) {
    message = 'No overdue meetings for this account.';
  } else if (range === 'Custom') {
    message = 'No meetings in this date range for this account.';
  } else {
    message = 'No meetings' + (when ? ' scheduled' + when : '') + ' for this account.';
  }
  icon = 'MessageTextSquare02';
} else if (typeTab === 'Generic') {
  title = 'No generic tasks';
  message = overdue ? 'No overdue generic tasks for this account.' : 'Nothing else' + due + ' for this account.';
  icon = 'CheckSquare';
} else if (typeTab === 'Skipped') {
  title = 'No skipped tasks';
  if (overdue) {
    message = 'None of the overdue tasks were skipped.';
  } else if (isAllTime) {
    message = 'Nothing has been skipped for this account.';
  } else {
    message = 'No tasks' + due + ' were skipped.';
  }
  icon = 'SvgFastForward';
} else if (range === 'Today') {
  title = 'No tasks due today';
  message = 'Nothing scheduled for today for this account.';
  icon = 'SvgClipboardCheck';
} else if (range === 'This week') {
  title = 'Nothing due this week';
  message = 'No tasks are due this week for this account.';
  icon = 'Calendar';
} else if (range === 'This month') {
  title = 'Nothing due this month';
  message = 'No tasks are due this month for this account.';
  icon = 'Calendar';
} else if (overdue) {
  title = 'No overdue tasks';
  message = "You're all caught up.";
  icon = 'SvgCheckCircle';
} else if (range === 'Custom') {
  title = 'No tasks in this date range';
  message = 'Try a wider range, or show all tasks.';
  icon = 'Calendar';
} else if (source === 'Automated') {
  title = 'No automated tasks';
  message = 'No sequence-created tasks for this account.';
  icon = 'SvgBolt';
} else if (source === 'Manual') {
  title = 'No manual tasks';
  message = 'No rep-created tasks for this account.';
  icon = 'User01';
}

return {
  title: title,
  message: message,
  icon: icon,
  showAll: showAll
};

func_Xqy2k.functionBody:
// Sequences tab rows (sequence source) -> Last step, Last contacted, Added by, keyed by enrolment row id.
const enrolments = ({{ e_6a5637ea6454dc4d22e88ce7['data'] }} || {}).objects || [];
const tasksData = {{ e_6adc9e8d0881d2257a29a111['data'] }};
const stepsData = {{ e_6adc9e8d5236864dd81993a1['data'] }};
const tasksLoading = {{ e_6adc9e8d0881d2257a29a111['isLoading'] }} === true;
const stepsLoading = {{ e_6adc9e8d5236864dd81993a1['isLoading'] }} === true;
const failed = !!({{ e_6adc9e8d0881d2257a29a111['error'] }} || {{ e_6adc9e8d5236864dd81993a1['error'] }});
const now = Date.now();

function relAgo(ms) {
  const minutes = Math.floor(Math.max(0, now - ms) / 60000);
  if (minutes < 1) {
    return 'just now';
  }
  if (minutes < 60) {
    return minutes + 'm ago';
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return hours + 'h ago';
  }
  const days = Math.floor(hours / 24);
  if (days < 30) {
    return days + 'd ago';
  }
  if (days < 365) {
    return Math.floor(days / 30) + 'mo ago';
  }
  return Math.floor(days / 365) + 'y ago';
}

function addedByOf(p) {
  if (p.source === 'rule') {
    return 'Rule: ' + (p.ruleSummary || 'auto-enrolment');
  }
  if (p.addedByName) {
    return p.addedByName;
  }
  if (p.source === 'ai_sdr') {
    return 'AI SDR';
  }
  return '—';
}

function channelOf(raw) {
  const v = String(raw || '').trim();
  const k = v.toLowerCase();
  if (k === 'email') return 'Email';
  if (k === 'linkedin') return 'LinkedIn';
  if (k === 'call') return 'Call';
  if (k === 'meeting') return 'Meeting';
  if (k === 'task' || k === 'generic') return 'Task';
  if (!v) return '';
  return v.charAt(0).toUpperCase() + v.slice(1);
}

const lastContacted = {};
const addedBy = {};
enrolments.forEach(function (r) {
  const p = r.properties || {};
  const touched = Number(p.lastTouchedAt || 0);
  lastContacted[r.id] = touched > 0 ? relAgo(touched) : '—';
  addedBy[r.id] = addedByOf(p);
});

const lastStep = {};
let lastStepReady = false;
if (failed || enrolments.length === 0) {
  lastStepReady = true;
} else if (tasksData && stepsData && !tasksLoading && !stepsLoading) {
  const tasks = tasksData.objects || [];
  const steps = stepsData.objects || [];

  function better(a, b) {
    return !b || Number(a.versionNumber || 0) > Number(b.versionNumber || 0);
  }

  const byVersionKey = {};
  const bySeqKey = {};
  const byVersionNum = {};
  const bySeqNum = {};
  const latestVersionOfSeq = {};
  steps.forEach(function (s) {
    const p = s.properties || {};
    if (p.versionId && p.stepKey) {
      byVersionKey[p.versionId + '|' + p.stepKey] = p;
    }
    if (p.seqId && p.stepKey && better(p, bySeqKey[p.seqId + '|' + p.stepKey])) {
      bySeqKey[p.seqId + '|' + p.stepKey] = p;
    }
    if (p.versionId && p.stepNumber != null) {
      byVersionNum[p.versionId + '|' + p.stepNumber] = p;
    }
    if (p.seqId && p.stepNumber != null && better(p, bySeqNum[p.seqId + '|' + p.stepNumber])) {
      bySeqNum[p.seqId + '|' + p.stepNumber] = p;
    }
    if (p.seqId && better(p, latestVersionOfSeq[p.seqId])) {
      latestVersionOfSeq[p.seqId] = p;
    }
  });

  function timeOf(t) {
    const p = t.properties || {};
    return Number(p.completedAt || p.markedSentAt || t.modifiedTime || t.createdTime || 0);
  }

  const latestByEnrolment = {};
  const latestByProspectSeq = {};
  tasks.forEach(function (t) {
    const p = t.properties || {};
    if (p.enrollmentId) {
      const cur = latestByEnrolment[p.enrollmentId];
      if (!cur || timeOf(t) > timeOf(cur)) {
        latestByEnrolment[p.enrollmentId] = t;
      }
    }
    if (p.prospectId && p.sequenceId) {
      const key = p.prospectId + '|' + p.sequenceId;
      const cur = latestByProspectSeq[key];
      if (!cur || timeOf(t) > timeOf(cur)) {
        latestByProspectSeq[key] = t;
      }
    }
  });

  enrolments.forEach(function (r) {
    const e = r.properties || {};
    const seqId = e.sequenceId;
    const task = latestByEnrolment[r.id] || latestByProspectSeq[e.prospectId + '|' + seqId] || null;
    let label = '—';
    if (task) {
      const tp = task.properties || {};
      const runVersion = e.sequenceVersionId || (latestVersionOfSeq[seqId] || {}).versionId;
      let step = null;
      if (tp.blockId) {
        step = (runVersion && byVersionKey[runVersion + '|' + tp.blockId])
          || (tp.sequenceVersionId && byVersionKey[tp.sequenceVersionId + '|' + tp.blockId])
          || bySeqKey[seqId + '|' + tp.blockId]
          || null;
      }
      if (step && step.stepNumber != null) {
        const ch = channelOf(step.taskType) || channelOf(tp.taskType);
        label = 'Step ' + step.stepNumber + (ch ? ' · ' + ch : '');
      } else {
        const n = Number(e.cur_step || 0) - 1;
        if (n > 0) {
          const fs = (runVersion && byVersionNum[runVersion + '|' + n]) || bySeqNum[seqId + '|' + n] || null;
          const ch = channelOf(fs ? fs.taskType : tp.taskType);
          label = 'Step ' + n + (ch ? ' · ' + ch : '');
        }
      }
    }
    lastStep[r.id] = label;
  });
  lastStepReady = true;
}

return {
  lastStepReady: lastStepReady,
  lastStep: lastStep,
  lastContacted: lastContacted,
  addedBy: addedBy,
};

