func_trkvA.functionBody:
// Account Overview > Tasks: the task list after the filter bar's controls,
// applied client-side to the rows Tasks_Table loaded for this account and the
// signed-in user (completed and skipped included). Rules, shared with
// Homepage Tasks and with func_vyXdx (keep the two bodies in step):
// - Due instant = utcTimeEpoch, else dueTime (epoch ms); never day/month/year.
// - Today / This week (Mon-Sun) / This month / Custom: bounds in the viewer's
//   own browser time zone. All time: no date filter.
// - Overdue = due before now and not completed, skipped or cancelled.
// - Type tabs compare taskType case-insensitively; All and type tabs show
//   skipped and completed tasks; only "Skipped" narrows to skipped.
var objects = {{ e_6a50b59ad9254572004794aa['data']?.['objects'] }} || [];
var typeTab = String({{ var_iGNmD['value'] }} || 'All');
var sourceFilter = String({{ var_D0RUI['value'] }} || 'All');
var rangePreset = String({{ var_Dk3An['value'] }} || '');
var customStartRaw = String({{ var_GjLgE['value'] }} || '');
var customEndRaw = String({{ var_9O8vT['value'] }} || '');
var searchFilter = String({{ var_ZAcID['value'] }} || '').trim().toLowerCase();
var priorityFilter = String({{ var_YvTHt['value'] }} || 'All');
var statusFilter = String({{ var_ppPJm['value'] }} || 'All');
var nowMs = Date.now();

function fieldsOf(row) {
  return (row && row.properties) || row || {};
}

function statusOf(row) {
  var s = fieldsOf(row).taskStatus;
  return String(s == null ? '' : s).trim().toLowerCase();
}

function toEpochMs(raw) {
  if (raw == null || raw === '') {
    return null;
  }
  var n = typeof raw === 'number' ? raw : Number(String(raw).trim());
  if (isNaN(n)) {
    var parsed = Date.parse(String(raw));
    return isNaN(parsed) ? null : parsed;
  }
  if (n <= 0) {
    return null;
  }
  // An epoch in seconds becomes milliseconds.
  return n < 100000000000 ? n * 1000 : n;
}

// The task's real due instant: utcTimeEpoch, else dueTime. Never day/month/year,
// which sequence tasks store in the PROSPECT's time zone.
function dueOf(row) {
  var f = fieldsOf(row);
  var ms = toEpochMs(f.utcTimeEpoch);
  return ms !== null ? ms : toEpochMs(f.dueTime);
}

function isSkipped(row) {
  var v = fieldsOf(row).skipped;
  return v === 1 || v === '1' || v === true || v === 'true' || statusOf(row) === 'skipped';
}

function isCompleted(row) {
  return statusOf(row) === 'completed';
}

function isCancelled(row) {
  var s = statusOf(row);
  return s === 'cancelled' || s === 'canceled';
}

function isOverdue(row) {
  if (isCompleted(row) || isSkipped(row) || isCancelled(row)) {
    return false;
  }
  var ms = dueOf(row);
  return ms !== null && ms < nowMs;
}

function isDueNotYet(row) {
  var status = statusOf(row);
  if (status === 'completed' || status === 'upcoming' || status === 'paused' || isSkipped(row) || isCancelled(row)) {
    return false;
  }
  var ms = dueOf(row);
  return ms === null || ms >= nowMs;
}

// Date bounds in the VIEWER's own time zone: a plain Date works in the
// browser's zone. Week = Monday 00:00 to Sunday 23:59:59.999.
var viewerNow = new Date(nowMs);
var vy = viewerNow.getFullYear();
var vm = viewerNow.getMonth();
var vd = viewerNow.getDate();
var backToMonday = (viewerNow.getDay() + 6) % 7;

function dayStart(y, m, d) {
  return new Date(y, m, d, 0, 0, 0, 0).getTime();
}

function dayEnd(y, m, d) {
  return new Date(y, m, d, 23, 59, 59, 999).getTime();
}

var bounds = null;
if (rangePreset === 'Today') {
  bounds = [dayStart(vy, vm, vd), dayEnd(vy, vm, vd)];
} else if (rangePreset === 'This week') {
  bounds = [dayStart(vy, vm, vd - backToMonday), dayEnd(vy, vm, vd - backToMonday + 6)];
} else if (rangePreset === 'This month') {
  bounds = [dayStart(vy, vm, 1), dayEnd(vy, vm + 1, 0)];
} else if (rangePreset === 'Custom') {
  var cs = toEpochMs(customStartRaw);
  var ce = toEpochMs(customEndRaw);
  if (cs !== null && ce !== null) {
    var s = new Date(cs);
    var e = new Date(ce);
    // Whole days in the viewer's zone: from the start day's 00:00 to the end day's 23:59:59.999.
    bounds = [dayStart(s.getFullYear(), s.getMonth(), s.getDate()), dayEnd(e.getFullYear(), e.getMonth(), e.getDate())];
  } else {
    // While the picker holds only one end, show today.
    bounds = [dayStart(vy, vm, vd), dayEnd(vy, vm, vd)];
  }
}
// 'All time' or nothing selected: no date filter.

// One rule for the list and every count: does this row show under the filter
// bar, with `tab` as the type tab?
function matches(row, tab) {
  var f = fieldsOf(row);
  var skipped = isSkipped(row);

  // "Skipped" narrows to skipped tasks; "All" and the type tabs show skipped
  // and completed tasks too. Types compare case-insensitively.
  if (tab === 'Skipped') {
    if (!skipped) {
      return false;
    }
  } else if (tab !== 'All' && String(f.taskType || '').trim().toLowerCase() !== tab.toLowerCase()) {
    return false;
  }

  if (rangePreset === 'Overdue') {
    if (!isOverdue(row)) {
      return false;
    }
  } else if (bounds) {
    var ms = dueOf(row);
    if (ms === null || ms < bounds[0] || ms > bounds[1]) {
      return false;
    }
  }

  if (sourceFilter !== 'All') {
    var isAuto = String(f.source || '').toLowerCase() !== 'manual';
    if (sourceFilter === 'Automated' && !isAuto) {
      return false;
    }
    if (sourceFilter === 'Manual' && isAuto) {
      return false;
    }
  }

  if (priorityFilter !== 'All') {
    if (String(f.priority || '').trim().toLowerCase() !== priorityFilter.toLowerCase()) {
      return false;
    }
  }

  if (statusFilter !== 'All') {
    if (statusFilter === 'Due' && !isDueNotYet(row)) {
      return false;
    }
    if (statusFilter === 'Overdue' && !isOverdue(row)) {
      return false;
    }
    if (statusFilter === 'Completed' && !isCompleted(row)) {
      return false;
    }
    if (statusFilter === 'Skipped' && !skipped) {
      return false;
    }
    if (statusFilter === 'Pending' && !(statusOf(row) === 'pending' && !skipped)) {
      return false;
    }
    if (statusFilter === 'Cancelled' && !isCancelled(row)) {
      return false;
    }
    if (statusFilter === 'Paused' && statusOf(row) !== 'paused') {
      return false;
    }
  }

  if (searchFilter) {
    var generic = f.generic || {};
    var haystack = [
      f.stepTitle,
      generic.taskName,
      f.prospectName,
      f.accountName,
      f.taskType,
      f.source,
      f.sequenceName
    ];
    var hit = haystack.some(function (value) {
      return String(value || '').toLowerCase().includes(searchFilter);
    });
    if (!hit) {
      return false;
    }
  }

  return true;
}

return objects.filter(function (row) {
  return matches(row, typeTab);
});

