const rows = {{ e_6a69bef6c0cadb553b40e45b['data'] }} || [];
const days = rows
  .map(function (row) { return Date.parse(row && row['date']); })
  .filter(function (time) { return !isNaN(time); });
if (!days.length) {
  return undefined;
}
const halfDay = 12 * 60 * 60 * 1000;
return {
  min: Math.min.apply(null, days) - halfDay,
  max: Math.max.apply(null, days) + halfDay,
};

func_VJ05t.functionBody:
// Opportunities tab rows -> Active sequences (IN_PROGRESS enrolments of the opportunity's prospects)
// and Next meeting (soonest upcoming sdr_calendar meeting), keyed by opportunity record id (row id).
const opps = ({{ e_6a4e7b7fd9254572003310da['data'] }} || {}).objects || [];
const prospData = {{ e_6adc9e8d0881d2257a29a115['data'] }};
const prospLoading = {{ e_6adc9e8d0881d2257a29a115['isLoading'] }} === true;
const prospError = {{ e_6adc9e8d0881d2257a29a115['error'] }};
const enrData = {{ e_6adc9e9e0881d2257a29a245['data'] }};
const enrLoading = {{ e_6adc9e9e0881d2257a29a245['isLoading'] }} === true;
const enrError = {{ e_6adc9e9e0881d2257a29a245['error'] }};
const mtgData = {{ e_6adc9e9e925d282255f23773['data'] }};
const mtgLoading = {{ e_6adc9e9e925d282255f23773['isLoading'] }} === true;
const mtgError = {{ e_6adc9e9e925d282255f23773['error'] }};
const now = new Date();
const nowMs = now.getTime();

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function clock(date) {
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const suffix = hours < 12 ? 'am' : 'pm';
  const hour12 = hours % 12 === 0 ? 12 : hours % 12;
  return hour12 + (minutes ? ':' + String(minutes).padStart(2, '0') : '') + suffix;
}

function formatMeeting(ms) {
  const d = new Date(ms);
  const year = d.getFullYear() === now.getFullYear() ? '' : ' ' + d.getFullYear();
  return WEEKDAYS[d.getDay()] + ' ' + d.getDate() + ' ' + MONTHS[d.getMonth()] + year + ', ' + clock(d);
}

function sfIdsOf(o) {
  const p = (o && o.properties) || {};
  return [].concat(p.prospect_ids || [], p.prospect_id || []).filter(Boolean);
}

const anySfIds = opps.some(function (o) { return sfIdsOf(o).length > 0; });

// Prospect SF id -> prospect record ids (enrolments and meetings hold the record id).
const recordsBySf = {};
((prospData || {}).objects || []).forEach(function (r) {
  const sf = (r.properties || {}).prospectId;
  if (sf) {
    (recordsBySf[sf] = recordsBySf[sf] || []).push(r.id);
  }
});
const anyRecords = Object.keys(recordsBySf).length > 0;

function recordIdsOf(o) {
  const out = {};
  sfIdsOf(o).forEach(function (sf) {
    (recordsBySf[sf] || []).forEach(function (id) { out[id] = true; });
  });
  return Object.keys(out);
}

let prospPending = '';
if (anySfIds) {
  if (prospError) {
    prospPending = '—';
  } else if (prospLoading || !prospData) {
    prospPending = '…';
  }
}

let activePending = prospPending;
if (!activePending && anyRecords) {
  if (enrError) {
    activePending = '—';
  } else if (enrLoading || !enrData) {
    activePending = '…';
  }
}

const enrolmentsByProspect = {};
((enrData || {}).objects || []).forEach(function (e) {
  const p = e.properties || {};
  if (p.prospectId && p.status === 'IN_PROGRESS') {
    (enrolmentsByProspect[p.prospectId] = enrolmentsByProspect[p.prospectId] || {})[e.id] = true;
  }
});

let meetingPending = '';
if (opps.length > 0) {
  if (mtgError) {
    meetingPending = '—';
  } else if (prospPending === '…' || mtgLoading || !mtgData) {
    meetingPending = '…';
  }
}

const upcoming = ((mtgData || {}).objects || []).filter(function (m) {
  const p = m.properties || {};
  const start = Number(p.startEpochOfCall || 0);
  const deleted = p.isDeleted === true || p.isDeleted === 'true';
  const cancelled = /^cancel/i.test(String(p.status || ''));
  return start >= nowMs && !deleted && !cancelled;
});

const activeSequences = {};
const nextMeeting = {};
const nextMeetingVia = {};
opps.forEach(function (o) {
  const recIds = recordIdsOf(o);
  const seen = {};
  recIds.forEach(function (rid) {
    Object.keys(enrolmentsByProspect[rid] || {}).forEach(function (eid) { seen[eid] = true; });
  });
  activeSequences[o.id] = String(Object.keys(seen).length);

  const byOpp = upcoming.filter(function (m) { return (m.properties || {}).opportunityId === o.id; });
  const byProspect = upcoming.filter(function (m) {
    const p = m.properties || {};
    return !p.opportunityId && recIds.indexOf(p.prospectId) !== -1;
  });
  const pool = byOpp.length ? byOpp : byProspect;
  if (pool.length) {
    const soonest = pool.reduce(function (a, b) {
      return Number(a.properties.startEpochOfCall) <= Number(b.properties.startEpochOfCall) ? a : b;
    });
    nextMeeting[o.id] = formatMeeting(Number(soonest.properties.startEpochOfCall));
    nextMeetingVia[o.id] = byOpp.length ? 'opportunity' : 'prospect';
  }
});

return {
  activePending: activePending,
  meetingPending: meetingPending,
  activeSequences: activeSequences,
  nextMeeting: nextMeeting,
  nextMeetingVia: nextMeetingVia,
};

