func_LZ4Xw.functionBody:
const rows = {{ e_6adef7586e8cff53facf3ac4['data']['objects'] }} || [];
const total = rows.length;
let healthy = 0;
let atRisk = 0;
rows.forEach(function (row) {
  const score = row['properties'] && row['properties']['healthScore'];
  if (score === null || score === undefined || score === '') {
    return;
  }
  if (Number(score) >= 75) {
    healthy = healthy + 1;
  } else {
    atRisk = atRisk + 1;
  }
});

return {
  total: total,
  healthy: healthy,
  atRisk: atRisk,
};

