// template_list: what the empty card grid says (one empty view reads this).
// Precedence: search -> filter -> channel tab -> nothing yet.
var q = String({{ b_bqiJr['value'] }} || '').trim();
var tab = String({{ var_o3h52['value'] }} || 'All');
var st = {{ b_pF0zF['state'] }} || {};
var fs = '';
try {
  fs = JSON.stringify(st.filter || '');
} catch (e) {
  fs = '';
}
var hasFilter = /"value"/.test(fs);
var channel = tab === 'Linkedin' ? 'LinkedIn' : tab;

var title = 'No templates yet';
var message = 'Create a template to reuse emails, LinkedIn messages and call scripts.';
var icon = 'File02';
var showCreate = true;

if (q) {
  var shown = q.length > 40 ? q.slice(0, 40) + '…' : q;
  title = 'No templates match "' + shown + '"';
  message = 'Try a different word, tab or filter.';
  icon = 'SvgSearchMd';
  showCreate = false;
} else if (hasFilter) {
  title = 'No templates match these filters';
  message = 'Change or clear the filters to see more templates.';
  icon = 'FilterLines';
  showCreate = false;
} else if (tab.toUpperCase() !== 'ALL') {
  title = 'No ' + channel + ' templates yet';
  message = 'Create one, or switch to All to see every channel.';
}

return {
  title: title,
  message: message,
  icon: icon,
  showCreate: showCreate ? 'true' : 'false',
};

func_rSz9h.functionBody:
// Access user information
const ctx = {{ userContext }} || {};

function getDisplayName(user) {
  const email = user?.contactDetails?.email;
  const username = user?.username;

  // "john.doe_smith" -> "John Doe Smith"
  const toName = (str) =>
    String(str)
      .replace(/\d+/g, '')
      .split(/[._-]+/)
      .filter(Boolean)
      .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
      .join(' ');

  // 1. Try the email
  if (email && email.includes('@')) {
    const name = toName(email.split('@')[0]);
    if (name) return name;
  }

  // 2. Try the username
  if (username) {
    const base = username.includes('@') ? username.split('@')[0] : username;
    if (/[._-]/.test(base)) {
      const name = toName(base);
      if (name) return name;
    }
    // 3. Can't parse it, so return the username as-is
    return username;
  }

  return '';
}

return getDisplayName(ctx);

