// Template history drawer: User and Action filter menus (options from thGetAuditLog's users/actions, drafts, labels).
const ds = {{ e_6ade00b7925d2822552c9fc1?.['data'] }} || {};
const appliedUsers = {{ var_SDJx1['value'] }} || [];
const appliedActions = {{ var_z8tJ7['value'] }} || [];
const userDraft = {{ var_5qfxG['value'] }} || [];
const actionDraft = {{ var_5aVzY['value'] }} || [];
const rawUsers = Array.isArray(ds.users) ? ds.users : [];
const rawActions = Array.isArray(ds.actions) ? ds.actions : [];

const users = rawUsers.map(function (user) {
  const id = String(user.id);
  return {
    id: id,
    name: user.name || id,
    checked: userDraft.indexOf(id) >= 0
  };
});

const groups = [];
const groupIndex = {};
rawActions.forEach(function (action) {
  const group = action.group || 'Other';
  if (groupIndex[group] === undefined) {
    groupIndex[group] = groups.length;
    groups.push({ key: group, label: group, items: [] });
  }
  groups[groupIndex[group]].items.push({
    code: String(action.code),
    label: action.label || action.code,
    checked: actionDraft.indexOf(String(action.code)) >= 0
  });
});

function nameOf(id) {
  const hit = users.filter(function (user) { return user.id === String(id); })[0];
  return hit ? hit.name : String(id);
}

function labelOf(code) {
  const hit = rawActions.filter(function (action) { return String(action.code) === String(code); })[0];
  return hit ? (hit.label || hit.code) : String(code);
}

const userLabel = 'User: ' + (appliedUsers.length === 0 ? 'All' : (appliedUsers.length === 1 ? nameOf(appliedUsers[0]) : appliedUsers.length));
