  {{ e_6a4cca1b2dae9d196020c5ef?.['data']?.['objects'] }}
];
const used = {};
let original = '';
for (let i = 0; i < pools.length; i++) {
  const rows = Array.isArray(pools[i]) ? pools[i] : [];
  for (let j = 0; j < rows.length; j++) {
    const row = rows[j];
