// Template history drawer: shapes the SDR | Get Audit Log answer (data source thGetAuditLog) for the drawer.
const ds = {{ e_6ade00b7925d2822552c9fc1?.['data'] }};
const dsError = {{ e_6ade00b7925d2822552c9fc1?.['error'] }};
const dsLoading = {{ e_6ade00b7925d2822552c9fc1?.['isLoading'] }};
const scope = {{ var_JpKNs['value'] }} || 'list';
const rawRange = String({{ var_RIWF0['value'] }} || '');
const search = String({{ var_Gp8IO['value'] }} || '').trim();
const data = (ds && typeof ds === 'object') ? ds : {};
const today = new Date();
const pad = function (n) { return String(n).padStart(2, '0'); };
const dayKeyOf = function (d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); };
const anchor = dayKeyOf(today);
const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const channelLabels = { linkedin: 'LinkedIn', email: 'Email', call: 'Call' };
const scopedText = {
  template_created: 'Created template',
  template_deleted: 'Deleted template',
  template_version_created: 'Created new version',
  template_approved: 'Approved template',
  template_rejected: 'Rejected template',
  template_sharing_changed: 'Changed sharing',
  template_pinned: 'Pinned template',
  template_unpinned: 'Unpinned template'
};

function shiftDays(key, days) {
  const d = new Date(key + 'T00:00:00');
  d.setDate(d.getDate() + days);
  return dayKeyOf(d);
}

function isDayKey(text) {
  return /^\d{4}-\d{2}-\d{2}$/.test(text);
}

function dayText(key) {
  const parts = key.split('-');
  const label = months[Number(parts[1]) - 1] + ' ' + Number(parts[2]);
  return parts[0] === anchor.slice(0, 4) ? label : label + ', ' + parts[0];
}

const defaultFrom = shiftDays(anchor, -29);
const defaultTo = anchor;
let fromKey = defaultFrom;
let toKey = defaultTo;
const pieces = rawRange.split('|');
const isCustomRange = pieces.length === 2 && isDayKey(pieces[0]) && isDayKey(pieces[1]);
if (isCustomRange) {
  fromKey = pieces[0] <= pieces[1] ? pieces[0] : pieces[1];
  toKey = pieces[0] <= pieces[1] ? pieces[1] : pieces[0];
}
const localRange = !isCustomRange
  ? 'last 30 days'
  : (fromKey === toKey ? dayText(fromKey) : dayText(fromKey) + ' – ' + dayText(toKey));
const rangeLabel = data.rangeLabel || localRange;

function escMd(text) {
  return String(text || '').replace(/([\\`*_\[\]#<>])/g, '\\$1');
}

function editText(entry) {
  const first = (entry.changeRows || [])[0] || {};
  const field = String(first.field || '').toLowerCase();
  if (field === 'name') {
    return 'Renamed template';
  }
  if (field) {
    return 'Edited ' + field;
  }
  return 'Edited template';
}

function shape(entry) {
  const rows = (entry.changeRows || []).map(function (row, index) {
    const kind = row.isLongText ? 'long' : (row.before ? 'change' : 'value');
    return {
      key: entry.id + '_' + index,
      field: row.field,
      before: row.before == null ? '' : String(row.before),
      after: row.after == null ? '' : String(row.after),
      kind: kind,
      entityName: entry.entityName || '',
      timeLabel: entry.timeLabel || '',
      actorName: entry.actorName || ''
    };
  });
  if (entry.note) {
    rows.push({ key: entry.id + '_note', field: entry.action === 'template_rejected' ? 'Reason' : 'Note', before: '', after: entry.note, kind: 'value' });
  }
  const modalText = entry.scopedActionText || scopedText[entry.action] || (entry.action === 'template_edited' ? editText(entry) : entry.actionText);
  const text = scope === 'modal'
    ? escMd(modalText)
    : escMd(entry.actionText) + ' **' + escMd(entry.entityName) + '**';
  const channel = String(entry.channel || '').toLowerCase();
  const channelLabel = entry.channelLabel || channelLabels[channel] || (channel ? channel.charAt(0).toUpperCase() + channel.slice(1) : '');
  const channelKey = channel || String(channelLabel).toLowerCase();
  return Object.assign({}, entry, {
    actionMd: text,
    rows: rows,
    hasBox: rows.length > 0,
    hasVersion: Boolean(entry.versionLabel),
    channel: channelKey,
    channelLabel: channelLabel
  });
}

const groups = (Array.isArray(data.groups) ? data.groups : [])
  .map(function (group) {
    return { dayKey: group.dayKey, dayLabel: group.dayLabel, entries: (group.entries || []).map(shape) };
  })
  .filter(function (group) { return group.entries.length > 0; });
const shown = groups.reduce(function (sum, group) { return sum + group.entries.length; }, 0);
const total = typeof data.total === 'number' ? data.total : shown;
const pickedFilters = (({{ var_SDJx1['value'] }} || []).length + ({{ var_z8tJ7['value'] }} || []).length) > 0;
const hasFilters = isCustomRange || (scope !== 'modal' && search.length > 0) || pickedFilters;
const failed = Boolean(dsError) || data.status === 'error';
let state = 'ready';
if (failed) {
  state = 'error';
} else if (dsLoading === true || !ds) {
  state = 'loading';
} else if (total === 0 && hasFilters) {
  state = 'nomatch';
} else if (total === 0) {
  state = 'empty';
}
const errorText = failed
  ? ((dsError && dsError.message) || data.message || 'Could not load history.')
  : '';
const countLabel = state === 'loading'
  ? 'Loading history…'
  : (data.countLabel || (total + (total === 1 ? ' event' : ' events') + ' · ' + rangeLabel));

return {
  state: state,
  groups: state === 'ready' ? groups : [],
  total: total,
  countLabel: countLabel,
  rangeLabel: rangeLabel,
  fromKey: fromKey,
  toKey: toKey,
  isCustomRange: isCustomRange,
  hasFilters: hasFilters,
  errorText: errorText,
  canExport: state === 'ready' && total > 0
};

