func_5Tf2w.functionBody:
// Access user information
const ctx = {{ userContext }} || {};

function getDisplayName(user) {
  const email = user?.contactDetails?.email;
  const username = user?.username;

  // "john.doe_smith" -> "John Doe Smith"
  const toName = (str) =>
    String(str)
      .replace(/\d+/g, '')
      .split(/[._-]+/)
      .filter(Boolean)
      .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
      .join(' ');

  // 1. Try the email
  if (email && email.includes('@')) {
    const name = toName(email.split('@')[0]);
    if (name) return name;
  }

  // 2. Try the username
  if (username) {
    const base = username.includes('@') ? username.split('@')[0] : username;
    if (/[._-]/.test(base)) {
      const name = toName(base);
      if (name) return name;
    }
    // 3. Can't parse it, so return the username as-is
    return username;
  }

  return '';
}

return getDisplayName(ctx);

func_lbbXP.functionBody:
// Live preview for the Add Variable modal
const catFn = {{ func_uoB35 }};
const cat = (catFn && catFn.value) || {};
const sel = cat.selected || null;
const fbBlock = {{ b_sh35P }};
const fallback = (fbBlock && fbBlock.value) || '';
const behaviour = {{ var_xz57L['value'] }} || 'optional';
const pd = {{ e_6ad10502875ed2429a95a5c7['data'] }};
const prospectRows = (pd && Array.isArray(pd.objects)) ? pd.objects : [];
const ad = {{ e_6ad10502875ed2429a95a5c5['data'] }};
const accountRows = (ad && Array.isArray(ad.objects)) ? ad.objects : [];

if (!sel) {
  return {
    token: 'Pick a field',
    tokenText: 'No field selected',
    fieldState: 'none',
    ifExists: 'Pick a field to see an example.',
    ifMissing: '—',
    missState: 'plain',
    hasSample: false,
    footerHint: 'Pick a field to continue.'
  };
}

let sample = null;
if (sel.salesforceObject === 'User') {
  sample = sel.label;
} else {
  const row = sel.salesforceObject === 'Account' ? accountRows[0] : prospectRows[0];
  const v = row && row.properties ? row.properties[sel.sourceField] : null;
  if (v !== null && v !== undefined && v !== '' && !(Array.isArray(v) && v.length === 0)) {
    sample = Array.isArray(v) ? v.join(', ') : (typeof v === 'object' ? JSON.stringify(v) : String(v));
  }
}

const token = '{' + sel.uniqueId + '}';
const required = behaviour === 'required';

return {
  token: token,
  tokenText: token,
  fieldState: 'picked',
  ifExists: (sample !== null ? sample : sel.label),
  ifMissing: required ? 'This email will not be sent.' : (fallback ? fallback : '[fallback]'),
  missState: required ? 'warn' : 'plain',
  hasSample: sample !== null,
  footerHint: 'Ready to add ' + token
};

