func_uoB35.functionBody:
// Fixed variable catalog (spec Catalog). One entry per Object + uniqueId.
// cl = [uniqueId, label, sourceField, contactKey, leadKey]
const cl = [
  ['firstName', 'First Name', 'firstName', 'FirstName', 'FirstName'],
  ['lastName', 'Last Name', 'lastName', 'LastName', 'LastName'],
  ['prospectName', 'Full Name', 'prospectName', 'Name', 'Name'],
  ['prospectEmail', 'Email', 'prospectEmail', 'Email', 'Email'],
  ['prospectDesignation', 'Job Title', 'prospectDesignation', 'Title', 'Title'],
  ['prospectDepartment', 'Department', 'prospectDepartment', 'Contact_Role__c', 'Contact_Role__c'],
  ['prospectPhone', 'Phone', 'prospectPhone', 'Phone', 'Phone'],
  ['mobilePhone', 'Mobile Phone', 'mobilePhone', 'MobilePhone', 'MobilePhone'],
  ['salutation', 'Salutation', 'salutation', 'Salutation', 'Salutation'],
  ['prospectLinkedin', 'LinkedIn URL', 'prospectLinkedin', '', ''],
  ['leadSource', 'Lead Source', 'LeadSource', 'LeadSource', 'LeadSource'],
  ['address', 'Address', 'address', 'MailingStreet', 'Street'],
  ['city', 'City', 'city', 'MailingCity', 'City'],
  ['state', 'State', 'state', 'MailingState', 'State'],
  ['country', 'Country', 'country', 'MailingCountry', 'Country'],
  ['postalCode', 'Postal Code', 'postalCode', 'MailingPostalCode', 'PostalCode'],
  ['accountName', 'Company Name', 'accountName', 'Account.Name', 'Company'],
  ['reportsToName', 'Reports To', 'reportsToName', 'ReportsTo.Name', 'ReportsTo.Name'],
  ['lastContacted', 'Last Contacted', 'lastContacted', 'LastActivityDate', 'LastActivityDate'],
  ['recent_achievement', 'Recent Achievement', 'recent_achievement', 'Recent_Achievement__c', 'Recent_Achievement__c'],
  ['pain_point', 'Pain Point', 'pain_point', '', '']
];
// [uniqueId, label, sourceField, salesforceKey]
const acc = [
  ['industry', 'Industry', 'industryTag', 'Industry'],
  ['companyWebsite', 'Company Website', 'companyWebSite', 'Website'],
  ['companyPhone', 'Company Phone', 'companyPhone', 'Phone'],
  ['annualRevenue', 'Annual Revenue', 'annualRevenue', 'AnnualRevenue'],
  ['companySize', 'Company Size', 'companySize', 'NumberOfEmployees'],
  ['accountType', 'Account Type', 'accountType', 'Type']
];
const usr = [
  ['senderName', 'Sender Name', 'senderName', 'SenderName'],
  ['senderEmail', 'Sender Email', 'senderEmail', 'SenderEmail'],
  ['senderDesignation', 'Sender Designation', 'senderDesignation', 'SenderTitle'],
  ['senderPhoneNumber', 'Sender Phone Number', 'senderPhoneNumber', 'SenderPhone'],
  ['senderCompanyName', 'Sender Company Name', 'senderCompanyName', 'SenderCompany']
];

const entries = [];
cl.forEach(r => {
  entries.push({ salesforceObject: 'Contact', uniqueId: r[0], label: r[1], sourceField: r[2], salesforceKey: r[3] });
  entries.push({ salesforceObject: 'Lead', uniqueId: r[0], label: r[1], sourceField: r[2], salesforceKey: r[4] });
});
acc.forEach(r => entries.push({ salesforceObject: 'Account', uniqueId: r[0], label: r[1], sourceField: r[2], salesforceKey: r[3] }));
usr.forEach(r => entries.push({ salesforceObject: 'User', uniqueId: r[0], label: r[1], sourceField: r[2], salesforceKey: r[3] }));

// uniqueIds already saved in SDR | Variable For Templates (fetch_variables)
const fv = {{ e_6a4cca1b2dae9d196020c5eb['data'] }};
const rows = (fv && Array.isArray(fv.objects)) ? fv.objects : [];
const existing = rows.map(r => r && r.properties && r.properties.uniqueId).filter(Boolean);

// Current picks in the Add Variable form
const formBlock = {{ b_3G6Cc }};
const formData = (formBlock && formBlock.data) || {};
const object = formData.field1 || 'Contact';
const picked = formData.field2;

const fieldOptions = entries
  .filter(e => e.salesforceObject === object)
  .map(e => {
    const added = existing.indexOf(e.uniqueId) !== -1;
    return {
      value: e.uniqueId,
      label: e.label + ' {' + e.uniqueId + '}' + (added ? ' · already added' : ''),
      disabled: added
    };
  });

const selected = entries.find(e => e.salesforceObject === object && e.uniqueId === picked && existing.indexOf(e.uniqueId) === -1) || null;

return { object: object, entries: entries, existing: existing, fieldOptions: fieldOptions, selected: selected };

func_UHPmI.functionBody:
// Audit payload for SDR | Log Audit Event.
// Reads only the snapshot taken when the Publish modal opens (var templateAuditSnapshot),
// so the template refetch after a publish cannot change it. Never throws.
const off = { logEdit: false, logVersion: false };
try {
  const snap = {{ var_P4kCF['value'] }};
  if (!snap || typeof snap !== 'object') {
    return off;
  }

  function toText(value) {
    return String(value ?? '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|h[1-6])>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&amp;/g, '&')
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  const isNew = snap.isNew === true || String(snap.isNew) === 'true';
  const entityId = String(snap.templateId ?? '');
  if (isNew || !entityId) {
    return off;
  }

  const before = {
    name: String(snap.beforeName ?? '').trim(),
    subject: String(snap.beforeSubject ?? '').trim(),
    body: toText(snap.beforeBody),
  };
  const after = {
    name: String(snap.afterName ?? '').trim(),
    subject: String(snap.afterSubject ?? '').trim(),
    body: toText(snap.afterBody),
  };

  const changed = ['name', 'subject', 'body'].filter(function (key) {
    return before[key] !== after[key];
  });
  let fieldsText = '';
  if (changed.length === 1) {
    fieldsText = changed[0];
  } else if (changed.length > 1) {
    fieldsText = changed.slice(0, -1).join(', ') + ' and ' + changed[changed.length - 1];
  }

  const current = Number(snap.currentVersion);
  const versionFrom = isNaN(current) ? 0 : current;

  return {
    entityId: entityId,
    entityName: after.name || before.name,
    before: before,
    after: after,
    changedFields: changed,
    actionText: fieldsText ? 'Edited ' + fieldsText + ' of' : 'Edited',
    logEdit: changed.length > 0,
    logVersion: true,
    versionFrom: versionFrom,
    versionTo: versionFrom + 1,
  };
} catch (e) {
  return off;
}

func_8jKFQ.functionBody:
// Access template information
const template = {{ e_6a4cca1b2dae9d196020c5ec }} || {};

function getNextVersion(tpl) {
  const current = Number(tpl?.data?.properties?.currentVersion);

  // No version yet (missing, undefined or not a number), so start at V1
  if (isNaN(current)) return 'V1';

  return `V${current + 1}`;
}

return getNextVersion(template);

