const objects = (data && data.objects) || [];

function formatDisplayTime(raw) {
  if (!raw) return '';
  const bits = String(raw).split(':');
  let hour = parseInt(bits[0], 10);
  if (isNaN(hour)) return '';
  const minute = (bits[1] || '00').padStart(2, '0');
  const ampm = hour >= 12 ? 'PM' : 'AM';
  let hour12 = hour % 12;
  if (hour12 === 0) hour12 = 12;
  return hour12 + ':' + minute + ' ' + ampm;
}

// The row's true instant, in epoch milliseconds, or null when the record
// carries none. This is the ordering key: the string `time` field is a
// wall-clock value many rows of one day share, so ordering on it put every
// card at the same moment.
function epochOf(p) {
  const raw = p.utcTimeEpoch;
  const n = typeof raw === 'number' ? raw : parseInt(String(raw == null ? '' : raw), 10);
  return isNaN(n) ? null : n;
}

// Fallback only, for a row with no utcTimeEpoch: converts the wall-clock
// `time` stamped in the record's own IANA zone into the true UTC instant,
// with the same two-pass Intl.DateTimeFormat probe scheduleViewerTimes
// (func_UHa5E) uses, so both kinds of row sort on one millisecond scale.
function zonedWallClockToMs(y, m, d, timeStr, timeZone) {
  if (!timeStr || !y || !m || !d) return null;
  try {
    const bits = String(timeStr).split('.');
    const hms = bits[0].split(':');
    const hh = parseInt(hms[0], 10) || 0;
    const mm = parseInt(hms[1], 10) || 0;
    const ss = parseInt(hms[2], 10) || 0;
    const ms = bits[1] ? parseInt((bits[1] + '000').slice(0, 3), 10) : 0;
    const guessUtcMs = Date.UTC(parseInt(y, 10), parseInt(m, 10) - 1, parseInt(d, 10), hh, mm, ss, ms);
    if (isNaN(guessUtcMs)) return null;
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: timeZone || 'UTC', hourCycle: 'h23',
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    }).formatToParts(new Date(guessUtcMs));
    const map = {};
    parts.forEach(function (part) { map[part.type] = part.value; });
    const zonedAsUtcMs = Date.UTC(
      parseInt(map.year, 10), parseInt(map.month, 10) - 1, parseInt(map.day, 10),
      parseInt(map.hour, 10), parseInt(map.minute, 10), parseInt(map.second, 10), ms
    );
    return guessUtcMs - (zonedAsUtcMs - guessUtcMs);
  } catch (e) {
    return null;
  }
}

// Shape the MEETING rows this source fetches — it calls the automation with
// taskType "Meeting", so the rail carries meetings only, not the whole queue
// — into the shape the schedule row template reads: time, title, sub,
// duration, taskType, isNowMarker, description, plus the utcTimeEpoch the
// order and the displayed time are both taken from.
// meetingType/eventType/attendees/meetingUrl are left undefined here on
// purpose: this source is the task record, not the calendar fetch the card
// used to read, so it carries none of those calendar-only fields, and the row
// template's own visibility checks on them already hide the attendee-count
// and Join chips when they are missing.
const rows = objects.map(function (obj) {
  const p = (obj && obj.properties) || {};
  const taskType = p.taskType || 'Generic';
  const isMeeting = taskType === 'Meeting';
  const meetingInfo = (isMeeting && p.meetings) || {};
  const title = isMeeting
    ? (meetingInfo.meetingTitle || meetingInfo.title || p.reasonOfTask || 'Meeting')
    : (p.reasonOfTask || taskType);
  const sub = [p.prospectName, p.accountName].filter(Boolean).join(' · ');
  const epoch = epochOf(p);

  return {
    id: obj.id,
    sortKey: p.time || '',
    sortMs: epoch !== null ? epoch : zonedWallClockToMs(p.year, p.month, p.day, p.time, p.timeZone),
    utcTimeEpoch: epoch,
    timeZone: p.timeZone || '',
    time: formatDisplayTime(p.time),
    title: title,
    sub: sub,
    duration: '',
    taskType: taskType,
    description: p.reasonOfTask || '',
    isNowMarker: false
  };
});

// Ascending by utcTimeEpoch (sortMs carries it, or the converted wall clock
// where the record had none). A row with no usable time at all sits last
// rather than jumping to the top of the day.
rows.sort(function (a, b) {
  if (a.sortMs === null && b.sortMs === null) {
    if (a.sortKey < b.sortKey) return -1;
    if (a.sortKey > b.sortKey) return 1;
    return 0;
  }
  if (a.sortMs === null) return 1;
  if (b.sortMs === null) return -1;
  return a.sortMs - b.sortMs;
});

// Insert a synthetic "now" row at its correct chronological slot, the same
// way the calendar-only card used to get one from the automation — done
// here instead, since the automation cannot be changed. Skipped entirely
// when there are no rows, so an empty day shows the empty state rather
// than a lone "Now" row.
if (rows.length > 0) {
  const zoneCarrier = rows.find(function (r) { return r.timeZone; });
  const zone = (zoneCarrier && zoneCarrier.timeZone) || 'UTC';
  const nowMs = Date.now();

  let nowSortKey = '';
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      hour: '2-digit', minute: '2-digit', second: '2-digit',
      hour12: false, timeZone: zone
    }).formatToParts(new Date());
    const map = {};
    parts.forEach(function (part) { map[part.type] = part.value; });
    const hh = map.hour === '24' ? '00' : map.hour;
    nowSortKey = hh + ':' + map.minute + ':' + map.second + '.000';
  } catch (e) {
    const now = new Date();
    nowSortKey = String(now.getUTCHours()).padStart(2, '0') + ':' +
      String(now.getUTCMinutes()).padStart(2, '0') + ':' +
      String(now.getUTCSeconds()).padStart(2, '0') + '.000';
  }

  // The Now row's DISPLAYED time follows the viewer's own device/browser
  // timezone, detected dynamically — never the records' timeZone, which is
  // what this row's chronological POSITION among the real tasks still uses
  // (now against each row's own instant). Changing the display zone here
  // does not change where this row lands in the list.
  let nowDisplayTime = '';
  try {
    const deviceZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (!deviceZone) throw new Error('no device timezone resolved');
    const dParts = new Intl.DateTimeFormat('en-US', {
      hour: '2-digit', minute: '2-digit',
      hour12: false, timeZone: deviceZone
    }).formatToParts(new Date());
    const dMap = {};
    dParts.forEach(function (part) { dMap[part.type] = part.value; });
    const dHour = dMap.hour === '24' ? '00' : dMap.hour;
    nowDisplayTime = formatDisplayTime(dHour + ':' + dMap.minute);
  } catch (e) {
    try {
      const fParts = new Intl.DateTimeFormat('en-US', {
        hour: '2-digit', minute: '2-digit',
        hour12: false, timeZone: 'America/New_York'
      }).formatToParts(new Date());
      const fMap = {};
      fParts.forEach(function (part) { fMap[part.type] = part.value; });
      const fHour = fMap.hour === '24' ? '00' : fMap.hour;
      nowDisplayTime = formatDisplayTime(fHour + ':' + fMap.minute);
    } catch (e2) {
      nowDisplayTime = formatDisplayTime(nowSortKey);
    }
  }

  let insertAt = rows.findIndex(function (r) { return r.sortMs !== null && r.sortMs > nowMs; });
  if (insertAt === -1) insertAt = rows.length;

  rows.splice(insertAt, 0, {
    id: '__now__',
    sortKey: nowSortKey,
    sortMs: nowMs,
    utcTimeEpoch: null,
    timeZone: zone,
    time: nowDisplayTime,
    title: '',
    sub: '',
    duration: '',
    taskType: '',
    description: '',
    isNowMarker: true
  });
}

// Where this row sits on the rail: trims the vertical line above the first
// dot and below the last, so it does not overhang the card's padding —
// same convention the previous (meetings-only) build used.
rows.forEach(function (row, index) {
  row.railPosition = index === 0 ? 'first' : (index === rows.length - 1 ? 'last' : 'middle');
});

return { schedule: rows };

const today = new Date();
today.setHours(0, 0, 0, 0);

const start = new Date(today);
start.setDate(start.getDate() - 6);

// Pre-create all 7 days
const grouped = {};

for (let i = 0; i < 7; i++) {
  const d = new Date(start);
  d.setDate(start.getDate() + i);

  const date = d.toISOString().split("T")[0];

  grouped[date] = {
    date,
    in: 1,
    out: 0,
    dummy1: 1,
    dummy2: 2,
    outbound_count: 0,
    inbound_count: 0,
    outbound_activity: [],
    inbound_activity: []
  };
}

// Fill data
(data.objects || []).forEach(item => {
