      hour12: false, timeZone: deviceZone
    }).formatToParts(new Date());
    const dMap = {};
    dParts.forEach(function (part) { dMap[part.type] = part.value; });
    const dHour = dMap.hour === '24' ? '00' : dMap.hour;
    nowDisplayTime = formatDisplayTime(dHour + ':' + dMap.minute);
  } catch (e) {
    try {
      const fParts = new Intl.DateTimeFormat('en-US', {
        hour: '2-digit', minute: '2-digit',
        hour12: false, timeZone: 'America/New_York'
      }).formatToParts(new Date());
      const fMap = {};
      fParts.forEach(function (part) { fMap[part.type] = part.value; });
      const fHour = fMap.hour === '24' ? '00' : fMap.hour;
      nowDisplayTime = formatDisplayTime(fHour + ':' + fMap.minute);
    } catch (e2) {
      nowDisplayTime = formatDisplayTime(nowSortKey);
    }
  }

  let insertAt = rows.findIndex(function (r) { return r.sortMs !== null && r.sortMs > nowMs; });
  if (insertAt === -1) insertAt = rows.length;

  rows.splice(insertAt, 0, {
    id: '__now__',
    sortKey: nowSortKey,
    sortMs: nowMs,
    utcTimeEpoch: null,
    timeZone: zone,
    time: nowDisplayTime,
    title: '',
    sub: '',
    duration: '',
    taskType: '',
    description: '',
    isNowMarker: true
  });
}

// Where this row sits on the rail: trims the vertical line above the first
// dot and below the last, so it does not overhang the card's padding —
// same convention the previous (meetings-only) build used.
rows.forEach(function (row, index) {
  row.railPosition = index === 0 ? 'first' : (index === rows.length - 1 ? 'last' : 'middle');
});

return { schedule: rows };

const today = new Date();
today.setHours(0, 0, 0, 0);

const start = new Date(today);
start.setDate(start.getDate() - 6);

// Pre-create all 7 days
const grouped = {};

for (let i = 0; i < 7; i++) {
  const d = new Date(start);
  d.setDate(start.getDate() + i);

  const date = d.toISOString().split("T")[0];

  grouped[date] = {
    date,
    in: 1,
    out: 0,
    dummy1: 1,
    dummy2: 2,
    outbound_count: 0,
    inbound_count: 0,
    outbound_activity: [],
    inbound_activity: []
  };
}

// Fill data
(data.objects || []).forEach(item => {
  const p = item.properties || {};
  const bucket = grouped[p.activityDate];

  // Ignore dates outside last 7 days
  if (!bucket) return;

  const activity = {
    title: p.taskName || "Untitled Activity",
    time: p.startTime && p.startTime !== "-" ? p.startTime : "-",
    type: (p.taskType || p.taskSubType || "task").toLowerCase()
  };

  if (activity.type === "call" || activity.type === "meeting") {
    activity.attendees = Array.isArray(p.prospectId)
      ? p.prospectId.length
      : 1;

    activity.duration =
      p.startTime &&
      p.endTime &&
      p.startTime !== "-" &&
      p.endTime !== "-"
        ? `${p.startTime} - ${p.endTime}`
        : "-";
  } else {
    activity.participants = Array.isArray(p.prospectId)
      ? p.prospectId.length
      : 1;

    activity.detail =
      p.description ||
      p.taskFrom ||
      p.status ||
      "";
  }

  if (p.isInbound) {
    bucket.inbound_activity.push(activity);
    bucket.inbound_count++;
  } else {
    bucket.outbound_activity.push(activity);
    bucket.outbound_count++;
  }
});

// Always returns exactly 7 days
return Object.values(grouped).sort((a, b) => a.date.localeCompare(b.date));

