const mappedData = {};

data.objects.forEach(obj => {
  const prospectIds = obj?.properties?.prospectId;
  const status = obj?.properties?.Status;
  const isInbound = obj?.properties?.isInbound;
  const activityDateStr = obj?.properties?.activityDate;

  if (!prospectIds || !activityDateStr) return;

  const d = new Date(activityDateStr);
  if (isNaN(d.getTime())) return;

  const dateKey =
    d.getFullYear() + "-" +
    String(d.getMonth() + 1).padStart(2, "0") + "-" +
    String(d.getDate()).padStart(2, "0");

  if (!validDates.has(dateKey)) return;

  const idList = Array.isArray(prospectIds) ? prospectIds : [prospectIds];
  const newDirection = isInbound ? "prospect_to_account" : "account_to_prospect";

  idList.forEach(prospectId => {
    if (!prospectId) return;

    if (!mappedData[prospectId]) {
      mappedData[prospectId] = {};
    }

    const existing = mappedData[prospectId][dateKey];

    if (!existing) {
      mappedData[prospectId][dateKey] = {
        status: status ?? null,
        direction: newDirection
      };
    } else if (existing.direction !== newDirection && existing.direction !== "both") {
      mappedData[prospectId][dateKey] = {
        status: status ?? existing.status,
        direction: "both"
      };
    } else {
      mappedData[prospectId][dateKey] = {
        status: status ?? existing.status,
        direction: existing.direction
      };
    }
  });
});

return {
  mappedData
};

